/* 令和3年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r03.committeeSessions.push(...[{"id":"r03-20210921-7","meetingId":"r03-cm09","date":"2021年9月21日","dateIso":"2021-09-21","committee":"厚生委員会","time":"午前１０時００分～午前１１時５５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"現在の対応としては、もう変わっているのかについて伺いたいと思います。対応ガイドラインには具体的にいろいろ書いてあるのですけれども、「適切に」という答弁だけでしたので、その対応ガイドラインがどう適切に具体化されたのかについて伺いたいと思います。質問としては、常勤換算での人数を聞いたのですけれども、常勤換算でいいのかの確認をさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"私は審議している最中でも一向に構わないと思います。そのほうがリアルに撮れると思いますので。別に写真があったからといって、それが審査に影響を与えるわけではないので、写真はいつでも撮っていただいていいとしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"}]},{"id":"topic-02","title":"第６２号議案、専決処分の承認を求めること","agenda":"第６２号議案、専決処分の承認を求めること","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今回、休日や時間外ということで上乗せになることになったのですけれども、これは、個別接種の医療機関がやる分と考えていいのでしょうか。それは、これまでもやってきたものがあると思うのですけれども、これまで行ったものまで遡るのか、これからのことだけなのか、伺いたいと思います。その点についても伺いたいと思います。そこら辺の体制がどうなるのかについても伺いたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ですので、１週間当たり３,０００件掛ける２４週分。これが２医師会ありますので、掛ける２です。大体休日に実施していただく分が全体の３割程度と見込みまして、これに３０％を掛けまして、４万３,２００件という数字を算出いたしました。","id":"exchange-003"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"これそのものがすごく安いということで、マスコミでも指摘されていたことだと思うのですけれども、接種費用そのものを上げるべきではないかと思うのですが、国においてもそのような議論はなかったのでしょうか。インフルエンザは、１回大体５,０００円くらいの接種費用が医療機関に入ると伺ったのです。その１５人というのはどう出されてきたのかについても伺いたいと思います。","respondent":"鷹箸保健予防課長、豊嶋新型コロナウイルス予防接種担当課長","answer":"訪問診療に手を挙げていただいている医療機関ですけれども、順次増えてきている状況です。現状、既に行っていただいている医療機関は５医療機関となりますけれども、順次増えていっている状況になります。金額が安いのではないかですが、国からの通知によって２,２７７円が決まっているものです。インフルエンザとコロナウイルスの（ワクチンの）金額の差ですが、コロナワクチンは国から無償で提供されるものです。","id":"exchange-004"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"在宅のワクチン接種の費用というのは、今でも同じですか。もともとこの場でも、区が在宅の患者のワクチン接種に対しては支援すべきではないかということを提案してきました。オンライン診療の報酬はどうなっているのかについても伺いたいと思います。それから、病床のベッドを１床だけ確保するということでの補助金が計上されていますけれども、これがどのように活用されるのかを伺いたいのです。","respondent":"豊嶋新型コロナウイルス予防接種担当課長、秋山保健整備担当部長、鷹箸保健予防課長","answer":"１接種２,２７７円の単価については、国から示されているものですので、区でどうこうということは考えておりません。こちらも登録ドクターの数はどんどん増えていっている状況でございまして。","id":"exchange-005"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"よろしくお願いします。往診の時間単価で医師会から来るというのは聞いていなかったのですけれども、そうすると、１件当たりおよそ幾らぐらいになるという計算になるのか、分からないですか。では、ドクターがいろいろと予防接種で行くところの時間単価のお金も２,２７７円にプラスして出るという考え方でいいということなのですね。違うのですか。","respondent":"秋山保健整備担当部長","answer":"１人どのぐらいかというのは、それぞれケース・バイ・ケースになりますので分かりません。","id":"exchange-006"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"巡回接種の場合はそうなるのかと思うのですけれども、巡回接種だけではなくて、いつも往診しているドクターが在宅の患者にコロナワクチンの接種もするということもやっているのです。そういうところに対して２,２７７円だけということだったので、そこら辺は、それだけの負担に対しての報酬という形で検討すべきなのではないかという意見を申し上げました。","respondent":"秋山保健整備担当部長","answer":"かかりつけの方の接種につきましては、かかりつけの方の往診の診療報酬が入ると聞いておりますので、それと合わせて２,２７７円が接種費用としてが入ると医師会からは聞いております。","id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１回目は、そのように往診のついでにできるのですけれども、２回目のときはワクチンだけになって、ワクチンの接種費用しかとれないということを医療機関から聞いていましたので、少し質問をしたのです。そのようなところに向けて、ぜひ検討していただきたいということを要望だけします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問","question":"専決処分の承認について、私は賛成するつもりでいるので、その前提で少しお伺いしたいのです。","respondent":"高山健康課長","answer":"本件補正予算につきましては、第３回定例会の通常の補正予算の流れに乗せるべく、７月下旬から準備を進めていたところですが、このたびの第５波の急速な感染拡大に伴いまして、様々な所要経費が不足するということが見込まれましたので、そうした緊急性に照らしまして。","id":"exchange-009"},{"speaker":"高橋（し）委員","kind":"質問","question":"専決しようということになったのが８月の頭という話なのでしょうか。緊急を要することは理解していますので、それだけ。","respondent":"高山健康課長","answer":"まさに、本来であれば議会でご審議いただきまして、第３回定例会においてお認めいただくというのが通常の流れだと考えていたところですが、８月の上旬から中旬にかけまして、そうした緊急性に照らしまして、専決処分をさせていただきたいということで。","id":"exchange-010"},{"speaker":"若林委員","kind":"確認","question":"２点、確認だけ。先ほど、オンライン診療の話もあって、それぞれざっくり人数が出ておりますけれども、これについて、保健所が基点になっていると思うのですが、費用、オンライン診療、訪問診療、ここら辺のコントロールといいますか、判断や派遣する仕組みなど、総合的な自宅療養者への医療体制ということで、ここを確認します。防護服はどこかに配付するという意味なのでしょうか。以上、２点です。","respondent":"鷹箸保健予防課長","answer":"現状ですと、往診をお願いしている状況は、そこまで緊急性が高くない場合には、幸い、今まで使う必要がなく済んでおりますけれども、我々が１台確保して持っている入院病床のほうに患者を運ぶ。そのような流れで考えているところです。","id":"exchange-011"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私はもっと様々なところに十二分にやっていただきたいという思いはありますけれども、この専決処分については賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]},{"id":"topic-03","title":"令和３年請願第８号、加齢性難聴者の補聴器購入費用に対する公的補助を求める請願","agenda":"令和３年請願第８号、加齢性難聴者の補聴器購入費用に対する公的補助を求める請願","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"今、課長からもあったように、多分今回で５回目の請願だと思います。それで、本当に高齢化がどんどん進む中で、昨日は敬老の日でしたけれども、高齢化率が２９.１％ということで、さらにこの高齢化率は上がっていくだろう。認知症を予防するという観点からも、難聴に対する対策というものが必要ではないかと思うのですけれども、まずこの点についての区の認識を伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"厳密に言いますと、難聴がそのまま認知症ということではなく、もう一段階あって、難聴によってコミュニケーションが低下することによって、認知症状が起きやすいというのは、認知症そのものは、なかなか医学のほうでも難しいということは承知しているところなのですけれども。","id":"exchange-013"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私は、認知症に対しての対応というのは、これからもますます求められてくると思うのです。そして、難聴に対しては、きちんと調整してトレーニングをすれば補聴器が有効だということもこれだけ明らかになっているにもかかわらず、なぜそれを日常の対応というところで検討しないのかということを、改めて伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"認知症の対策、対応については、区も日々いろいろな取組を考えておりまして、実践でも行っております。","id":"exchange-014"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それに合わせて、最もリスクの高く、しかも予防可能なものが難聴になっているわけですから、専門家がしっかりとやるのが先でしょうと言っているだけではなくて、私は区としてもその対策に真正面から向き合っていくことがとても大事だと思います。聴力低下が見られる方への早期からの補聴器使用の重要性については、区としてどのように認識されているのか、伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"医学的なところについては、なかなか福祉部門が踏み込むのは難しいのですけれども、内容としてはそういったところです。","id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"本当にとことん悪くなってからの補聴器ということだと、もう脳が回復することができないので、聴力低下が見られる方に早期の補聴器使用が大事なのだと言われているのですけれども、その重要性についてはどう認識されていますかということを伺ったのです。早期の補聴器使用の重要性についてどう認識されているかという点についてはいかがですか。","respondent":"寺嶋福祉計画課長","answer":"今回の請願の内容につきましては、あくまでも補聴器について、保険適用がないというところでご指摘をいただいておりますので、それにつきましては、実際にご購入された方でも使っていないという事例があるので、やはり業界団体等々が言っているとおり。","id":"exchange-016"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そこの問題は共有しています。多分皆さんが共有されていると思うのです。ですから、それを具体的にどう進めていくのかということが大事なのです。この認識は、区としては東京都と同じ形で認識されてないということなのでしょうか。そのようなことを言っていることを文献で読んでいるというだけなのか、区としても同じ認識ということなのか、その点についても伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私は、東京都としても認識しているとはっきりと述べているわけですから、区としても認識をしていただきたいと改めて申し上げたいと思います。これを解決するためには、区としてはどうしたらいいと考えられているのか。専門的知見を持った補聴器相談員や、認定補聴器技能者に区民がアクセスしやすいように支援すべきだと思うのですけれども、その点についてはいかがでしょうか。","respondent":"寺嶋福祉計画課長","answer":"今、この段階で１区として何かできることがあるかというと、やはり我々は、日々窓口や実際の現場で接している方々とのコミュニケーションをしっかりとっていくことに最善を尽くすというのが一番正しい選択であろうと今の段階では思っております。","id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そこのところは、区としては一切関知しません、専門機関がやるところです、まずは医療機関と専門機関が普及・啓発、正しい使い方をやっていくべきで、区は関わりませんということでいいのかということを伺いたいと思います。そのために、私は購入費補助というのがその１つになっていくと思うのですけれども、区としては、専門機関がそれをやることがまず第一だと言われているのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そうすると、補聴器の購入費補助制度を創設するということは、区としてはどうやったらそれができるのではないかと考えられているのか、その点についてもお伺いいたします。","respondent":"寺嶋福祉計画課長","answer":"ここは、ある意味、役割分担だと考えております。その後のことにつきましては、そういったことがしっかり見受けられるようになった段階で、次にどういった施策が必要かというのは、その都度判断していく必要があろうかと考えます。","id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"補聴器の普及をすることの一番の課題の１つが、補聴器の金額が高いということだと思うのです。本当にお金がない人はとても補聴器を買えません。そういうことで、ぜひ購入費助成制度を区としてもつくっていただきたい。それから、どのようになったらこれを検討できるのかということも合わせて伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"いろいろなご意見があるということは、我々も承知しております。それから、先ほどと同じ回答ですが、まず、しっかり普及・啓発が進んでいるという段階を見極めることが重要だと考えております。","id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"東京都も明確に聞こえのバリアフリー、聞こえの支援については大事だということで、東京都としても取り組み出しているわけですから、この東京都と同じ立場になれば、補聴器の購入費助成制度をぜひつくっていただきたいと思います。改めて、補聴器購入費助成制度を東京都と同じ立場に立って、ぜひつくっていただきたいと思うのですけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私は、区が購入費補助制度をつくることによって普及・啓発も進むし、正しい補聴器のつけ方も、区が一緒になって取り組むことにつながると思います。そしてまた、高齢者の生活の質が保たれて、認知症も予防するというところで、これは何度も出てきていますので、これからも実現するまで請願・陳情が出され続けると思うのです。ぜひ一歩踏み出していただきたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"結論を出していただきたいと思います。我々も政策要望で出してきた、それを取り扱ってきた経緯もありますが、我々としては、やはり都の役割分担の中で、補助ということが、今、難聴の方々のコミュニケーションを確立していくという中で、それがプラスとも思っておりません。そういう意味では、今のこの段階で、我々は補助制度を創設するという結論には至っておりませんので、不採択といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"若林委員","kind":"意見","question":"今回、５回目ということで、過去４回、私たちの会派では、これを不採択にしている。その都度といいますか、特に一番最初のとき、私も審議に加わらせていただいたと思いますけれども、そのときの課題、区の見解はなかなか変化していない。社会情勢的にも大きく変化をしていないというところから、今回についてもこれまでと同じという結論で、不採択。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"せお委員","kind":"意見","question":"結論を出すで、不採択でお願いします。私は厚生委員会が初めてですので、今までの議事録を読ませていただきましたが、現状、今までの状況と現在とが変わっていないこと。先ほども自民党からもお話がありましたけれども、国や都、区で加齢性難聴者に対しての役割分担をすればいいと私も思っておりますので、こちらは不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"結論を出すということで、採択でお願いしたいと思います。日本の補聴器の使用率というのは、欧米諸国に比べて半分から３分の１というくらい大変遅れた状況になっているのです。なぜ遅れているのかと言えば、それは公的補助がないということが１点。ほかの１４自治体まで広がった補聴器購入費助成制度を、ぜひ品川区でもつくっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"木村委員","kind":"意見","question":"結論を出すで、不採択でお願いします。このように大変高価なものでもあります。１５万円から３０万円ということで、大変な金額でありますけれども、これは先ほどもお話がありましたが、大変聞こえづらい、使いづらいということで、これを使わない人もたくさんいるようであります。そういうことを考えますと、この請願に対しては不採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"高橋（し）委員","kind":"質問","question":"結論を出すで、不採択でお願いします。何度かこれと同じ請願を審議してきたことがありました。先ほど課長のご説明にもありましたように、状況に変化がないということや答弁で理解させていただきました。今回、このように費用を補助していくことに関して不採択ということで、理由としたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"}]},{"id":"topic-04","title":"の品川区立障害児者総合支援施設併設の医療系サービス","agenda":"の品川区立障害児者総合支援施設併設の医療系サービス","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"今、日本精神科看護協会の精神科クリニックが、障害児者総合支援施設の指定管理者が変わるのと同時に閉院になるというご報告があったわけなのですけれども、現在、日本精神科看護協会が品川区から場所を借りて行っている事業と、どういう職種の職員が何人いて、どれだけ勤務して、どのような中身の仕事をしているのかという現状を、まず教えていただけますか。","respondent":"築山障害者施策推進担当課長","answer":"事業につきましては、児童精神科もしくは精神科の外来診療を行っております。品川児童学園との連携を図るということで、相談等にも対応しています。","id":"exchange-030"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"陳情には、大人の精神科医を配置してくださいという要望が出されているのです。もともと日本精神科看護協会がやろうとしていた計画というのは、一番初めは指定管理という提案もあったと思うのです。そもそもの計画を改めて教えてください。","respondent":"築山障害者施策推進担当課長","answer":"当時の内容は、精神科クリニックと訪問看護の事業、それから、精神科クリニックではデイケアも入っておりました。対象者につきましては、特に具体的に大人限定、子ども限定ということはなかったです。","id":"exchange-031"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"そうすると、もともとの提案や計画からすると、精神科クリニックも児童精神科だけですし、訪問看護も結局ないのですか。ああ、こんなに広いところでデイケアがされるのだと、たしか４０人の定員と聞いた思いもあるのですけれども、そういうことで来たにもかかわらず、できなかった理由を区としてはどう考えられるでしょうか。その点についても伺います。","respondent":"築山障害者施策推進担当課長","answer":"ただ、今回、ご報告申し上げましたとおり、また、以前、精神科デイケアを見送るというご報告をさせていただいたときにもご説明させていただいたのですけれども、医師の確保が難しいというところが原因にあったものと考えられます。","id":"exchange-032"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この陳情の裏のページの上から５行目ぐらいに、「『専門性のない施設職員による精神障害者地域生活支援センター』のようなものではなく、『専門家による相談支援センター』の開設を強く求めます」と書かれているのですけれども、これはたいむのことを言われているということなのでしょうか。その点についての区の見解も伺いたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"２つ目のご質問でたいむの体制ですが、たいむにつきましては、職員が５名おりまして、有資格者ですが、精神保健福祉士、社会福祉士を持っている方が３名、相談支援専門員の資格を持っている方が４名いるということで。","id":"exchange-033"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"本当に障害者福祉はまだまだいろいろと改善や充実が求められるところだと思います。日本精神科看護協会の閉院が事業者からこのような形で来たのと、この陳情が同時ですので、これから本当に様々な要望がたくさんあると思いますから、充実に向けて検討に検討を重ねて、充実する方向でぜひお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"本日結論を出すでお願いいたします。一言だけ。今、資料には、８月２６日、令和４年９月末ということでありまして、これはどうしてかというと、経営状況の不振で、精神科医が確保できなかったということだと、今後もいろいろな形が出てくるので、先ほどの指定管理からの流れも、私は大体理解していますが、こういう流れも踏まえて、根本的にどのようにしていくのだということもしっかり区が判断していく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"若林委員","kind":"質問・要望","question":"結論を出すでお願いします。ご説明にもありましたけれども、いずれにしても精神保健衛生に関する部門にも、また保健等とも密接に絡んでくると思います。充実に向けて、しっかりと取り組んでいただきたい。これは、しっかりお願いをするしかないということで、この陳情については不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"せお委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。来年９月に閉院するというご報告がありました。子どもの発達相談や診断などに関しては、私の周りではすごく評判がよかったのですごく残念ですが、本当にぐるっぽ全体で、区が方向性をしっかり検討していただきたいという要望と、令和４年９月末まではしっかり診療を行っていただきたいという要望をさせていただいて、不採択にします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"本日結論を出すということで、趣旨採択でお願いしたいと思います。もともとこういうところにあるようなことをやろうとしていたにもかかわらずできないという現実の中で、要望が出てくるということは当然のことだろうなと思います。趣旨は分かりますので、趣旨採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。資料に閉院とあるということですので、当初の目的、一番初めにいろいろな事業をやろうと思ったことがなかなか軌道に乗らなかった。事業者も努力され、また、区も十分支援をしてきたと思うのですが、残念なことに閉院となってしまったので、この陳情のお求め自体はなかなか実現することは無理だということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/779921?Template=document&Id=3606#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":27564,"voices":114}},{"id":"r03-20210921-8","meetingId":"r03-cm09","date":"2021年9月21日","dateIso":"2021-09-21","committee":"建設委員会","time":"午前１０時００分～午後 ２時２８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を68件抜き出しています。","topics":[{"id":"topic-01","title":"第６３号議案、指定管理者の指定","agenda":"第６３号議案、指定管理者の指定","exchanges":[{"speaker":"のだて委員","kind":"提案","question":"実際に事業者からは、提案内容とかをもらっていると思うのですけれども、そういったものも含めて情報を出していくことが必要だというふうに思います。なので、実際に中身を聞きたいのですが、５つ聞きたいと思いますけれども、この魅力ある講座が提案されていると書かれておりますが、どういったものなのか。その提案内容と、区の評価を伺いたいと思います。","respondent":"河内環境課長","answer":"立正大学との連携ですが、先方のほうで環境を勉強している学生もいらっしゃり、また、ボランティアでも体験してみたいというところもありますので、講座などの手伝いから始まりまして、また、立正大学という立地を活かしました講座なども、今後、行っていきたいということで。","id":"exchange-001"},{"speaker":"のだて委員","kind":"提案","question":"最初に、提案内容からもっと情報を公開していただきたいということを求めたので、それについても伺いたいと思います。でご答弁いただければと思います。利害関係者がこの選定委員にいるというのは、利害関係、どこまでそう言えるか分からないですけれども、関係する方がいるというのは、どうなのかなというふうに思ったのですが、区のお考えも伺いたいと思います。","respondent":"河内環境課長","answer":"全員経験者の中でそろえていきたいとは考えておりますが、今後また検討の内容によっては変化するかもしれませんが、そういったところで、現在、進められているところです。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"それで、この施設そのものの話に移っていきたいと思うのですけれども、やはりこの環境学習交流施設、今、課長からもご説明がありました地球温暖化の問題が一番注目されていると思うのですけれども、この気候変動がやはり人類の存亡もかかった重大問題ということで、２０３０年までに地球の気温上昇を１.５℃に抑えることが危機回避のために必要とされていますけれども、こうしたことはどのように発信。","respondent":"河内環境課長","answer":"情報開示につきましては、積極的に検討して進めてまいりたいと考えています。それから、温暖化についての発信です。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"２０１９年度のＣＯ２排出割合では、発電所が３９％、産業が２５％で６割を超えています。家庭は５％だったと思うのですけれども、やはりこの家庭の努力だけではどうにもならないということになりますので、産業と一体的に進めていくということでも、区の施策を一体にやっていくということが重要なのではないかというふうに、だからこそ直営にすべきではないかと思うのですが、いかがでしょうか。","respondent":"河内環境課長","answer":"先ほど、パリ協定、温暖化につきまして、待ったなしの状況というところで、結果優先というところと、先ほど指定管理者の要旨のところでご説明させていただいたとおり、やはり民間のノウハウを使うべきときは使うというようなところから指定管理者としたいというものです。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"このアクティオという事業者が、運営のノウハウを持っているということですけれども、アクティオも環境の専門業者ではないのですよね。このアクティオのホームページを見させていただいたのですけれども、正社員よりも契約社員とかアルバイトが多数を占めていまして、環境学習交流施設での労働環境、処遇が心配されます。不安定な雇用を増やすことになるのではないかと危惧しますが、いかがでしょうか。","respondent":"河内環境課長","answer":"前段の簡易型プロポーザルの中で、実は運営、管理、設計、それぞれの専門業者が三位一体となってやることにつきましてご説明したとおりでございまして、こちらにつきましては、丹青社といいまして、歴史館あるいは防災センターの中で。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"雇用の部分で、それぞれの地域で顔になるというようなご説明でしたけれども、ちょっとよく分からなかったのですが、ほかの指定管理の資料とかを見ますと、この事業者で最も低い労働賃金単価が幾らかということが出ているのですが、このアクティオの場合、そういったことが分かるのかどうか、知っていたら教えていただきたいと思います。","respondent":"河内環境課長","answer":"そういったところから検討を進めていっている状況です。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"この指定管理者候補者は、何件あったのでしょうか。","respondent":"河内環境課長","answer":"その後に施設条例ができますので、つまり、施設がある程度固まってきて、どういうものでやるかと決まってまいりますので、そこで指定管理に任せることが決まり、また、選定基準が決まりという点で、そちらの選定したものにつきまして。","id":"exchange-007"},{"speaker":"西本委員","kind":"提案","question":"要するに、このいろいろと評価基準に照らし合わせて評価をして、プレゼンもしていただいてということが、アクティオだけですか。要は、どこまで、プロポーザルだからいろいろ提案されてきているのかだと思うのです。だけど、どこで選別して、どこで決めて、やっぱり事業所だからいろいろやりたいのだと思うのです。でも、そこまで見えるような形になっている選定なのかということも気になります。","respondent":"河内環境課長","answer":"その際、公募を行いまして適切な業者を決めたところではあるのですが、その後で、こちらの業者が、２年経っていることもありますし、また、指定管理者の運営基本方針も改定されまして、外部評価員を入れる点とか。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"ということは、新たにいろいろ選定の方法が変わってきたということで、こういう手順をとりましたということなのでしょうけれども、要は、例えば３者だったら３者あって、同じように評価をした上での選定であるべきではないのかと思うのです。例えば、この点数制がありますね。これ、１者だけやっても正しい評価になるのでしょうか。そこがちょっと気になるのですけれども。","respondent":"河内環境課長","answer":"そういった事情で進めているものです。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"私は、確かに実績というのは必要だと思うし、規模なども、うまくいくための大きな指標になるかと思うのです。この環境というのは、なかなか浸透する、啓発活動ですから、本当に新しいことを考えていかないと、継続が難しいという思いがあるのです。なので、そこの融通性とか、新しい発想であったりとかというところをどういうふうに判断なされているのか。","respondent":"河内環境課長","answer":"委員のおっしゃる点もよく理解しているつもりですが、中小のところで、やはり新たな視点、提案などがありましたら、聞く耳を持つのは当然なのですが、やはり大事なところは、運営に対する実行能力だとか、指定管理期間の５年間の安定感だとか。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"例えば１年、数年は必要だと思うのですけれども、もしもこちらの要望に合わないというような状況になったときに、見直しも、契約が５年間だから５年間投資しなければいけないということは私はないと思っていて、もっと違うところで意欲があって品川区の要望がかなえられるようなところがあるならば、私はどんどん採用するべきだろうと、そこは競争の世界に入ってくるのではないかと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"西本委員","kind":"意見","question":"それは全部品川区の持ち出しになってしまうのか、ある程度補助金がありますということなのかということと、それから、何かやりたいと言われたときに、いや、予算がないから駄目と言うのではなくて、ある程度幅を持たせて、やれることがあるのだったらば、ある程度予算をかけながらということが必要な部分かなと思っているのですけれども、このコストの面についてはどう考えていますか。","respondent":"河内環境課長","answer":"こちらにつきましては、指定管理者として協定を結ぶというものでございまして、あらかじめ内容につきましては区と協議するものですので、収入につきましても一定のものとなるものですが、さりとて、環境に関して違う風が吹いて、これが要るものというところにつきましては。","id":"exchange-012"},{"speaker":"塚本委員","kind":"質問","question":"今回のこの基本方針ですか、指定管理者制度の基本方針というものを活用して選定していくということで、まず公募でアクティオが選ばれて、それに対して候補者としての予備委員会と、候補者選定委員会、こういったものを実施をしてということで一定の評価が得られたということで、それはそれで、なるほどということだと思うのですが、やっぱり分かりにくいのは、候補者選定委員会と言っても。","respondent":"河内環境課長","answer":"現段階において、このスタイルがいろいろあるかどうかというのは私も分かりませんけれども、当時の事情といたしましては、そういった開館後の安定的な意義と、それから、会社のそういったところの選択におきまして。","id":"exchange-013"},{"speaker":"塚本委員","kind":"質問・要望","question":"公募の段階、プロポーザルの段階で、１者になったというところで、それに対してどういった選定という言葉がかかってくるのかというのは、やっぱりちょっと、所管が違うので意見なのですけれども、これはまた改めて選定委員会という言い方がいいのかどうかというようなことは、ちょっと思ったりもしましたが、いずれにしても、今まで以上に深い検討を重ねて選定しているということについては。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"芹澤委員","kind":"提案","question":"各施設との、区内施設との連携ということが書いてあったと思うのですが、改めて具体的にどういうことか、よく分からないので教えていただきたいのですけれども、例えば、環境を学んで、そこから歴史館であったりとか、しながわ水族館が、具体的にパンフレットが置いてありますとかではなくて、何か連携したプログラムを組まれるということで認識として合っているのかということと、あと、この資料の中では。","respondent":"河内環境課長","answer":"例えば、食品ロスや衣類など、そういった項目も展示物の中で学習できるとともに、大人目線で考える環境講座なども含めて行いながら、後ほどまたご説明いたしますボランティアなどでも、そういったところのご活躍をというところで、今、進めているところです。","id":"exchange-015"},{"speaker":"のだて委員","kind":"意見","question":"この施設は、特に重大な気候変動を回避するための発信や啓発行動が期待されております。それを実現するために、区が責任を持って運営する区の直営にすべきです。費用を削減するためにも、指定管理にすることは、品川区がワーキングプアをつくり出すことにもなりますので、反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"}]},{"id":"topic-02","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"西本委員","kind":"質問","question":"１点だけ教えてください。これはボランティアなので、有償、無償とあると思うのですけれども、それはいかがですか。","respondent":"河内環境課長","answer":"当初は無償です。今後、ボランティアの分野がいろいろまた発展するかと思いますので、そういったところと他区の状況などによりまして、有償なども検討していきたいというふうに考えているところです。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"今後考えるということなのですけれども、内容によっては、ボランティアの方々の思いを尊重するという形、これは無償になるのだろうと思うのですが、ですから、ある程度、融通をきかすような形で、幅を持たせていろいろやっていただくという形が必要かと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]},{"id":"topic-03","title":"会議の運営上、予定表の順番を入れ替えまして、予定表の４、その他","agenda":"会議の運営上、予定表の順番を入れ替えまして、予定表の４、その他","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今後の予定で、説明会等を今年度中に行っていくということが説明されましたけれども、これはいつ行うのか伺いたいと思います。このマンションの住民は、やっぱり自宅がどうなるのかということさえ詳しく情報をもらっていないというもとで、この都市計画手続を進めていくというのは、やめるべきだと思いますけれども、いかがでしょうか。","respondent":"多並都市開発課長","answer":"今後の説明会ですが、１０月１３日に権利者の方々を対象とした説明会を行う予定となっています。その後、全体の区民を対象とした説明会については、現在の予定は、１２月頃を予定しています。","id":"exchange-019"},{"speaker":"のだて委員","kind":"提案","question":"そういった再開発を進めていくという、この仕組み自体が私は問題だというふうに思いますけれども、先ほどの冒頭の説明で、準備組合の総会の中で、９割の方が賛成をして、都市計画の企画提案を議決したということですが、その総会に参加した人数は先ほどおっしゃっていましたね。その中で、そうすると、実際の権利者の数は、準備組合に参加をしている方は何名なのか伺います。","respondent":"多並都市開発課長","answer":"このカウントの仕方で、地権者数は６４名の中で、そのうち組合員の方が６３.４１名ということで、９９％の方にご参加いただいていると聞いているところです。","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問","question":"この６４名、また組合に参加している方の内訳、土地の所有者、あと、マンションの区分所有者、借地権者等々の内訳を伺いたいと思います。","respondent":"多並都市開発課長","answer":"借地権者の方が３９名、そのうち組合員の方が３９名ということで１００％です。区分所有者の方が、先ほどご説明した５名となりまして、そのうち組合員の方が４.４１名ということで、８８％ということで、合計９９％です。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問","question":"マンションの方は１棟１名と換算して４.４１名が組合に参加しているということですけれども、そうすると、今回この総会の中で、マンション区分所有者の方がどれだけ参加をされていたのか。総会に参加していた土地所有者の方、借地権者の内訳も伺いたいと思います。","respondent":"多並都市開発課長","answer":"これは７月の総会時点のお話になりますけれども、全体の組合員数が５５名で、参加された方が４９.８７名、その中で土地所有者の方が１６名、借地権者の方が３１名、区分所有者の方が２.８７名です。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、このマンションの所有者の方は、全体で言えば５名のところ２.８７名という、４割強、参加をしていないということになるわけですね。その実際の実人数は何人になるのでしょうか。その方たちは、実際に権利、総会では賛成を表明していないということになるわけですが、何人でしょうか。","respondent":"多並都市開発課長","answer":"総会へ参加された区分所有者の方は、実人数で言うと６９名と聞いてあります。加入者の方が全体で１２２名という状況です。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問","question":"組合に参加している方でも、約半数の方が行使をしたというだけにとどまっている。残りの５３名プラス組合にも参加をしていない、全体が１４７名だったと思うのですが、そうすると、２５名の方が参加もしていないということで、７０名以上の方が納得をしていないというもとで都市計画手続を進めていくというのは、やめるべきではないかなというふうに思うのですが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"より丁寧に地域の方にちゃんとご説明しながら進めているところで、区としても、しっかりそういうふうに指導していきたいと思うところです。人数の件ですが、先ほどの権利者以外に借家人の方が約１５０名と聞いてあります。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"実際にそこに住んでいる、生活があるということは変わりがありませんので、このマンション１棟という、一筆という形で考えるのではなくて、それぞれの生活を保障していく、各家庭のその人の生活を保障していくということで考えていくべきだというふうに思いますけれども、いかがでしょうか。今回、総会で９割の方が賛成したということですが、これはどういった説明がされて議決をされたのかと思うのです。","respondent":"多並都市開発課長","answer":"当日参加されなかった方、または組合に参加されない方に対しても、書面で、この配布された資料については周知を図っている、要するに、ポスティングをして周知を図っているということですので、区といたしましては、皆さんに説明しながら進めているというふうに認識しています。","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"ここに住み続けたいと。その思いを区が守ることこそ必要ではないかと思うのですが、いかがでしょうか。そして、この開発計画の中では、個別利用区ということを設定することもできると思うのですが、ビルを建てるだけではなくて、戸建てなども建てられる、そういう制度もあると思うのですが、そういった設定を検討されたということは、区は聞いているのかどうか伺います。","respondent":"多並都市開発課長","answer":"これについては、より丁寧に、ちょっとご説明しましたけれども、マンション全体の中で説明会をやっていただくということと、また、その中でご不安の声をいただいている方がいれば、個別にサポートしながら進めていく。","id":"exchange-026"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"先ほど来から課長のご答弁を伺っていましたけれども、生活再建、あと、情報をどういうふうに伝達をするのかという説明とお話、また質疑の中で、そのようなものがありましたけれども、答弁の言葉の中で、「報告を受けている」、そして「聞いております」という、これ、２つのキーワードというか、文言が出てきたのです。そこをどういうふうにお考えになって、どういうふうに今後されるか、ご答弁願いたい。","respondent":"多並都市開発課長","answer":"区といたしましては、このような状況をもう少し丁寧に説明して、もっと丁寧な関わり方をしようということで、事務局に対して、今回もマンション説明会を個別でするようにであったり、また、その生活再建に必要な管理費であったり、今後の積立金であったり。","id":"exchange-027"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"そこをしっかりと指導というか、助言というか、徹底をする目を光らせていただきたいと思いますけれども、今ご答弁を聞きましたけれども、もう１回、すみません、そこのところをお話しいただきたい。","respondent":"多並都市開発課長","answer":"それで、これから地域の方を対象とした説明であったり、また、ご意見をいただける場がありますので、それに対して、またそれをちゃんとご理解した上で意見をいただけるような、そういう形でより丁寧にやっていきたいというのはそういう意味ですので。","id":"exchange-028"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"だから、そこのところは、頼みますから、先行の２棟が失敗したという認識にならないように、新しいまちづくりはしっかりと住民主体にやっていただきたいと思いますし、今、課長においても、そこのところはやっていらっしゃるということでしょうし、今後のいろいろな生活再建等々については、これからの話になろうかと思いますので、粛々と進めていただきたいと思いますので、あとで態度表明はしますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"なぜならば、なぜ理解できるように、当初から、スタートの段階から、なぜ調整できないのだろうか。そして、それは大分前から、もう何年前なのですか、定めているわけであって、それに従って業者がやりますよという形で準備組合等々ができて、そして都市計画審議会にかけられてという順番で、もう今の段階として、都市計画審議会にかかるわけです。これのもともとのスタートはいつだったのでしょうか。","respondent":"多並都市開発課長","answer":"武蔵小山駅につきましては……。この後、平成２４年に街並み誘導指針、また、街並み再生地区を変更しながら、令和元年に街並み誘導指針の追補版をまた策定いたしまして、この中で、現在の計画に至っているです。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、一番スタートはどこでしょうかというところなのです。それぞれの１軒１軒、生活再建に入ってくるので、そのそれぞれの要望をお聞きしながら、サポートがどこまでできますかねという個別の対応にならざるを得ない。これを開発をやめてくれ、白紙にしろなどというのは、今の段階、この段階で私は無理だと思っているのですが、その件についていかがですか。","respondent":"多並都市開発課長","answer":"さっき途中でご説明しましたけれども、この平成１６年に策定しただけではなくて、その後、地域の方のご意見を踏まえて、これまで変更もしくは追補という形で、新たに考え方を加えながら、そのときそのときの事業の。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、やはりまちづくりをするときに、私も今回、一般質問をしましたけれども、住民合意というところでは、本当にしっかりやっていただきたいと思います。住民サイドも、知らないでは済まされないのです。では、それを区はどこまで関与しなければならないのですかという話になってしまうと、民民の話に顔を突っ込むことになってしまうから、それはしてはいけない範疇だと思います。","respondent":"多並都市開発課長","answer":"これについては、今ちょうどマスタープランの改定をこれから作業を進めているところですけれども、今度の新しい中で、より区民の方が、一人ひとりが分かりやすい言葉、共通認識できるような言葉で伝えながら、地域の中でこのまちをどうしたらいいかというのが。","id":"exchange-032"},{"speaker":"のだて委員","kind":"質問・要望","question":"実際にこれだけ知らない方もいらっしゃるということで、区も問題意識を持っているわけですから、一旦停止をすることはすべきだというふうに思います。住民が求めているのはそういうことではなくて、今のマンションに、住みなれたマンションに住み続けたいということで願っているわけなのです。進めるべきではないと思うのですが、そういったことが必要だというふうに思いますけれども、いかがでしょうか。","respondent":"多並都市開発課長","answer":"これをやることで、今後どういう形でお住まいになるのかということが大分見えてこられると思いますので、そういう形でもっと丁寧に対応するようなことで、いろいろそのときそのときの皆さんのご不安を聞きながら、適切な対応をするようにということで、区としても助言。","id":"exchange-033"},{"speaker":"芹澤委員","kind":"意見","question":"ただ、今お話があったように、特にマンションの方々を中心として、不安や疑問を持っている方がいるというのは、区も課題として考えていらっしゃるというお話もいただきましたので、区がやること、準備組合がやること、それぞれやれることも含めてあると思いますが、最大限、引き続きになるかと思いますが、そこの不安解消というところは、ご支援をいただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"塚本委員","kind":"意見","question":"本日結論を出します。結論は不採択でお願いしたいと思います。基本的には、やはりこれは、質疑の中でもありましたけれども、住民主体ということが大前提で、準備組合内のことにつきまして、何かをやるべきとか、やめるべきとかということを議会が基本的には発言すべきものではないというのが考え方としています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"不採択。疑問が解消されないままということと、都市計画を進めることをやめるという、これはもうやめるということは、制度にのっとってやっているものですから、これは無理。だけれども、先ほどの請願第９号の今後の予定の中で、これは予定ですから、ここの慎重な進め方というのはいくらでもできるわけです。そこだけはきっちりときめ細かに対応していただきたいと思います。それはお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択を主張します。住民の生活が壊されるにもかかわらず、自分たちの生活がどうなるか分からないまま進められており、住民の合意が得られていないまま強行に都市計画手続を進めることはやめるべきですので採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出すということで、不採択でお願いします。先ほども申しましたが、住民合意形成の仕方は、これからいろいろ考えていただきたいということと、それから、本当にきめ細やかな対応をぜひお願いしたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"}]},{"id":"topic-04","title":"令和３年陳情第４９号、品川区内の特定整備路線事業の中止を求める陳情","agenda":"令和３年陳情第４９号、品川区内の特定整備路線事業の中止を求める陳情","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"最初に、用地取得率のところで、２９号線、区間ごとに６つに分かれて出ておりますが、下は１７％から上は４０％ということで、これ、全体でのパーセンテージがありましたら、伺いたいと思います。それ以上に、この陳情で言いますと、２０％、３０％減少しているということですから、廃止をする理由にはなるというふうに思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"それから２点目ですが、交通量の減少に伴うネットワーク等のお話ですが、陳情にもありまして、今、委員が口頭でもご説明いただいたこの調査内容については、区のほうでも、これは交通センサスの中で、東京都が国と合同で実施している報告書の中で公表しているものの確認。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問","question":"それで、２９号線ができた際には、周りの交通が流れ込んでくるということなのですが、逆に、流れ込んでくると、もともとあったところが交通量が増えるわけですから、危険性が増していくということになるので、商店街が通りますし、むしろ流れ込んできては困るというふうに私は思うのですが、いかがでしょうか。２９号線、２０ｍ道路ができたから詰まらないのかということが言えるのでしょうか。伺います。","respondent":"鈴木都市計画課長","answer":"それで、先ほど、私の説明が不足しておりましたが、やはり木密地域ということもあって道路が非常に狭いこの荏原地域を通る３路線ですが、そうしますと、車が非常に狭い道路等を通っているというようなところで、一定の広幅員の都市計画道路が整備されて、当然ながら。","id":"exchange-040"},{"speaker":"のだて委員","kind":"質問","question":"交通の適正化が図られていくということなのですが、戸越公園の駅周辺は特にですけれども、２９号線のところが商店街なのです。そこを２９号線が通るわけですけれども、現在でも人と自転車がボトルネックになっているという中で、今度はさらに車まで追加されていくということで、交通の円滑化と言いながら、むしろ交通が円滑化しないという道路なわけですが、区はそのところはどうお考えなのでしょうか。","respondent":"鈴木都市計画課長","answer":"２９号線の特に戸越公園駅の点についてご質問いただいたわけですが、先般の建設委員会でも所管よりご説明させていただきましたが、東京都は、この立体化に向けて、準備採択、位置づけをワンランク上げて採択されたというところが結果として出てあります。","id":"exchange-041"},{"speaker":"のだて委員","kind":"質問","question":"陳情の２点目のところでは、防災性の疑問も投げかけられています。実際に２９号線は２０ｍということですが、その道路で延焼を止められるのかということなのです。そういった飛び火を考慮せずに、この延焼シミュレーションを行って、防災性がありますというのはおかしな話ではないかと思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"そうしたところの建物を、延焼遮断体の形成と一緒に不燃化を一生懸命、今、品川区として、助成をもって進めているです。","id":"exchange-042"},{"speaker":"のだて委員","kind":"質問","question":"その消防力で止めたのだということなのです。そういったことを区はご存じだったのか、ご存じであれば、それをどのように考えていらっしゃるのか、これまでも区は不燃化領域率７０％になれば燃え広がらないということをおっしゃっていましたけれども、効果が、実際、道路では分からないということになるわけですが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"不燃領域率につきましては、これは区のほうで不燃化特区、東京都の不燃化１０年プロジェクトを活用し助成制度を行っていくに当たって、それぞれで不燃領域率を算定して、区のほうでも把握をして進めているです。それに向かって、今、取組を進めているです。","id":"exchange-043"},{"speaker":"のだて委員","kind":"質問・要望","question":"放射２号線のほうも、実際、これは防災のためと言われて進められてきましたけれども、火災危険度は低いほうから２番目というところで、星薬科大学もあって、延焼遮断に既に星薬科大学はなっているというものを分断する計画になっておりますので、そうした計画はやはりやめるべきだと思いますし、コロナのこの中で、不要不急の巨大道路、特定整備路線などを進めていく必要はないと私は思いますので。","respondent":"鈴木都市計画課長","answer":"いつ来るか分からない大きな地震に備えるというところでは、非常に喫緊な課題というところで、先ほどもご説明しましたが、ソフト的なところ、消防の方々の力だけでは、当然ながらマンパワー的なところも限られているところはあると思います。","id":"exchange-044"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうした対策をちゃんとやって防災性を高めていく。この特定整備路線の延焼遮断帯の構想は、１ｋｍメッシュで遮断帯をつくっていこうというものなわけです。それで実際、品川区民の生活を守れるのですかと私は思うので、やはり耐震化、不燃化、感震ブレーカーの設置など、そういった予防策をさらに推進していっていただきたいと思いますし、特定整備路線はやめるべきだと言っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"西本委員","kind":"確認","question":"幾つか確認をします。資料でいただきましたこのパーセンテージですけれども、これ、東京都公表値ということで、いつの、３月末だから、どういうところまで、完全に取得というところのものなのか、例えば、めどがついているものでちょっとずれがあるのではないかと思います。というのは、２８号線は５６％なのですが、もっと進んでいるのではないかと見ているのです。それを教えてください。","respondent":"鈴木都市計画課長","answer":"不燃化特区、木密関係の事業についてですが、ちょっと手持ちに、今日は所管もいなくてあれなのですが、当初１０年間の事業だったものを、東京都も延伸しますよというところで、その延伸の中で、区としても事業を進めているです。","id":"exchange-046"},{"speaker":"西本委員","kind":"質問","question":"大分進んでいるかなというところもありますので、実際は、これよりも、交渉も含めると大分進んでいるかと考えています。途中でやめてしまう可能性もあるということなのか、その辺はいかがですか。","respondent":"鈴木都市計画課長","answer":"これは区民の方にはしっかり周知していかなければいけないわけなのですが、やはり我々も早急にこのエリアの地域について不燃化を図っていきたいですので、それにはやはりしっかりした周知と説明を地域の方にしていきたいというふうに考えてありますが、それは。","id":"exchange-047"},{"speaker":"西本委員","kind":"確認","question":"特に補助２９号線、２８号線もそうなのでしょうけれども、商店街などもいろいろ含んでいて、結局まちづくりにかなり関与している部分があるのです。なので、これは東京都が中心なので品川区の意気込みを聞いてもしようがないと思うのですけれども、東京都がどういう気持ちなのか、やっぱりある程度の期間を置きながらも確認作業をしていって、住民の皆さんには周知徹底をしていく。","respondent":"鈴木都市計画課長","answer":"コロナ禍におけるこの道路整備というところでのご質問ですが、昨年の令和２年５月に東京都が依命通達という形で、コロナ禍における様々な都の事業の考え方について出しているところがあります。","id":"exchange-048"},{"speaker":"本多委員","kind":"質問","question":"当然、周知とか、その必要性は東京都がやってきたことだし、やるべきものだと思いますが、品川区の担当から見まして、その辺の把握というのでしょうか、手応えというのでしょうか、その辺の感じ方。それと、今質問も出ていたように、令和２年５月の依命通達とか、そういったことも東京都がやってこられて、その辺の感じ方、担当部署から見て、その辺の手応えみたいなものを教えてください。","respondent":"鈴木都市計画課長","answer":"それで、その事業化に当たっての、区内でも３路線、地域説明会が開かれて、東京都による説明会が行われておりまして、これまでも、その中でも、さらに沿道の、先ほどご紹介した不燃化の区の事業の中でも、やはり特定整備路線と沿道の不燃化。","id":"exchange-049"},{"speaker":"芹澤委員","kind":"質問","question":"本日結論を出すで、不採択でお願いします。個人的に特定整備路線の効果、必要性はあると思っていますし、特に今お話しいただきましたけれども、区内の地域柄、木密というところも考えると、非常に効果が高いというご説明もいただきました。区としては、都の計画を粛々と進めるという役割もあるかと思いますので、それはしっかりと進めていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"塚本委員","kind":"意見","question":"本日結論を出すということで、不採択でお願いいたします。この特定整備路線の整備事業についてということでの交通量、あるいは防災性、こういったことについて疑問があるということですけれども、既に区から説明があった資料にあるとおり、事業が進んでいる中で、この目的を無意味として中止するということにはとても当たらないというふうに思いますので、不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"大沢副委員長","kind":"質問","question":"理由については、先ほど課長から言われたように、昭和３０年代後半から木造家屋が密集して、当時で言えば、まさに都市計画法に基づいてこの事業はなったわけですけれども、無秩序に並べられた都市を整備していくという部分では、非常にこれは大事な事業であるということは言うまでもないことだと私は思っておりますので、ここのところは、やはり防災性、防火。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択を主張します。るる言ってきまして、交通の円滑化にもならず、防災も費用対効果に合わない。名古屋市では、買収が進んだところでも、８割つくっているというところでも廃止にしました。住民に立ち退きを迫り生活を破壊するというものですので、ましてやコロナ禍で莫大な税金を投入して進めるべきではないですので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出すということで、不採択でお願いします。必要なことということで、東京都のほうも、この路線は必要だということがあるならば、やはり住民サイドの方々にご理解を求めるということは、継続的に、東京都が中心になると思いますけれども、しっかり取り組んでいただきますように、２８号線等はもうかなり進んでいるのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"のだて委員","kind":"確認","question":"確認なのですが、今回の都市計画の４つの内容、これは区は区民に周知をしたのでしょうか。具体的には、区報に載せたのかということになると思いますが、ほかにも方法があれば、いかがでしょうか。","respondent":"多並都市開発課長","answer":"区報には載せてございません。ただ、ホームページで、事業計画の中で記載したものは、皆さんが見える形にさせていただいているところです。","id":"exchange-055"},{"speaker":"のだて委員","kind":"確認","question":"事業計画の中ではやったというのは、どういうことでしょうか。実際に説明会をやりますよということが載ったということか確認させてください。","respondent":"多並都市開発課長","answer":"先ほどご説明したとおり、ＪＲ東日本と共催で説明をした事業計画の説明会を行いました。この中で今後の進め方のところで全体の説明をさせていただいて、その中で今後の都市計画の内容であったりを記載させていただいて、周知させていただいた。","id":"exchange-056"},{"speaker":"のだて委員","kind":"質問","question":"ということは、改めてこの説明会、７月１２日の説明会をやるに当たっては、広報はしていないということだと思います。そうしたところを見れば、品川区としてもやはり区報に載せるなど、周知をしていくことが必要だと思いますけれども、いかがでしょうか。そもそも品川区内の計画なわけです。それを区民に知らせていくというのは、そもそも区がやるべきことだと思うのですが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"今年度から進めている新たな策定委員会につきましても、ご議論や、また当日使った資料については、全てホームページに出するとともに、これからパブリックコメントという形で区報のほうに載せる予定ですけれども、皆さんにこれをお知らせしながら進めるということで。","id":"exchange-057"},{"speaker":"のだて委員","kind":"質問","question":"私が伺ったのは、都市計画手続の中で、法律に基づいてというところもあるとは思いますが、そういった面で見ても、品川区決定があるということですから、区が、区報などで、この説明会がありますよということを周知することが必要なのではないかということなのです。","respondent":"多並都市開発課長","answer":"今のものも第１６条という、先ほど説明させていただいた条文と、もう１つ、第１７条がありましたけれども、これが考え方としては、まず、基本的な考え方ですけれども、都市計画法の中では、地区の中の非常に関係性が深い、地区計画というのは、地区のルールを定める計画ですので。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問","question":"なので、この第２項の考え方からいっても、利害関係者以外の住民も対象になっていくべきなのだと私は思います。第１７条になってしまうと、案になると、一歩進んでもう決定しようとするときの説明会だということになりますので、その第１６条のところで多くの方に、まだ案の段階というか、考えている、検討中の段階というところで意見を聞くというのが、私は重要だと思いますけれども、いかがでしょうか。","respondent":"多並都市開発課長、鈴木都市計画課長","answer":"ただ、今回は新庁舎がありますから、それについては、庁舎という観点で、その中でも都市計画の説明をしながら、ご意見を募りながら、両方総合的に連携しながら進めている形をとっておりますので。繰り返しになりますが、法律にのっとって手続を進め、第１７条で、第１７条の条文も都市計画法で記載しておりますが、関係区市町村の住民および、ここで利害関係人と、広く聞くようにと、しっかり第１７条で明示されておりまして。","id":"exchange-059"},{"speaker":"のだて委員","kind":"質問","question":"今回、地区計画の範囲の方が一番影響を受けるのだということでおっしゃられておりますが、その地区計画、昔の規制型であれば、その地区内の人に意見を聞くだけでよかったと思うのですが、今は、今回もですけれども、容積率緩和で規制緩和型の地区計画というのは、建物が高くなってくるということで、陳情にも書いてありますが、大きく周辺に影響を与えるというものになりますので、やはりそういった面でも。","respondent":"多並都市開発課長、鈴木都市計画課長","answer":"これ以外に、今、周辺への影響のところでありますけれども、これについては、また環境影響評価という観点から、地域の説明をして、ＪＲの建物になりますので、ＪＲが事業者として説明し、縦覧というか。先ほどの委員のご質問の中で、第１６条の第１項のお話がございましたので、法律的な内容でご説明しますと、第１６条の第１項を見ていただきますと、「都市計画の案を作成しようとする場合において必要があると認めるときは」と。","id":"exchange-060"},{"speaker":"のだて委員","kind":"質問","question":"第１６条の第１項のところは、必ずやらなくてもいいという話ですが、そうすると、区はやらなくていいと思っているのですか。この広町地区に関して、説明会をやらなくていいと考えているのかということと、やはり実際の説明会をやるに当たっては、この４つの都市計画の説明をすると思うのです。ということは、やはり多くの区民に周知をしていくということが必要だと思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"第１７条のほうでは、むしろ説明会を行わなければいけないという記載はございませんが、しっかり事前に周知をして説明会を行った上で、公告、縦覧、意見募集を行うという手続です。","id":"exchange-061"},{"speaker":"西本委員","kind":"確認","question":"いろいろ説明ありがとうございました。ちょっと法的な部分になると、いろいろな解釈がないと分かりづらいところがあるのですが、要するに、品川区においては、ご説明があったように、法的なところを踏まえて着々と進んでいます。そこを確認させてください。しっかり法的なところの根拠に基づいて進めていますということでよろしいのでしょうか。","respondent":"多並都市開発課長","answer":"今、委員のご指摘のとおり、区としては、今、都市計画課長からも法的な説明をさせていただきましたが、そのような形で法にのっとって適切な対応、東京都のほうもありますので、東京都と連携して、法にのっとってやっているところです。","id":"exchange-062"},{"speaker":"西本委員","kind":"質問","question":"そうだろうと、十分説明の中で、それが十分認識されました。それで、この陳情のほうです。関係する方々は見るかなという感じで、なので、今こういう状況で進んでいますよというのは、分かりやすい言葉で、知らせていくということは必要なのかなというふうに感じましたが、だから、今後、表現の仕方、区民の皆さんに対して、ここの地域の進み具合、進捗状況の周知をどのように考えていますでしょうか。","respondent":"多並都市開発課長","answer":"それが区有地に関しては非常に密接に関係する観点があるので、それについては、この中でも説明しましたし、庁舎計画の中でも丁寧に説明させていただいたとおりで、この間の（建設）委員会では、もう少し具体的に説明させていただいて。","id":"exchange-063"},{"speaker":"芹澤委員","kind":"質問","question":"本日結論を出すで、不採択でお願いします。今回の陳情の理由としては、基本的に法令違反というような前提条件があるかと思いますが、今ご説明いただいて、遵守して進めてきているというようなお話がありましたので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"塚本委員","kind":"確認","question":"本日結論を出す、結論は不採択でお願いいたします。区から説明があったとおり、大井町周辺広町地区における、この地区計画等の都市計画、この手続については、法にのっとって、また、自治体の条例にのっとって適切に進められているということが確認できましたので、本陳情は、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"大沢副委員長","kind":"質問","question":"本日結論を出してください。不採択でお願いします。理由は、今、理事者の担当の課長お二人から説明を受けましたが、この陳情に流れる文脈とは大分事実的に相違があるというふうに理解をしましたので、この陳情については、不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"のだて委員","kind":"意見","question":"結論を出すということで、採択を主張します。まちづくりは住民の合意で進めていくということが大切ですし、今回の計画地は区有地を含む計画であります。都市計画手続の中には品川区決定のものもありますので、区が区民に周知をすることが必要だと考えますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろと先ほど確認をいたしました計画、法にのっとった形でしっかりされているということも確認がとれましたし、ただ、やはり住民にとっては難しいのです、とっても。なので、少なくとも、一部の人とか、そういうことでやっているとは思えないのですけれども、でも、そう捉えられないように、やっぱり仕組みを考えて丁寧にやっていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/297355?Template=document&Id=4330#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":61585,"voices":179}},{"id":"r03-20210921-9","meetingId":"r03-cm09","date":"2021年9月21日","dateIso":"2021-09-21","committee":"文教委員会","time":"午前１０時００分～午後 ２時１４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を60件抜き出しています。","topics":[{"id":"topic-01","title":"第５３号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"第５３号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"国の引上げ改正の理由と背景について、また、引上げ額の根拠についても伺います。例えば、どういうときに介護補償というのは受けるものなのか、もう少し説明していただけるとと思います。以上、３点よろしくお願いします。","respondent":"勝亦学務課長","answer":"基準の引上げの背景です。先ほどご説明いたしましたが、労災保険法の改正に準拠しています。","id":"exchange-001"}]},{"id":"topic-02","title":"令和３年陳情第４０号、区内小学校普通級で学ぶ障害児への支援員の拡充、および通級利用の許可に関する陳情","agenda":"令和３年陳情第４０号、区内小学校普通級で学ぶ障害児への支援員の拡充、および通級利用の許可に関する陳情","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"ごめんなさい。最後のほうから行きますけれども、通級の利用を拒まれていますがというので、今ご説明がありました。私も、今の制度がダウン症のお子さんには当てはまらないということは承知をしておりまして、拒まれていますがという言葉遣いについて、これはどういうことを要望なさっているのか、陳情者の方に確認をいたしました。","respondent":"矢部教育総合支援センター長","answer":"現状ですと、知的の１１校、特別支援学級を設置している学校がありますので、そちらにいらっしゃると、通常学級との交流は物理的にも容易ですし、その効果もあると聞いておりますので、そちらをお考えできないかとは思います。","id":"exchange-002"},{"speaker":"吉田委員","kind":"質問・要望","question":"ただ、親御さんの気持ちとしては、それに加えて、そういう通級の制度が用意されている子たちがいるのだから、それを広げてほしいというような趣旨です。ですから、そういうことも今後の拡大していく方向性として考えておられるのか、全くその可能性はないのか、ぜひ考えていただきたいという陳情だと思いますが、その点についてもう一回だけお聞かせください。","respondent":"矢部教育総合支援センター長","answer":"ですから、国も進めていくということですので、そんなところの研究結果も注視しながら検討してまいりたいと考えております。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問・要望","question":"今は制度がないわけですよね。これ以上は押し問答になってしまいますので、これは最後、意見でいいです。今、大変厳しい状況であるということは、多分、陳情者の方もご承知ですし、今十分伺いました。ただ、やはり支援員ということがあれば、もっと有効な教育が受けられるということについてのご要望は、そちらの方向で考えるべきだと思うのですけれども、その辺についてはいかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"通常学級の学習支援員、介助員については、人数も増えてありますので、予算でもできる限り取っていきたいと要望はしたいと考えていますけれども、財政の考えもありますので、検討はしていきたいとお答えいたします。","id":"exchange-004"},{"speaker":"松本委員","kind":"質問","question":"今のお話の流れで、支援員が週１回という形でしたが、ほかの特別区の実態というのは把握されているのでしょうか。他区というのはどのくらいの頻度かというのをお願いします。","respondent":"矢部教育総合支援センター長","answer":"２３区につきましては、全て網羅はしてございませんけれども、様々な状態がありますが、本区は決して低い数字ではないと思います。ただ、特別支援学級については、かなり丁寧にやっている授業がありますので、こちらを優先して、あとは通常のほうにというところのバランスです。","id":"exchange-005"},{"speaker":"松本委員","kind":"質問・要望","question":"分かりました。予算要望とかの際に、他区も参考にしていただきながらやっていただけると、説得力が増すのかと考えていますので、こちらは要望としてします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"説明・質疑などありましたけれども、特別支援教室にダウン症のお子さんというのは通ってはいけないということなのか、そういう規定があるのかどうかだけ確認させていただきたいのと、それと、支援員の拡充という点では、増やして、充実させていきたいということなのですけれども、財政とかという話もちらっと出ましたが、支援員の拡充の実現に当たって何がネックになっているのか、もう少し聞かせてください。","respondent":"矢部教育総合支援センター長","answer":"２点目は、割合は国のほうでは６.９％と、随分前に情緒障害の方の割合を、１クラスにという数字が出ていますけれども、実際は、いろいろなところで困っているお子さんや、学級の中でも対応があることを考えますと、割合は人口増に比べて同じように増えているので。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"その点でもう一回、ネックが何になっているのかというのを聞かせていただきたいと思います。改めて、区の教育委員会としては、品川区のインクルーシブ教育の目標というのですか、今はそこの途上に向けてのいろいろ課題とか不自由な点もあるかもしれないのですけれども、最終的にどういうところを目標に置いているのかというのを伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"インクルーシブ教育は、様々示されておりますが、現状は、同じ教室でどんなお子さんについても教育するという考えもありますけれども。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"その子にとって一番充実した教育を受けられるということがすごく、それはそのとおりなのですが、ある意味、もう少し将来というか、やはりインクルーシブ教育そのものを進めていくということ自体が、先ほども言ったように、社会、あるいは子どもの育ち、豊かな教育自体の底上げというのですか、幅を広げていくという観点をぜひ持っていただきたいと思いました。さらにこうも言っています。","respondent":"矢部教育総合支援センター長","answer":"国のほうもそういうインクルーシブ教育システムの構築ということで今進めていますので、そちらに準じて、保護者と連携しながら、子どもたちができる限り輝くように応援してまいりたいと考えています。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"子どものインクルーシブ教育にとって必要だし、子どもの豊かな環境にとって必要な予算なのですということをぜひ積極的に働きかけていただき、早急な改善をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"つる委員","kind":"質問・要望","question":"やはり制度に人をはめ込んでいくということではなくて、人に制度を合わせていくという考え方というのは大事かと思いますから、そういう課題というのは、都、文科省にもしっかりと教育委員会としても強く求めていっていただきたいと思います。そうした中で、１点確認が、学業の取組の質、ここの部分を今の体制の中で、一定程度のご答弁がありましたけれども、改めてどのようにこの質を担保していけるのか。","respondent":"矢部教育総合支援センター長","answer":"東京都の人材派遣については、先ほどのとおりですが、そこも全学校に改めて、支援体制について協力できる部署がありますので、そこを紹介したところですので、特にそういうご要望のあるところはお名前もいただいていますので、少し個別に対応させていただきたいと思います。","id":"exchange-011"},{"speaker":"つる委員","kind":"提案","question":"どこそこにあるからそこに入れれば全て解決だということでは私はないのかというふうにあっては、しっかりそういう専門的な現場の先生だとか、教育委員会の皆様と、また、当該保護者との前向きな建設的な、お子様にとっての取組をどうやっていくかという、本当に伴走するような形でしっかりとコミュニケーションを図っていただいて、支援も引き続きやっていけるような形、それから、もう一方では。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"松澤委員","kind":"質問","question":"今がないというわけではないですけれども。そういった部分で、先ほど子どもの理解というお話が出ていましたけれども、学校でそういった障害児、こういう子たちもいますという障害者教育というのですか、そういったものに関して取決め、教育委員会で例えばどういうことを教えているのかというのを教えてください。","respondent":"矢部教育総合支援センター長","answer":"特別支援学校のお子さんは、復籍交流といって、施設は全然遠いのですけれども、年３回ぐらいの学校行事に来たり、今、コロナ禍で難しいのですけれども、学級だよりを送ったりして、交流を進めているところです。","id":"exchange-013"},{"speaker":"松澤委員","kind":"質問","question":"センター長がおっしゃったとおり、私も保護者会に行ったときに、一度、親御さんがそのお話をされた。私の子どもはこういう形なのでよろしくお願いしますというお話をしたときに、衝撃で、今はそのように言わないといけないのかみたいな、何か寂しいというか、みんなで助けるのだというのが当たり前の世の中ではないですか。やはりお互い気を遣っていかないといけないのかというのが大いに感じております。","respondent":"矢部教育総合支援センター長","answer":"当然、特別支援学級が併設されている設置校については、その理解を深めなければいけませんので、４月５月の学校だより等で、また、保護者会等で説明させていただいているというところです。","id":"exchange-014"},{"speaker":"松澤委員","kind":"質問・要望","question":"結論を出すでお願いします。不採択でお願いします。先ほどいろいろお話がありました。いろいろな課題があるのですが、制度に現状入らないといういろいろなお話の中、区としては、特別支援教室での増員なども一生懸命やられている姿が感じ取れます。いろいろと今後とも制度の状況を見ながら、一生懸命進めていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"つる委員","kind":"質問・要望","question":"本日結論を出すで、態度は不採択です。通級の利用のところについては、制度に対する理解というのですか、現状の中で当該児童が行かれても、お子様に合った支援がなかなかこれは本当に心苦しい点もあろうかと思いますが、制度上できないというところがあろうかと思います。ここはやはり違う観点で求めていかなければならないのかというところにおいて、この陳情については、不採択ということにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"採択です。インクルーシブ教育の環境整備の方向性について、区教委としても、その必要性は認めておられます。障害者権利条約にうたう合理的配慮というのを実現するためには、やはりこの陳情を採択して、支援員の拡充と様々な場の拡充について、区議会から行政にその実施を私は促すべきだと。後押しと言ってもいいのですかね。なので、採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"本日結論を出すということでお願いいたします。大変だと。それが先ほどの合理的配慮、教員の負担過重になってはいけないというのが合理的配慮ということであれば、支援員の拡充というのは学校こそが求めるべき、校長こそが求めるべきだと思っています。それをこの陳情者の方は、教員への配慮を示されて、国連障害者の権利条約第２４条で保障されている権利を実現するために、支援員の拡充を求めておられます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"松本委員","kind":"提案","question":"本日結論を出すで、不採択でお願いします。これは我々議会、議員としては、これを採択するという方向に持っていくよりも、何ができるのかということを提案する方向でやっていくのが我々の職務かと思いますので、本陳情については不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"}]},{"id":"topic-03","title":"令和３年陳情第４７号、区立学校の新型コロナウイルス変異株の感染予防対策に関する陳情","agenda":"令和３年陳情第４７号、区立学校の新型コロナウイルス変異株の感染予防対策に関する陳情","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"ガイドラインなのですが、通知が来たので改定するということでしたけれども、６月３０日から２学期が始まる前までに、改定の検討というのですか、改定するかどうかという検討というのはあったのかなかったのか、伺いたいと思います。","respondent":"矢部教育総合支援センター長、勝亦学務課長","answer":"ガイドラインにつきましては、何回も協議をしていますけれども、特に学校の行事については、一刻一刻、予定が詰まってありますので、そこについての改定はしてまいりましたけれども、大きなところ。学校現場におきましては、全校におきまして、年間２回、全ての学校で薬剤師会に委託いたしまして測定を行ってあります。１,５００ｐｐｍを超えたという、基準を超えたということはございませんので、そういった状況です。","id":"exchange-020"},{"speaker":"安藤委員","kind":"確認","question":"３０日に改定、そこから９月１日までにそういう検討も行われなかったということでいいのかというのを確認させてください。全校で一斉にやるものなのか。そこら辺をお伺いしたいと思います。それとあわせて、２学期開始以降の感染状況を伺いたいのですけれども、区立学校での感染者数、子どもと先生の数それぞれ、それとあと、学級、学年、学校閉鎖の有無、あったのかなかったのか伺います。","respondent":"勝亦学務課長、工藤指導課長、矢部教育総合支援センター長","answer":"直近の検査につきましては、７月、８月に全校で実施をしております。続きまして、感染状況ですけれども、２学期以降の児童・生徒の感染者数です。９月、２学期始まって以降の教職員の感染状況ですが、９月以降はゼロです。３０人近かった学校も１２人ということで、大分減少しているという状態です。タブレットを教室に設置して、やっている授業をそのままライブ配信をしている学校もありますし、また、その場合。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"同時に、そういうお子さんに対してはこういう形で学びを保障していますというような、学校、教育委員会からの強いメッセージというのはすごく大切なのではないかと思いますので、そういった点からも、マスクの着用というのは、不織布マスクが効果があるというのは当たり前なことなわけですから、少なくとも、少しでも感染のリスクを下げるという点では。","respondent":"有馬庶務課長","answer":"大きなところでいきますと、まず、教育活動について、学びの継続と保障というところで、まずはガイドラインに基づいた感染予防対策を徹底した上で学校運営を継続するようにお願いしますということをまず言った上で、基本的には、あのときはまだ感染が続いていましたので。","id":"exchange-022"},{"speaker":"安藤委員","kind":"確認","question":"実施状況は学校によると思うのですが、実際、学びの保障というのはどれだけされていると感じているのかというか、ライブ配信で朝夕のみ確認し、紙で課題、様々あるとおっしゃいますけれども、実際それらがどれぐらいの規模で、規模というか、そういうお子さんがいた場合、実際どれぐらい行われているのかということと、それで、実態として学校に行けない。","respondent":"工藤指導課長","answer":"現状でいえば、タブレットで可能ですので、例えば、ｅライブラリアドバンスを使っての学習の指示であるとかも含めながら、学級担任から児童・生徒に対してはきめ細かく対応していると考えていますので、お休みいただいた中での学びの保障、その補充の観点からも。","id":"exchange-023"},{"speaker":"吉田委員","kind":"質問","question":"今、学校としても、いろいろな通達とか、そういう通知をされているということを伺いましたが、それは夏休みが終わる前にされたのか、それとも、その後だったのか。時系列の事務的な話ですけれども、お伺いいたします。","respondent":"有馬庶務課長","answer":"今、私が出した通知というのは、最終的には８月３１日付で学校には出しておりますけれども、学校はある程度そういう方針でいくというのは分かった内容で発出したという状況です。","id":"exchange-024"},{"speaker":"吉田委員","kind":"質問・要望","question":"ですから、そういう意味で言えば、８月３１日時点で、明日から２学期だというときに、この陳情者がこういう心配をされて、議会のこの議論の仕組みとかもご存じないでしょうから、今だったら間に合うかもしれないということでこの陳情を出されたということについては、実際の保護者の方ですから、いろいろホームページも調べた結果、それが見えないということで、この陳情を出されたというのは。","respondent":"有馬庶務課長、勝亦学務課長、矢部教育総合支援センター長","answer":"私からは、マスク、これは現場のほうにも実は校長先生も何人か相談していますが、やはり現場でも徹底というところは難しいという声を聞いています。こちらのほうでも、先ほど申し上げました検査につきまして、各フロアにおいて検査を行っておりますので。ガイドラインのことですが、基本的には、お子さんを守る感染防止、健康第一のための基本方針ですので、今言ったご意見からすると。","id":"exchange-025"},{"speaker":"吉田委員","kind":"質問","question":"不織布マスクで、子どもたちのこともあって、子どもたち、本当にそれぞれ状況がありますので、現に息苦しいだけではなくて、いろいろな身体的な理由でマスクがしにくいという子どものこともニュースなどでは報道されておりますので、そういう子たちへの配慮は当然必要だと思いますけれども、排除とか、そういうことにつながってはいけないと思いますので、その辺は配慮は必要だと思いますが。","respondent":"勝亦学務課長","answer":"子どもたちへの不織布マスクについてです。学校生活の中におきまして、例えば、忘れてしまった、汚してしまった等の対応につきましては、不織布のものを臨時的にお渡しできるように備蓄しています。","id":"exchange-026"},{"speaker":"吉田委員","kind":"質問・要望","question":"ごめんなさい。一律で配るというよりも、なかなかそういう毎日替えるような状況ではないお子さんが、心おきなくマスクができるような状況を求めたつもりですので、その辺については、きちんとそのお子さんも、自分はそういうマスクをする用意が、学校で配慮されているのだということが分かるような形になっているか、もう一回だけ。","respondent":"勝亦学務課長","answer":"経済的な事由のご家庭につきましては、就学援助等で現状支援を行っています。マスクの支援という形は、具体的には行っていない状況です。","id":"exchange-027"},{"speaker":"松澤委員","kind":"質問","question":"あれは子どもたちにもすごく評判で、きちんとオンラインで授業をやっていたよ、何々ちゃん元気だよとか、そういうのがよく聞こえているので、そういった部分で学びの保障というのはしっかりやっていただいていて感謝しているのですけれども、不安で来られないお子さんの数というか、それが本当にコロナなのか、また違う形で問題なのかというのはすごく難しいと思うのですけれども。","respondent":"矢部教育総合支援センター長","answer":"ただ、もう一方で、おうちの中に疾患を抱えているご家族とか、ご自身もそうでしょうけれども、そういう場合はあくまで不安ということが原因でお休みになっていると認識しています。","id":"exchange-028"},{"speaker":"松澤委員","kind":"質問","question":"そうしますと、濃厚接触者になってしまったとかいう場合はオンラインでやっていただいていて、そういう不登校気味の方、不登校の子たちに関しても、同じようにオンラインでやるのか、それとも個別でやるのですか。","respondent":"矢部教育総合支援センター長","answer":"方法で多いのは、教員と黒板をバックに映している形。中には本当にきめ細かく、Ａ君、Ｂさんということで、一つ一つの質問や、みんなで協議するときは部分的に入ってくるというような工夫をしている学級もあるようです。","id":"exchange-029"},{"speaker":"松本委員","kind":"質問","question":"どうしてもつけたくない、思想上つけたくないのだという方たちも世の中にはいらっしゃって、そういう人たちに対してそれぞれ、教員でそういう人たちがいた場合に、これはやはり子どもたちの安全の面から、布マスクとかでもウレタンでもない、完全につけないという人がいらっしゃったときにどう対応するのかという対応策と、あと、お子さんで。","respondent":"工藤指導課長、矢部教育総合支援センター長","answer":"教職員でマスクをつけないという、仮定のところですけれども、基本的には、現状、３密の回避であるとかと併せて、マスクをしないでの会話というのが、やはり感染予防の観点からすると、非常に今。こちらのガイドラインも含めて、国や東京都でも推奨ということですので、お願いはしていると思いますけれども、実際に大声を出さないとか、できるだけ飛沫が飛ぶような行為はお互い、ＡさんだけではなくてＢさんも気をつけるというのは。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問","question":"分かればでいいのですが、９月１日で、様々な事情で登校されないお子さんの数は先ほど３９５人ということだったのですが、参考までに、昨年の９月１日とか、一昨年の９月１日の状況が分かれば、もし分からなければ、どれぐらい増えているのかというのを、感触だけでも教えていただければと思います。","respondent":"矢部教育総合支援センター長","answer":"正確な数字はお答えできないのですが、昨年９月の下旬に調べたときは、コロナ不安は二十数名だったと記憶しておりますので、現状は、この９月１日については、今年度については増えていると認識しております。","id":"exchange-031"},{"speaker":"松澤委員","kind":"質問・要望","question":"結論を出す、不採択でお願いします。いろいろお話を聞いてまいりましたけれども、品川区としては、一生懸命取組が見えますので、継続して頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"つる委員","kind":"質問・要望","question":"理由は、各委員の質疑を伺っている中で、これまでも、今も、また、これからもしっかりと対策を取り、ずっと取っていくということが示されていることを理解いたしました。４点目のガイドラインについても、改定が随時行われると。そういったことも含めて、ここに挙げられていることについては、教育委員会、各学校においても対応が取れているというところで、不採択とさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"安藤委員","kind":"意見","question":"そういう意味で、陳情にありますように、この内容は、せめてこのぐらい、最低限の感染対策というところがありましたけれども、私もそれはそう思いますし、やはり見える化で、学校がどういう状況になっているのかというのを、最低でもそういった情報というのを保護者のほうに伝えていくことで生まれる安心感というのもあるでしょうし、これは採択すべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問・要望","question":"マスクについては、先ほども言いましたけれども、強制とか徹底とか推奨とか、そういう言葉がすごく、具体的にどの言葉がどう定義されているかということはいろいろ議論があると思いますけれども、ぜひマスクは進めてほしいということで言えば当然のことですし、それから、二酸化炭素濃度計についても、これがあれば逆に、これからの季節、暖房をかける季節になります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"松本委員","kind":"意見","question":"本日結論を出すで、不採択でお願いします。マスクのところは、かなり推奨という形でできることはやっていらっしゃると思います。以上、できるところはやっていらっしゃるので、今回の陳情については、不採択というところで申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"}]},{"id":"topic-04","title":"令和３年請願第１０号、デルタ株の感染爆発の中で迎えた２学期 子どもたちを守り、成長と学びを保障するための緊急請願","agenda":"令和３年請願第１０号、デルタ株の感染爆発の中で迎えた２学期 子どもたちを守り、成長と学びを保障するための緊急請願","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"質疑の前にぜひ意見陳述をされたいということですので、陳述を伺った上で、請願の審査にも活かしたいと考えています。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問","question":"生活者ネットワークとしても、意見陳述していただくなら、やはり審査に活かせるように、先にぜひ伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"安藤委員","kind":"質問","question":"一般質問でも、学校の感染の状況についての質問とかがありまして、答弁もあったと思うのですけれども、改めて、今年度に入ってからの学校の感染の実態について伺いたいのですが、４月以降の感染者数、小学校、中学校それぞれ、あと、子どもと教職員の内訳、それと、今年度に入って、学級閉鎖ですとか学年閉鎖、学校閉鎖、それぞれ何回ずつ発生しているのか、伺いたいと思います。","respondent":"勝亦学務課長、廣田子ども育成課長、工藤指導課長","answer":"学級閉鎖等々につきまして、２学期以降また、４月以降も学級閉鎖は実施しておりませんけれども、一部。すまいるスクールについては、預かりを休止したのは８月１２日から２６日、大井第一のみで、これは前回の文教委員会でご説明申し上げたとおりで。教職員の感染者数ですが、４月以降９月、先週末までの現在で３７名でございました。","id":"exchange-039"},{"speaker":"安藤委員","kind":"質問","question":"結構大事だと思うのが、濃厚接触者は２週間の出席停止になりますけれども、いわゆる周辺の検査対象者の検査の場合は、検査を受けたというだけでは出席停止にはならないで、検査結果が出るまでは登校控えというのはあるかもしれないですけれども、出席停止にならないというところも示されておりますが、でも、文科省の８月２７日付の対応ガイドラインを受けて、今現在、区教委としては。","respondent":"勝亦学務課長、廣田子ども育成課長","answer":"一般的には、１メートル以内でマスクなしで１５分以上接触したというようなものがあれば、濃厚接触者として検査対象としているような状況です。ですので、何人だからということではなく、すまいるスクールの中で感染者が複数人出て、保健所の判断により、すまいるスクールで預かりを続けることによって感染が広がる可能性が否定できない場合には閉めるという形で捉えております。","id":"exchange-040"},{"speaker":"安藤委員","kind":"質問","question":"よくはっきりと分からないのです。今までとあまり変わっているという印象がないのです。あわせて、検査キットの話がありましたけれども、全国の小・中学校で８０万回分が配布ということで、品川区にも今月中に来るということなのですが、これは区教委としてはどのように活用するというお考えになっているのでしょうか。具体的な活用方法というのですか、どのように考えているか、あわせてお伺いします。","respondent":"勝亦学務課長、有馬庶務課長","answer":"基本的には、保健所の対応の中で、これから発症するであろうという疑いの強い方を検査の対象にしていくという考え方で実施してまいりますので、全員に検査を行うという対応は取っていない状況です。ただ、小学校４年生以上も実施することは可能ですということは書いてありますけれども、先ほど少し触れたように、子どもの鼻腔を医師免許がない人がやるのは難しいだろうということで。","id":"exchange-041"},{"speaker":"安藤委員","kind":"質問","question":"検査キットのほうは、検体を取るのはかなり大変なので、何で検査キット、こういう抗原検査のにしたのかというのはそもそも論としてあるのですが、高齢者施設でやっているような、唾液で即、短時間で取れるＰＣＲ検査のほうがよっぽどいいのではないかと思うのですけれども、これが来たものですから、現場としてはどう活用するかということを考えていくということだと思うのですが。","respondent":"勝亦学務課長","answer":"コロナ対応の検査についてです。こちらの、今おっしゃいました保健所の対応ですけれども、品川区におきましては、こちらの通知の、現場での濃厚接触の判断という形は取らずに、保健所のほうで変更なく、濃厚接触の判断、検査時期の判断等を継続して行ってまいりました。","id":"exchange-042"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはりしっかりとそういう学校での現場の判断で、別に検査をやって陰性だったら、それで安全だということが分かるだけなのですから、別に検査をやることで濃厚接触者の周りの、さっきも紹介しましたけれども、検査をやることで待機になるわけではないのですから、だから、子どもにとっても、自分が今、感染しているかどうかをはっきりさせられるという、ただメリットしかないのです。","respondent":"矢部教育総合支援センター長","answer":"２点目の話合い活動についてですが、コロナにということだけで申し上げると、先ほど各学習の中で取り上げると同時に、自宅待機になってしまうお子さんの話も含めて、各クラスの実態に応じて、担任と話す場合もありますし。","id":"exchange-043"},{"speaker":"安藤委員","kind":"質問・要望","question":"それぞれ区内の実施状況、どうなのでしょうか。区教委としても、財政面も含めて、最大限支援すべきだと思うのですけれども、いかがでしょうか。昨年度もそういう状況だったのですけれども、いろいろな支援、工夫をして、区教委としても後押しして、様々な代替行事も行われたと認識していますが、そういったことも含めて支援をすべきだと思うのですけれども、いかがでしょうか。","respondent":"勝亦学務課長、矢部教育総合支援センター長","answer":"今年度、６年生、それから７年生、８年生が移動教室を実施する予定でございました。本来ですと、７年生なのですけれども、昨年度、７年生の移動教室ができませんでしたので、今年度、８年生として実施する予定でございました。修学旅行についてです。１５校中２校で既に実施しておりまして、５校は、この９月１０月が予定でしたけれども、全て延期と聞いています。１校、中止を検討していますが、その際も代替をしたいという意向です。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問・要望","question":"なおかつ心のケア、そういう意味では、本当に行事というのは、いろいろな工夫をして、最大限に保障してあげるというのが大人の、教育委員会としてのやるべきことかと考えていますので、様々工夫をするということですが、例えば、今年の６年生というのは、昨年の５年生のときに林間学校が中止となり、前期課程というところで、今年も中止になってしまうと、５年生６年生で何もないというような、そういう。","respondent":"勝亦学務課長","answer":"これまでも何とか実施できないかということで、様々な手法、実施のタイミングですとか、方法を研究してまいりましたけれども、残念ながら、現状はできていないということで、今後、相談してまいりたいと考えております。","id":"exchange-045"},{"speaker":"吉田委員","kind":"質問・要望","question":"私からは、先ほどすまいるスクールの職員、また教職員の方たちへのご要望に対して、ご答弁が、聞き間違いでなければ、感染予防に資するに適切な時期と回数でしたか、そういうことで判断して実施しているということだったのですけれども、具体的に感染予防に資する適切な時期と回数というのはどういうことなのか、ぜひ教えていただきたいと思います。その辺、ぜひ教えていただきたいと思います。","respondent":"廣田子ども育成課長、有馬庶務課長、矢部教育総合支援センター長","answer":"その間にもし感染した方と接触した場合においても、すぐに検査しても陽性とは出ないので、接触して５日たってからであるとか、適切な時期に検査をしないと。教室の関係ですけれども、この請願の項目だと、ゆとりのある教室空間を確保するというところですから。基本的に、必要に応じて対応するということになりますが、例えば、いじめがあった、不登校が長引いている、また、虐待の案件、非行傾向、ご家庭の様子。","id":"exchange-046"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。この数は、品川区としては十分な数なのでしょうか。区としては、国から来るから使おうかではなくて、今後の検査の体制を構築した上で、今の検査キットの活用と、それから、今後、都なり国なりにこういうことを求めていく全体の検査体制というのを、今、構築していくべきではないかと思うのですけれども、この辺について検討されていることがあれば、伺いたいと思います。","respondent":"有馬庶務課長","answer":"義務教育学校が４箱、それから、幼稚園が１箱ということなので、小・中学校でいけば、２０回から３０回分ということで来る予定になっているということですので、常時定期的に使うというよりは、具合が悪くなった先生に対して。","id":"exchange-047"},{"speaker":"吉田委員","kind":"質問・要望","question":"国の枠でそういう数になるということですよね。分かりました。第６波も必ず来るとおっしゃっている方もいらっしゃいますし、そこはやはりもう少し想定しておくべきなのではないかと思うのですけれども、今現在はそういうことだと思いますが、ぜひ検討していただきたいのですけれども、その辺についてお考えを伺いたいと思います。","respondent":"有馬庶務課長","answer":"基本的には、朝から具合が悪ければ、教職員の方も出勤を控えてくださいということもお願いをしているところですので、今回配られるものがどの程度使われるかというところを見て判断していきたいと考えております。","id":"exchange-048"},{"speaker":"吉田委員","kind":"質問・要望","question":"なので、マスクの着用とか、そういうこともすごく強めに要望されるところもあるかと考えています。ぜひ今後は、無症状者をどのように捉えていくかということと、あとは、やはり子どもの心のケアということと、それから、子どもの意見をきちんと聞くというところをもう少し考えていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"安藤委員","kind":"意見","question":"ぜひ積極的に議会としてもそういった意見陳述のご発言があれば、受けていくと。さらに充実した審査にしていくという姿勢が私は大事だと思いますので、受けるべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"吉田委員","kind":"質問","question":"私も、この請願文を読ませていただいて、一生懸命読み解いて、それに沿った発言をさせていただいたつもりなのですけれども、かなり詳細にわたっておりまして、本当にこれだけで十分だったのかということについては、ぜひ請願者のご意見を伺った上で判断したいと思います。ぜひ意見陳述は認めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"松本委員","kind":"質問・要望","question":"私も意見陳述していただきたいと思っています。先ほど冒頭か質疑の後かで冒頭ではないということだったのですけれども、逆に、請願者の方たちにも、委員会の審議を受けて、やはりこうではないかというような話とかも出てくる可能性もありますので、それはやはり冒頭ではないのだったら、むしろこのタイミングでおっしゃっていただくというのが大事かと思いますので、意見陳述していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"つる委員","kind":"確認","question":"今の質疑、それから、請願の内容、十分に理解できました。今の質疑の中で、紹介議員に名を連ねていらっしゃる会派の方たちがるる質疑をされてましたので、そうした質疑の様子を見ても、紹介議員になられている会派の方たちが積極的に聞かれていろいろなことを質疑の中で確認したのだけれども、それを拝聴する中で十分理解できましたので、私は結構だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"安藤委員","kind":"質問・要望","question":"３対３という形で、委員長裁決ということですが、受けない判断に至った委員長としてのお考えを聞かせいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"松澤委員","kind":"意見","question":"結論を出すでお願いいたします。不採択でお願いいたします。理由としましては、今いろいろと、マスクのお話なども出ておりましたが、共感するところもありますが、行政としてはよりよい取組を推進するということを聞いておりますので、不採択とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"},{"speaker":"つる委員","kind":"確認","question":"理由は、この緊急請願の主題にある中で、成長と学びを保障するためというのが目的で、その項目においては、それは手段ということで、今の質疑、それからご答弁を拝聴する中で、この請願で挙げられている項目についても既に実施済みであったり、実施されている、また、用意をしているというご答弁を確認ができ、そうした意味で、子どもたちの成長と学びを保障するという目的に向かって、今の話。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"安藤委員","kind":"確認","question":"ですから、スクールカウンセラーも充実が必要です。第６波が来ますということです。第６波が来たときに、また子どもが危機にさらされて慌てるのではなくて、今だからこそしっかりと学校で感染を防ぐような体制を取っておくべきなのではないでしょうか。方向性も確認できたから採択できないということですが、むしろそれなら採択すべきなのではないかと私は思います。それが不採択の理由にどうしてなるのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ請願の趣旨をよく読み取っていただきたいと思います。その中でもやはり子どもの意見を聞いてほしいというのが、子どもたちからも、本当だったら学校の中でもっと自分たちの意見を聞いてほしいという声が上がって、それが区教委に伝わっているべきだと思うのですけれども、それがないというのが、それが不安の種というか、生活者ネットワークとしては不安に思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"松本委員","kind":"意見","question":"この請願ですけれども、本日の審議の中でもいろいろ意見が出ておりましたけれども、私もやはりぜひやってほしいという部分もありますし、一方で、だからといって議会として採択できるかといったら、例えば、抗原検査の点です。では、どう考えていくかですけれども、例えば、海外の事例を見ると、学校でやるのではなくて、各家庭に配布するという手段もあるかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"１日目の石田秀男議員の総合実施計画についてのご質問についてです。多岐にわたったご質問だったのですけれども、その中に児童相談所の人材確保についてのご質問がありました。この委員会で、この所管でよろしいですよね。どのような人材を任期付で採用して、どういうところで活用しようとしておられるのか、もう少し詳しくお話を伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/186280?Template=document&Id=5042#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":51649,"voices":175}},{"id":"r03-20210921-5","meetingId":"r03-cm09","date":"2021年9月21日","dateIso":"2021-09-21","committee":"総務委員会","time":"午前１０時００分～午前１１時１５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"田中委員","kind":"質問","question":"先ほどの所管質問のところで、一般質問のところから質問したいのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"田中委員","kind":"質問","question":"すみません。２点目は、石田秀男議員の質問で、企画部長がお答えだったので総務委員会で伺えると思うのですけれども、新庁舎に関連して、にぎわいゾーンへの質問に対して、多くのにぎわい集客ができる施設が必要といった趣旨の答弁をされていたと思うのですが、もう施設建設についての想定などがされていて、計画などがあるのかといったところを伺いたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"おくの委員","kind":"意見","question":"大規模改修工事ということで、耐震化改修工事というのは本当に改修だなという形で分かるのですけれども、まず、耐震化改修工事というのは、どの程度の耐震性を今まで持っていたものが、どの程度のものになるのか、その辺のことをもう少し具体的に説明願いたいのと、それから、耐震性を向上させるというようなものが改修に当たるのは分かるのですけれども、舞台機構の改修工事で。","respondent":"小林施設整備課長","answer":"舞台機構のご質問があったかと思いますが、まず、ご質問にありましたエレベーターにつきましては、舞台にエレベーターが設置されるわけではありませんで、８階から９階部分にある客席のところを上下するような、人が移動できるようなエレベーター。","id":"exchange-003"},{"speaker":"田中委員","kind":"確認","question":"契約の中で、この改修工事が環境に配慮して行われるのかといった点と、また、トイレの改修もあったのですけれども、その際にユニバーサルベッドが契約の中にあったのかという点と、また、今、ホールのところに、親子が過ごせる親子ルームのようなものがあったと思うのですけれども、そこなどはぜひこれからも、授乳スペースであったり。","respondent":"小林施設整備課長","answer":"３点のご質問のうち、まず１点目、環境に配慮という点ですが、今回、機械設備につきましても、電気設備につきましても、大規模な改修を実施するところです。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"８０億円近く。実際、大規模改修工事に関しては、結構それなりにかかるのかと思うのですが、参考にお聞きしたいのですが、機械のほうも、電気設備のほうもそうですが、一体、一番高額な、これにすごく金額がかかるのですよというものを、参考にそちらを教えていただけませんか。","respondent":"小林施設整備課長","answer":"特に空調におきましては、空調熱源を替えますと、それだけで何億円というお金が支出されますので、そういった機器については非常にお金がかかってくるというふうに認識しています。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"そうすると、割と割高なのかなというふうに思いましたけれども、夜間工事云々ということもありましたので、ただ、金額的にはかなり高額なので、少しお聞きしました。営業しながら作業をする場面もあるでしょうし、また夜間工事ということもあって、人通りも多い場所なので、十分、人の往来に配慮して、事故のないように進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"すみません。先ほど、トイレのところで聞き忘れてしまったのですけれども、男性トイレの改修の中に、子どものおむつ替えベッドや、個室に子どもを座らせられるシートというか椅子というのが契約の中にあるのかどうか、もし確認ができたらお聞かせいただきたいのですけれども。","respondent":"小林施設整備課長","answer":"ベビーチェア、ベビーシートのご質問ですが、もちろん全てのブースではございませんが、一定程度、ブースの中にスペースをとっておりますので、１つのトイレの中に１つだけでも作れるような計画で、今回は進めているところです。","id":"exchange-007"},{"speaker":"渡部委員","kind":"質問","question":"というのは、やはり、今、須貝委員が言った話ではないですけれども、七十何億円というお金がどーんとここに行って、機能が維持されるのだけれども、であれば、もし、あと何年か延ばせば、区の新しいものを作るというところにまた機能集約なども可能だったのかなと思ったりもしたのですが、その辺、何か考えがあったのかどうか、３点お伺いできればと思います。","respondent":"小林施設整備課長、篠田文化観光課長","answer":"本来でありますと、これに併せて共有部分の配管などもやれるといいなと思っていたところですが、やはりなかなか、テナントさんのほうの休館などは難しいなどいろいろなことがございまして、今回聞いている話の中では。私からは、休館に関してのご説明をします。今回の工事につきましては、年明けの２月１日から全館、きゅりあんに関しては休館を迎えます。","id":"exchange-008"},{"speaker":"渡部委員","kind":"質問","question":"ありがとうございました。一度その概略を聞いておこうと思って聞いたのであれなのですけれども、休館に関しては、これはまた契約の問題になると思うのですが、あそこは業務委託でしたか、やってもらっている業務のところが、それだけの長い間休館になると、例えば、お願いしている業務内容なども変わってくると思うのですけれども、その辺の変更だとか、継続性だとかというのを考えて、何かあるのでしょうか。","respondent":"篠田文化観光課長","answer":"それぞれの業者さんも、私どものきゅりあんだけを持っているわけではございませんので、ほかのそれぞれ管理している施設等に、恐らく回っていただくなどしながら、最終的に開館したときにはまた今までどおりきちんと継続していただくということで考えているところです。","id":"exchange-009"}]},{"id":"topic-02","title":"取り上げる順番を変更し、(8)第６１号議案 しながわ区民公園北側ゾーン改修工事（第一期）請負契約","agenda":"取り上げる順番を変更し、(8)第６１号議案 しながわ区民公園北側ゾーン改修工事（第一期）請負契約","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"このしながわ区民公園に関しては、これまでもいろいろ議論があったようなので、念のため伺っておくのですけれども、周辺住民の皆さんから様々なご要望があって、建設委員会などで議論があったと聞いているのですけれども、今回の工事に関わるご要望にはどのようなものがあって、どのように対応されてきたのか、そして今後どのように対応されていくのか、この点、念のため伺っておきたいと思います。","respondent":"高梨公園課長","answer":"しっかりと、伐採だけではなく、新しい樹木を植える、そういった意味で、また新しい緑を更新していくといったところで、改修後の区民公園もまた、緑を大切に愛していただきたいといったところを区からは説明し、ご理解をいただいているというふうに認識しています。","id":"exchange-010"},{"speaker":"おくの委員","kind":"質問","question":"今後、説明会などを予定されているというふうに伺っておりますけれども、その理解でよろしいですか。","respondent":"高梨公園課長","answer":"今回お諮りさせていただいている第一期工事につきましては、この後、契約した後の本年１２月に工事の説明会を開催したいと、このように考えているところです。","id":"exchange-011"},{"speaker":"須貝委員","kind":"確認","question":"今回、労務単価の改定ということで、特例措置ということなのですが、労務単価の積算が変わって、今回こういうふうにアップ、増額するわけですが、それが間違いなく労務単価に流れているよとか、そこの確認は、別に区でできるわけではないのですよね。その点についてお聞かせください。すみません。労務単価について聞かせてください。","respondent":"東野経理課長","answer":"実際の支払いにつきましては、会社のほうでということになりますので、その確認まで区のほうでは致しておりません。ただ、この内容から、もちろん賃金のアップにつながるという部分での措置となりますので、会社のほうで適切に支払いを行っているものと推測されます。","id":"exchange-012"},{"speaker":"おくの委員","kind":"質問","question":"設計労務単価の変更に伴ってやっていることですけれども、この設計労務単価、国のほうでいつも変更しているみたいですが、上がるときもあれば下がるときもある。こういう特例措置というのは、いつもやっているのですか。下がるときもやったりしているのでしょうか。その点をお伺いしておきたいのですが。","respondent":"東野経理課長","answer":"こちらの設計労務単価の特例措置ですが、平成２５年度以降はずっと上がり続けている状況です。下がった場合につきましては、当然、会社側で考えるという部分になってきますので、恐らく会社側からの請求、事業者側からの請求というのは、そういう意味ではないと思われます。","id":"exchange-013"}]},{"id":"topic-03","title":"第６０号議案 戸越台複合施設大規模改修工事請負契約の変更","agenda":"第６０号議案 戸越台複合施設大規模改修工事請負契約の変更","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"ないようです。先ほど、平成２５年から上がる一方だという話ですが、上がるのは、それはそれで制度として、私は致し方ないのかなと、国で決めているから。でも、下がる場合もあるので、上げているなら、やはり下がることもありますよということを、きちんと制度の１項目に入れておくべきではないかと思うのですが、その辺について、考え方だけお聞かせください。","respondent":"東野経理課長","answer":"民間ではないというお話ですが、民間は契約当事者で対応を図っているということで理解しています。区としましては、契約書に記載のこの条項を適用することで、公共工事の品質の確保、それから適正な賃金水準が長期の工事でも保たれるというふうに考えているところです。","id":"exchange-014"},{"speaker":"たけうち副委員長","kind":"質問","question":"関連で、工事のところで、電気設備と機械設備の工事が上がっていますけれども、こちらはこの条項に、期間とかいろいろなことで当てはまらなくて、こちらはならないということでいいのか。それとも、何か業者のほうからの請求がなかったということなのか、もし分かれば教えてください。","respondent":"東野経理課長","answer":"関連工事につきましては、特に請求がないものとして取り扱っております。","id":"exchange-015"},{"speaker":"渡部委員","kind":"確認","question":"１点だけすみません。今回のインフレスライド条項の適用に関しては、先ほどデフレーションの場合という話もあったのだけれども、あくまでも動きを見て、行政側がこういうふうにこれを適用したほうがいいなというものに対して、業者さんのほうに、事業者さんのほうに声をかける仕組みという、基本的な捉え方というのはそれでいいのでしょうか。","respondent":"東野経理課長","answer":"ただ、区としては、事業者さんといろいろ工事のところでのお話もしていますので、こういう制度が適用になるのではないでしょうかというようなお声かけはさせていただいていると聞いております。","id":"exchange-016"},{"speaker":"渡部委員","kind":"意見","question":"今、何でそれを聞いたかというと、２１ページのところの文言と、先ほどの１９ページのところの文言を読み比べていたのですね。１９ページのところだと、業者の申し出によりというところで、２１ページのところだと、まず品川区が決定して、それから業者に伝えたのだな、要するに、適用を決定したと。これを受けて、請求者より契約金額変更の請求があったと。","respondent":"東野経理課長","answer":"そういったところから考えますと、事業者からの請求があるか、ないかによって、適用されるかどうかという部分にかかってくるものです。","id":"exchange-017"},{"speaker":"渡部委員","kind":"質問","question":"多分、ここにいる皆が思っているのは、請求があったから適用されたのか、適用したから請求したのか、どちらなのかと。では、どちらが正しいですかということで、それによってはこの文章が間違っていますよねという話です。","respondent":"渡辺委員長、東野経理課長","answer":"２１ページの変更の概要のところを指摘されているかと思いますので、そこの表現の仕方を含めてご説明いただけるといいのかなと思います。それによりまして、区のほうでも適用になりますよというような決定をいたします。それで、事業者さんにホームページなどでお知らせしまして、事業者さんからの申し出によりまして、案件ごとに決定をとるというような流れです。","id":"exchange-018"}]},{"id":"topic-04","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"この請願の本文、理由の中にもありますけれども、昨年来のコロナ禍の中で非常に大変な状況になっていると思うのですが、他方で、ここで出されている軽減措置というのは、いずれもかなり前からのもので、特に１番はバブルのときのもので、昭和６３年からということですけれども、このコロナ禍の中で、さらなる軽減措置を求めるような声、あるいは。","respondent":"提坂税務課長","answer":"先ほど申しましたとおり、賦課徴収につきましては東京都が行っておりますので、直接、区のほうにそういうご要望は聞いてございませんけれども、実際に賦課した後で、徴収の段階になりまして、納税が難しいということになりましたら、都税事務所のほうで徴収猶予など。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"間違いなく今後下がっていく、法人税が減ってくるということは、財調もやはり減ってくるというわけで、いずれはそうなってきてしまうわけですから、抑えるところは抑えて、２３区でもっと配分されるところは今のうちに、私は、しっかり確保しておかないと、この先、法人住民税が減りました、皆さん、財調も減らしますなどというやり方で、品川区民を、２３区そうですけれども。","respondent":"提坂税務課長、桑村副区長、黒田財政課長","answer":"財調の件については、配分割合とか、その辺については東京都と区のほうで認識のずれがあるということは事実です。ストレートにお答えはしていませんけれども、そういう思いの中で、特別区の中でこれをまとめて。その際に、地方税制としてどのような、これは東京都に限らず、法人住民税というのは全国的にありますので。","id":"exchange-020"},{"speaker":"須貝委員","kind":"意見","question":"法人住民税ももちろん多い。かといって、地域の地場産業もしっかり見ていかなければいけないとなったときに、やはり今、都が潤っているさなかに、何とかそこの隙を突くというか、今後の、将来の２３区の在り方、品川区の在り方として、しっかり財源を、何かあっても大丈夫だよというものを、私はつないでいってほしいなというふうに思います。これは意見だけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"たけうち副委員長","kind":"質問・要望","question":"本日結論を出すで、採択で、意見書を提出させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"渡部委員","kind":"質問","question":"今日結論を出すで、両件とも採択。片方だけでいいのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"おくの委員","kind":"質問・要望","question":"結論を出すで、採択で、意見書も提出するということで求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/307500?Template=document&Id=2208#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":24195,"voices":163}},{"id":"r03-20210922-6","meetingId":"r03-cm09","date":"2021年9月22日","dateIso":"2021-09-22","committee":"区民委員会","time":"午前１０時００分～午前１０時４５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件抜き出しています。","topics":[{"id":"topic-01","title":"戸籍法施行規則改正に伴う届出における押印義務の廃止","agenda":"戸籍法施行規則改正に伴う届出における押印義務の廃止","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"届出用紙は在庫がなくなるまで使用するということですけれども、なくなるのはいつぐらいになる見通しかご説明いただきたい。区ホームページからダウンロードできるものは、もう既に９月１９日から公開されているということですけれども、「より記入しやすくする改良も加え」とありますけれど、どのような改良をされたのか教えていただきたいと思います。","respondent":"木村戸籍住民課長","answer":"各自治体から届出が、品川区に来るのですけれども、これはお客さんが書きやすいなというものを、職員の発想でここ３か月で練りまして、それをこの改良に反映させたです。","id":"exchange-001"},{"speaker":"くにば委員","kind":"質問","question":"１点だけ伺いたいのですが、婚姻届の枠の上部にある、品川区長の印であるとか、書類調査、入力、戸籍記載等は業務上で使うものなのですけれど、こちらには印鑑は使われるのでしょうか。","respondent":"木村戸籍住民課長","answer":"こちらには「印」という文字を記載しておりますけれども、基本的には使わないと。お客さん側が押していただく欄に、印鑑を押さないという形に今回なっております。","id":"exchange-002"},{"speaker":"くにば委員","kind":"質問","question":"ということは、庁舎内での業務上の印鑑を押さなければいけないという、いわゆる脱ハンコ化についてもかなり進んでいて、この欄も押さなくて済むようになったという理解でよろしいのでしょうか。","respondent":"木村戸籍住民課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]},{"id":"topic-02","title":"ダブルでお得！！しながわ商い活性化事業","agenda":"ダブルでお得！！しながわ商い活性化事業","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"１点だけ。プレミアム付区内共通商品券ですけれども、申込受付期間が８月３０日月曜日必着となっているのですけれども、住民の皆さんから、これは岐阜県宛てなので何日かかるかよく分からないから、３０日月曜日必着ではなく、３０日月曜日消印にしたほうが、いいのではないかというご意見を伺ったのですけれども、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"できるだけ消印有効という形で進めてもらえないかということで、再度、要望としてこちらのほうから伝えします。","id":"exchange-004"},{"speaker":"西村委員","kind":"質問","question":"２点お伺いさせてください。１点は、説明会を開催されるということで、説明をする方はＰａｙＰａｙの方なのか、それとも区のほうでするのか、教えてください。もう一つは、ＰａｙＰａｙに加盟する区内店舗が約５,０００店あるということで、加盟料はどれぐらいかかっているのか、教えていただけますか。","respondent":"遠藤商業・ものづくり課長","answer":"説明会ですが、こちらはＰａｙＰａｙの方がお見えになって、説明をいただける形になっております。","id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ＰａｙＰａｙのことをお聞きしますけれども、区内で加盟店が約５,０００店あって、私は小さい雑貨店も経営しているのですけれど、その５,０００店の中に私のところも含まれるのかなと思っています。このチラシというのは、５,０００店舗に対して、ＰａｙＰａｙから発送するのか。これＡ４判ですけれども、もう少し大きいサイズの啓発ポスターとかもあるのかどうかも、教えていただきたいです。","respondent":"遠藤商業・ものづくり課長","answer":"こちらのチラシも校正の段階での印刷ということで、紙が薄くなっておりますけれども、それぞれの店舗で、キャンペーンをやっていますよというのがわかりやすい、お客さんが見て分かるようなものを、それぞれの店舗に配布していただく形で進めておりますので。","id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"どうもありがとうございました。ぜひ、このＰａｙＰａｙでの決済は非常に、決済する方が多くなっていますので、ぜひ店舗にも見やすく貼っていただけるようなものを、もう少し検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"くにば委員","kind":"質問・要望","question":"幾つか伺います。最大３０％戻ってくるキャンペーン、多くの自治体が参加されて実施されていますけれども、これは自治体ごとに付与されるポイントが、１５％だったり、２０％、３０％のところもあれば、そこに関しては各自治体の予算によって何％にするというのが決まっているのでしょうか。それが１点です。その点について伺いたい。これも早め、早めにしたほうがいいと思うので伺いたいです。","respondent":"遠藤商業・ものづくり課長","answer":"ほかの自治体では２０％とか、いろいろあるというふうには聞いております。それから５億円を超えた場合のお話ですけれども、超えた場合でもやり続ける、期間で決めてくれという仕組みになっているようですので。ただ、５億円で１か月間足りるだろうという形で見込んです。","id":"exchange-008"},{"speaker":"くにば委員","kind":"質問・要望","question":"各種ご説明ありがとうございました。何にせよ３０％という大変強力なキャンペーンというか、ポイント付与なので、広報の部分は強くお願いしたいのと。ホームページという部分で、今、ＰａｙＰａｙはかなり力を入れて、テレビでもＣＭをやっているぐらいキャンペーンをしています。それを早めに。以上２点、要望という形でします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"横山委員","kind":"確認","question":"私からは２点確認させてください。いつ頃追加の予定なのか、教えてください。２点目が、下の小さなところに「ヤフーカード以外のクレジットカードは対象外」というふうにあるのですけれども、チャージのとき銀行の登録ですとか、そういった手続きがあると思うのですが、区民の方に手数料とかがかかるケースはどのようなときか、確認させてください。","respondent":"遠藤商業・ものづくり課長","answer":"それからクレジットカードの件ですけれども、ＰａｙＰａｙにひも付けするのに、自分でお金をチャージするという方法と、クレジットカードで行う場合、銀行口座で行う場合、この３つあるところで、そのときカードでのリンクもできるのですけれども。","id":"exchange-010"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ご説明ありがとうございました。商品券についてお伺いいたします。より多くの方に利用されるようにということで、この申込書にはお１人様８冊と書かれておりますが、先ほどのご説明では五、六冊になるということで、より多くの方に利用していただくということで上限があるということ、冊数が変更になるというのは、どこかに記載されているのでしょうか。それが１点です。","respondent":"遠藤商業・ものづくり課長","answer":"今お配りしているチラシの中の面の右側、ＳＴＥＰ１と書かれているところ、こちらに青い字で「購入希望数が多い方の購入数を減らしますので、ご希望の冊数を購入できない場合があります」と、このような形で周知させていただいてあります。","id":"exchange-011"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ありがとうございました。中に書かれているということで、確認させていただきました。特にこのことに関してお声が出ているのか、クレーム的なものがあるのかどうか、もっと買いたかったというような声が入っているのかどうか、あれば教えていただきたいです。使用率がほぼ９９％ということで、やはりすごい利用率だなと考えています。これは要望とします。","respondent":"遠藤商業・ものづくり課長","answer":"以前は買えない方がいたということでのクレームが、あったと聞いております。この形にしてから、買えなかった、使えなくなってしまったというようなお声はいただいてなかったので、この方式は非常によかったのかなと考えているところです。","id":"exchange-012"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"大ホールの工事内容について、結構大規模なイメージがあるのですけれど、これは何年に１回ぐらいの規模なのか、伺いたいです。難聴者対策設備改修工事ということですけれど、磁気ループの対応なのかどうか、その点だけ確認させてください。","respondent":"篠田文化観光課長","answer":"椅子もちょっとくたびれていますので、張替え等の工事を行うという形で考えているところです。それから、難聴者対策につきましては、磁気ループの導入工事という形で対応するものです。","id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/943539?Template=document&Id=2910#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":14231,"voices":51}},{"id":"r03-20210922-7","meetingId":"r03-cm09","date":"2021年9月22日","dateIso":"2021-09-22","committee":"厚生委員会","time":"午前１０時００分～午後 ２時１９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","topics":[{"id":"topic-01","title":"令和２年度指定管理者の管理に対するモニタリング・評価の結果","agenda":"令和２年度指定管理者の管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"一番初めにご説明があったように、今回、指定管理者のモニタリングのほうも見直しがされて、収支の、今までは、収入のところだけだったのですけど、支出のところも人件費、事業費、事務費等ということで記載されて説明がされるということになりまして、ここのところはずっと、収支の「支」もしっかりと報告をしていただきたいということで求めてきたのが。","respondent":"宮尾高齢者福祉課長","answer":"離職率に関してですが、まだちょっと令和２年度の詳しいデータが上がり切っていないというところはあるのですけれども、コロナが影響で区内の事業所に関して大きく落ち込んでいるという認識は持っておりません。","id":"exchange-001"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そういうふうなときに、利用料金と介護報酬というふうな扱いにしていただくと分かりやすいのではないかなというふうに思ったのですけれど、そういう記載はいかがでしょうかということが１点です。そういう方に対してはＰＣＲ検査を行うというのを原則にすべきだと思うのですけれど、そこのところは原則としてそういうふうになっていたのかどうか、その点も伺いたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"コロナ禍における面会ですけれども、こちらも副委員長お話しのあったとおり、やはり施設側としては、面会は実現はしたいが、そこから感染が広がってしまうというリスクを考えると、なかなかコロナ前のようにはできないというのは確かにあります。","id":"exchange-002"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ではちょっと引き続いて伺いたいのですけど、４１ページのさくら会の大井林町地域密着型多機能ホームの小規模多機能、ここで、通いが５６.０％で泊まりが２５.２％ということで、多分これは小規模多機能なので、先ほどのご説明でも訪問介護のほうが主になっているということだったので、私もそうだろうなというふうな思いを持っていたのですけれど、それだけの利用率でも赤字ではなくて。","respondent":"宮尾高齢者福祉課長","answer":"小規模に関しても看護の機能がついているということで、厳密にこれを横一線上で見るというのはちょっと厳しいところがあるというふうに認識をしております。","id":"exchange-003"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そういう点では、本当に今の利用者の方からも、何回かこの厚生委員会にも、今のサービスを継続してほしい、今の事業者を継続してほしいという、そういう陳情とかも何回か伺っている状況ですけれど、その辺のところでの説明会というのはどういうふうになっていて、引継ぎがどういうふうにされようとしているのかという点、また、不安のない形でやっていくのがすごく必要だと思うのですけれど。","respondent":"松山障害者福祉課長、築山障害者施策推進担当課長","answer":"ただし、改善につきましては、感染対策を取りつつ、やはり会館の強みを今後ＰＲしていく、最重度の方への介護、支援といった強みが会館にはありますので、そういった強みをＰＲしていくです。それから引継ぎにつきましては、ご利用者の心身の状態や、ご家庭の事情等を踏まえた継続的な支援を提供していくということが大事ですので、個別の３者、ご利用者、現指定管理者。","id":"exchange-004"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ぐるっぽは当事者それから障害者団体の皆さんから本当に様々なご意見、ご要望が出される中でこういう結果になったわけです。そういうノウハウもしっかりと学んでいただいて、次のところにつなげて、皆さんが本当にがっかりしないような形での対応、丁寧な対応をぜひともしていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これは評価をした事項でありますから、その評価した事項それぞれのところに、ここはこういう評価をした事項があって、この共有というのか、そういう共有化というのは、それぞれのところで、それぞれの所管で、それぞれの事業者と共有しているのかというのをお伺いしたい。せっかくこういう交流施設なのだから。今答えられなくても結構です。","respondent":"宮尾高齢者福祉課長、菅野高齢者地域支援課長","answer":"コロナを受けた流用等ですけれども、答えになっているかというところはちょっとあれなのですが、やはり令和２年度は、それ以前の年と比べて、予期せぬ対応にしっかりと対処するためということで。私どもも、今４か所のゆうゆうプラザを造って、次に、北品川シルバーセンターを改築後はゆうゆうプラザということを考えているところなのですが、やはりその中で、多世代交流が。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"最後に１つだけ聞きたいのはぐるっぽです。それも同時期に大田区にも同じような施設ができて、大変期待をしていた。ここのところは必ず出るわけだから、その辺のところは今度、ぜひそこは巻き返していただきたいなと思っているところがあって、今日はぜひその辺のところの意気込みだけ聞いておこうかなと思って、それだけちょっとお聞かせください。","respondent":"築山障害者施策推進担当課長","answer":"障害児者総合支援施設は、多くの区民の方から期待をされているということも認識をしております。障害児者の地域生活を支える拠点として機能ができるように、より総合機能を発揮しまして、障害児者の方を支えていけるよう取り組んでいきたいというふうに考えております。","id":"exchange-007"},{"speaker":"せお委員","kind":"質問・要望","question":"先ほど、品川児童学園のところで、医療的ケア児は一部受入れをしているというお話だったのですけれど、これは日中一時かなと思うのですが、ここはどういったところで受入れしているのかなというところと、来年指定管理者が変わるので、今後医療的ケア児に関してはどういったところを考えているのかなという、今決まっていることがあればお聞かせいただきたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"東京都への届出は、指定を２０名にしているといった違いがあります。ゆうゆうのほうで、日中一時支援も同様に、「運用上の定員」というのは、ハード上、当初２０名で、現在は１０名の定員で実施しているというものです。","id":"exchange-008"},{"speaker":"せお委員","kind":"質問・要望","question":"ありがとうございました。定員のところは理解いたしました。医療的ケア児のところはなかなか、すぐに希望する方全員というのも、受入れは難しいとは思うのですけれど、せっかくインクルーシブひろばベルでフローレンスも入っていただいているので、そういったところと連携して、少しずつ広めていっていただきたいなと、ここは要望したいと思っています。","respondent":"築山障害者施策推進担当課長","answer":"現在、発達相談で相談に来られた方が、療育を受けたいといった場合に、医療のほうにつないで、医師から医師意見書を出してもらって、これをもって療育につながるという流れがあるのですけれども、そこの療育につながるまでの流れにつきましては、品川児童学園のほうにもう１名。","id":"exchange-009"},{"speaker":"せお委員","kind":"質問・要望","question":"そこのところ、指定管理者が替わると、またちょっとスムーズにいくのかというところも皆さん考えられていると思うので、その辺も検討していっていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"若林委員","kind":"質問・要望","question":"そうするとつじつまが合うのですよね。逆に利用者から見ると、いわゆる介護度が改善したという意味なのかの確認をさせていただきたい。もう５年以上、１０年ぐらいになるのか。７８ページの総括で、積極的に評価した事項の中の２番目、「必要な福祉機器」とは何ですかということなのですけれど、導入して、その結果、職員の負担軽減とか、退職者の防止、休職者の減少と。以上、お願いします。","respondent":"宮尾高齢者福祉課長","answer":"１点目、３０ページの区民満足の視点の２点目の表記のところですけれども、こちらはちょっと表記が分かりにくかったかもしれないのですが、もともと、施設にはご家族が、ご近所にあったということでふらっと来て、そのときには介護サービスを使っていなかったのです。","id":"exchange-011"}]},{"id":"topic-02","title":"八潮在宅介護支援センターの移転","agenda":"八潮在宅介護支援センターの移転","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"改めてこれからつくられる、その障害者の生活相談なのですけれど、この体制は、相談員の方が何人体制で、どれぐらいの方の計画相談ができることになっていくのか、その点を伺いたいと思います。","respondent":"宮尾高齢者福祉課長、松山障害者福祉課長","answer":"広さですが、現在の八潮在宅介護支援センターは約３０m2、こちらで業務を行っております。移転先の八潮南特別養護老人ホームの１階部分というのは、ほぼ倍、約６０m2程度確保できるというふうに踏んでいるところです。ほかの在宅介護支援センター併設型の相談支援事業所とほぼ同程度ということになりますので、１０月１日から移転後の開設ということですので、まずはケアプランをつくり、円滑に慣れていただくです。","id":"exchange-012"}]},{"id":"topic-03","title":"令和４年度分品川区高齢者住宅（単身用）補欠登録者の募集","agenda":"令和４年度分品川区高齢者住宅（単身用）補欠登録者の募集","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういう点でいえば、もっと一般の高齢者が入れるような高齢者住宅も、立ち退きとか、よほどの本当に劣悪な、という以外でも入れるというところにまで拡大できるようなシルバーピアの住宅の戸数になってきてほしいなというのは、一つ要望として申し上げておきたいと思います。それから、昨年の申請者と、一昨年に入れた人数と、今年、これまでに入れている人数を教えていただきたいと思います。","respondent":"菅野高齢者地域支援課長","answer":"今年度、順次ご案内をしていますが、１０名程度のご案内ということで、今後も空いている住宅がありますので、もう少しご案内をする予定となっております。令和２年度につきましては、名簿登録者が５４名で、最終的に入居された方が１９名でした。","id":"exchange-013"}]},{"id":"topic-04","title":"新型コロナウイルス感染症生活困窮者自立支援金に関する申請期間の延長","agenda":"新型コロナウイルス感染症生活困窮者自立支援金に関する申請期間の延長","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これは本当に、なぜコロナ収束までの制度というふうな形にならないのかなというふうに私は思うのです。それは国の制度なので、区がこう決めますというふうなことはできない問題ですけれど、その辺のところは現場のほうからもぜひそういう声を上げていただきたいなというふうに思っているのですけれど、その点いかがでしょうか。","respondent":"櫻木生活福祉課長","answer":"３点目です。最大の見込数は、総合支援資金の再貸付を終了される方というのが、概算で社会福祉協議会のほうからいただいているのは、それが最大件数が５００人ですが、実際に申請される方の状況としては、１００人から１５０人程度を見込んでいるです。","id":"exchange-014"}]},{"id":"topic-05","title":"新型コロナウイルス感染症に感染した被保険者等に係る傷病手当金の延長","agenda":"新型コロナウイルス感染症に感染した被保険者等に係る傷病手当金の延長","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"２の対象者なのですけれど、「感染が疑われる者」というのは、濃厚接触者で１４日間仕事に出られないとか、そういう方というのも入るのでしょうか。それと、これは本人が、こういう制度があると気がついて申請する以外には対象にならないということで、区のほうから働きかけるすべというのはないということですよね。ちょっとその確認だけお願いします。","respondent":"池田国保医療年金課長","answer":"あくまでも熱があったりという症状があった方で、会社をお休みになって、賃金がカットされた方が対象という形になってまいります。","id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ということは、この「疑われる者」というのが、感染しているかどうかというのは必ず検査して、症状があっても検査していくと思うのですけれど、症状があって疑われる者というのは、どういう場面が想定されるのでしょうか。","respondent":"池田国保医療年金課長","answer":"陰性の方もいらっしゃるわけですが、陰性の方でそういった症状でお休みになって賃金をカットされた方についても、傷病手当金として支給されるですので、コロナウイルスに感染をされた方だけではなく、そういった症状でお休みをされた方も対象になるということで。","id":"exchange-016"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"分かりました。そういうことがあれば、風邪かコロナか分からないで、取りあえずはコロナの疑いもあるので休んでいたけれども、ＰＣＲ検査は陰性だったという方もこの手当の対象になるということで、それは分かったのですけれど、それと同時に私は、濃厚接触者も同じように、自宅待機で仕事ができないという状況になるわけですから、その濃厚接触者も対象にすべきではないかと思うのです。","respondent":"池田国保医療年金課長","answer":"こちらの傷病手当金につきましては、国民健康保険につきましては特に対象ということで検討はされていないところですけれども、濃厚接触者で会社を休まなければいけない、休んだところでお給料が事業主のほうから出ないというふうな場合については。","id":"exchange-017"}]},{"id":"topic-06","title":"新型コロナウイルス感染症に係る保健所・保健センターの対応","agenda":"新型コロナウイルス感染症に係る保健所・保健センターの対応","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"まん延防止対応なのですけれど、９月１日から１９日までは対象を限定していたということなのですが、これは品川区としての判断でこういうことをされたのか、それとも、東京都や国からの方針で、この感染爆発のときは症状がなければ濃厚接触者であっても検査をしなくてもいいですよという対応をされたのか、その点についても伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"患者への対応をしている保健師・看護師の人数ですが、ピーク時は７１名ということでお話をさせていただいたところですが、現在の人数につきましては、常勤の保健師が６名、会計年度任用の保健師が８名、派遣の看護師が１８名、合わせて３２名の体制で対応しております。","id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それで、１回目（のＰＣＲ検査）は保育園でやっていただいたということなのです。そういう点では今からでも、ぜひホームページなりで医療機関を、ＰＣＲ検査ができるところを案内していただきたいと私は思うのですけれど、どうでしょうかということ。今、ＰＣＲ検査ができる医療機関というのはどれぐらいあるのかということについても教えていただきたいと思います。","respondent":"鷹箸保健予防課長","answer":"その結果、保育園医で検査をされている場合でも、そもそも保育園医が小児科でない場合もたくさんあるのですけれども、診療のほうが本来の業務であるということもありまして、具合の悪い方の治療をすることを優先する中では、例えば症状のない子１０人、２０人の単位で。","id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ＰＣＲ検査ができる医療機関の公表というのはなかなか難しいと。それから、「濃厚接触者の特定等」というふうに書かれているのですけれど、特定する以外にも、何かされたことというのがあったのか、また、健康観察などというのは、品川区が担うということもあったのか、そこの状況を教えていただきたいと思います。","respondent":"鷹箸保健予防課長","answer":"我々は場合によっては、その施設の消毒などについて、例えば滞在しているホテルから相談があったときにはそれに対応する、助言をするという形で、直接的に特に品川区保健所においては現場に出向いて感染者の方を移送するとか、そういった対応はほぼやらずに済んだという。","id":"exchange-020"}]},{"id":"topic-07","title":"品川区の新型コロナウイルス感染症にかかるワクチン接種状況","agenda":"品川区の新型コロナウイルス感染症にかかるワクチン接種状況","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ワクチンメーカーを見ると、ワクチン供給率というのが５６.１％なのですけれど、この供給率の中には、全て、ファイザーからモデルナからアストラゼネカから全て入っているという考え方でいいのか、その確認と、それからファイザーの分というのは３５２箱で約４１万回分ということで書かれているのですけれど、アストラゼネカとモデルナは、それぞれ何回分なのか、それを教えていただきたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"今週金曜日の分は、残り枠があと約４０枠というふうに聞いております。ただ１０月に入りまして、１０月１日分と８日分については、まだ１５０枠ほど余裕があるように報告を受けております。","id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そういう中で、一般質問の中で、国がワクチンは確保できているというふうに言っているにもかかわらず、なぜ自治体に供給されないのかということで、その理由はどう説明されているのかというふうなことで聞いたのですけれど、国は１２歳以上の人口の８割が２回接種できるためのワクチンを配分していると説明しているという、こういう答弁しかなかったのです。そういう点も伺いたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ちょっと細かいバイアル数は、すみません、今ちょっと私の手元に数字はありませんが、１バイアルで１０名打てます。１日２００名ですので、およそ１日２０バイアル、それの３日分、６０バイアルほどを融通していただきました。","id":"exchange-022"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そうすると、ワクチン供給率というのは、これは人口全員がやったときのことを考えて５６.１％という考え方なのでしょうか。区として、大規模接種会場だったりとか職域接種であったりとかというふうなことを含めると、その辺の割合と、それから区がこれだけはというのを除いたところで、何％ぐらいまでは確保されているというふうなことになるのか、その辺のところの計算ができていたら教えてください。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"職域接種それから大規模接種ですが、こちらは、区でどれくらい打てるかという試算をすることができませんで、あくまで打ち終わった、いわゆるＶＲＳというシステムで登録をしていくのですけれども、その登録で上がってきた数字から類推するほかにちょっと方法がなくて。","id":"exchange-023"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そうしますと、そもそも８割でいいのかというのもあるのかなという気がするのです。６５歳以上の人も９割は接種していますし、６０代の人だって１回目でもう８割近くになっているわけですから。数％ですか。数％というのは何人分というのだけ教えていただけたら。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"こちらの試算というのは３６万５,０００人ですので、１％が約３,６００人に当たります。二、三％分というふうに考えていますので、１万人はいかないだろうと。数千人分で８割に行くのではなかろうかというところの試算で今動いております。","id":"exchange-024"},{"speaker":"若林委員","kind":"確認","question":"確認で、今の数％とか二、三％とか、１万人とか数千人とか、いろいろな数字が出てきたのですが、すると要するに、ファイザーはもうありませんよと。その１万人以下とか数千人分とか数％から二、三％は、全てアストラゼネカとモデルナでこれを賄っていくということでよろしいですか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ただ、一部、まだ病院のほうで、既にお渡ししているファイザーの使用期限の問題がありまして、打ち切れないというものがもし今後出てくるようであれば、それを急いでこちらのほうで回収しまして、期限内に打てるように行っていきますから、もしかしたらそのファイザーがあと少し。","id":"exchange-025"}]},{"id":"topic-08","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それから３点目は、先ほども言いましたけれど、自宅療養者への健康観察についての体制ということで、最大保健師・看護師が７１名、事務職が２７名ということでしたけれども、常勤換算ということでの人数ということでいいのかという確認をさせていただきたいということと、それから、先ほどのところでも、現在の看護師と保健師の内訳をご説明いただきましたけれど。","respondent":"鷹箸保健予防課長","answer":"陽性者が同じクラスで２人以上発生し、お互いの感染経路が、例えばお父さんが陽性であるとか家族内感染ということではなくて、感染経路が全く不明の場合は同じクラス内での感染拡大を考えて、クラス全員を対象にＰＣＲ検査を実施し、その結果、陽性の人がいた。","id":"exchange-026"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ご答弁ありがとうございました。学校での感染というときも、濃厚接触者の判断とかも全部保健所がやるという形に今でもされているということなのでしょうか。それから、自宅療養者のほうは、改めて常勤換算でこれだけの人数でされていたくらいの、それだけ大変な状況だったのだろうなということが分かりました。ありがとうございました。学校のほうだけ教えてください。","respondent":"鷹箸保健予防課長","answer":"先ほどの対応の人数７１名ですが、要は土曜日、日曜日も含めてずっと対応をしなくてはいけないので、代休を取っていきますとこれだけの人数が必要で、これでも足りなくなって、かなり深夜までの残業が必要になったという形になります。","id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"学校だったり保育園だったりとかも、実際は、保健所と相談をしながら決めていくという、そういうことだと思います。ガイドラインもそういうことで、こうしたことを保健所が認めたら学校ができるよというガイドラインになっていると思うのです。そういうガイドラインだと思いますので、ぜひこれからも、もしも感染が出た場合にはそういう形で広く検査をやっていただくようにお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/779921?Template=document&Id=3608#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":60981,"voices":111}},{"id":"r03-20210922-8","meetingId":"r03-cm09","date":"2021年9月22日","dateIso":"2021-09-22","committee":"建設委員会","time":"午前１０時００分～午後 ２時３１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を60件抜き出しています。","topics":[{"id":"topic-01","title":"羽田空港の機能強化","agenda":"羽田空港の機能強化","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"運用可能な気象条件ということで書かれておりますけれども、今回選定された２つの飛行方式、どちらも好天時ということで、9)のＲＮＰ＋ＷＰというのは、括弧書きで「（視界良好時のみ）」と書いてありますけれども、若干違いはあるということですが、この好天時というのが、どういった気象条件なのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"今後の予定で、４段階、先ほどご紹介したとおりなのですが、区としましても、この４段階が示されたとおり、ある程度の検討の段階の区切りであるということは、この資料からも読み取れるわけでして、この１つ１つのまとまりが一月なのか、二月なのか、数か月なのかというのは。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"今回選定された２つの着陸方式、これは好天時に利用できるというものなので、悪天時のときには今のルートを通ってくることになるのかなというふうに思いますけれども、そうすると、やはりこの２つの方式を利用したとしても、結局は品川の上を飛ぶことになるということだと思いますけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"ご質問の中で、結果、区の上空を飛ぶことには変わりないのではないかですが、やはり羽田空港の導入が可能である飛行方式として、１２から６つ、６つから２つと、今回絞り込まれたところでございまして、これはもう明確に会の中でも言っておりますが。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"それで、実際問題として、やはり品川区は空港に最も近い自治体の１つでもありますので、結局、Ａ・Ｃ滑走路に着陸をしていくということになれば、品川の上を飛ぶことになってしまうというふうに考えているわけですけれども、２つの滑走路が並行してあるということで、大型機がこの並行したルートを降りてくるに当たって。","respondent":"鈴木都市計画課長","answer":"同時旋回、特に大型機の曲線への同時のというお話ですが、議論を見ていく中では、そうした議論はまだされていないですが、同時旋回での同時進入というよりも、同時進入、「同時旋回」という言葉よりも「同時進入」というところは、資料の中でも同時進入での基準があるなしと。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"区民が求めているのは、やはり品川の上を飛ばないでほしいということなのです。そのためには、滑走路を前提にしていると、品川の上は飛ぶことになるということになってしまうので、やはり滑走路の使い方、Ａ・Ｃ滑走路を使っていくということを変えていくということが必要だと思いますので、やはりそういったことも区として求めていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"西本委員","kind":"確認","question":"幾つか確認をいたします。この検討会なのですけれども、そもそも何の目的での検討会なのか。そして、それが今回４回目の会議で、２つの手法が、技術的な方法が選定されているという状況の流れの中で、当初の考え方、品川区にとってのこうであるだろうというものに対して、解決の方向にいっているのかどうかをまずお聞きしたいと思います。","respondent":"鈴木都市計画課長","answer":"先ほどもご答弁申し上げましたが、区としましては、国の決定事項、国の責任において進められるべきではあるのですけれども、やはり経路について少しでも技術の進展があって、品川区上空の影響を少しでも軽減できる方策があるのであれば、それを固定化せずに。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"固定化回避、でも、固定化回避と言っておきながら、ある程度その航路が決まるわけではないですか、ルートが。そうすると、固定化になるわけですよね。旋回をどうしようが品川区は通るということは変わらない。Ａ滑走路、Ｃ滑走路。そこをどうやって固定化回避と言えるのか。品川区の住民の側から言えば、固定化回避ではなくて固定化ではないですか。そこを区の認識ではどう考えていますでしょうか。","respondent":"鈴木都市計画課長","answer":"ただいまご説明いただいた前提条件として、Ａ滑走路、Ｃ滑走路の着陸の滑走路としての運用を前提とするということは、１回目の会の立ち上げ当初から、国は資料でも提示しておりますし、区でもそういう前提のもと、検討が進められるということは当然認識しています。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"私たちも期待しています。そうしたときに、品川区の上空は全く変わらないのではないのか、多少変わっても、ほぼ変わらない状況で飛行機が飛んでくるではないかと、区民の方々がそう思ってしまう、私たちもそう思えば、区の期待と違うわけですから、そのときどういう態度をとるのですか。そうなったときの品川区の態度をどうするつもりですか。","respondent":"鈴木都市計画課長","answer":"やはりこの固定化回避については、この名のとおり、少しでも、それが大幅であればあるほど区としてはいいわけですが、少しでも軽減策につながることがあれば、そこはぜひ検討していただいて、その実施を求めていくというのが区の姿勢です。","id":"exchange-007"},{"speaker":"西本委員","kind":"確認","question":"もうそろそろ品川区としての態度を示していくべきだと思います。課題への対応を見ると、「安全性評価も踏まえ、新たな基準を策定する」とか、それから「シミュレーションを用い、運航手順、パイロット操作負荷、想定した経路の再現性等の妥当性を確認する」など、これ、今からやるのですかというところです。８ページの一覧を見ました。設定基準という黄色いところで、9)、国内基準、なし。","respondent":"鈴木都市計画課長","answer":"当然ながら、その安全性第一、採用に当たってのステップが、先ほど、取り組むべき課題としてご説明した前提条件だとか、モデルの検証ですとか、関係者との調整、そうした中で検証しながら検討が進められているという理解です。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"まとめます。当然この整理した表を見ても、おかしいのではないのかということは当然思いますが、それ以上に、品川区として、行政側が、これでいいのかと思わなければいけないのではないのですか。それ以上に、これは危険だということを、区が、私自身も含めてですけれども、危ないと思ったら、やっぱりそれは国に、このような状況で検討していいのですかと、人の命がかかっているのですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"塚本委員","kind":"質問・要望","question":"これは国が決定することですけれども、この先の議論を進めていくのは、引き続きこの同じ検討会というところでやっていくのかどうかというところについて区として何か分かることがあれば、見解を示していただきたいのと、区と国との今後のやり取りについても、今まで以上に、技術的というところの視点だけではない部分での視点で。","respondent":"鈴木都市計画課長","answer":"委員ご指摘いただいたように、技術的方策について検討するですので、これが検討が進められて、一定程度、安全性を担保した上で、検証、設計、あるいは調整が進んでいって、採用に非常に具体的な中身に固まってきた以降の話は、まだ国からは具体的には説明はありませんし。","id":"exchange-010"},{"speaker":"塚本委員","kind":"質問・要望","question":"ぜひ、実際にこのどちらかの、どちらかになるのか、両方併用するのかはちょっとまだ今の段階では分からないですけれども、新しい技術的方式が導入されていくということが、今後、だんだん具体化していく上で、区としては、やっぱりここは飛べるのですね、飛べないのですねと技術的な視点だけではなくて、もっといろいろな要素が、直下に住む方々の生活とかがあるわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり品川の上を飛んでいる以上、区民に被害が及んでいるということになるので、品川の上を飛ばないことを求めていくべきだと私は思うのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"区としましては、本格運用開始以前から、基本的には、これは国の事業で、国の責任において国が実施していくべきだというスタンスのもと、ただ、やはり影響のある落下物への不安ですとか、あるいは騒音の軽減について、可能な限り取組を求めていくと、これまでも求めてきましたし。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問・要望","question":"不安軽減ではなくて、この羽田新飛行ルート、変わった後も品川の上を飛ばないようにという立場で求めていただきたいと思いますし、ぜひ中止の立場に立っていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]},{"id":"topic-02","title":"第３２回東京都道路整備事業推進大会","agenda":"第３２回東京都道路整備事業推進大会","exchanges":[{"speaker":"塚本委員","kind":"提案","question":"今の委員長の提案のとおりで、よろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"}]},{"id":"topic-03","title":"令和３年１１月都営住宅入居者募集","agenda":"令和３年１１月都営住宅入居者募集","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"区内の募集戸数ですとか、区内の状況を教えていただきたいと思います。","respondent":"竹田住宅課長","answer":"今回の１１月募集につきましては、１０月２２日の発表を待っているところです。ちなみに、昨年度の同時期の区内の募集状況は、８団地１９戸となっております。","id":"exchange-015"}]},{"id":"topic-04","title":"令和２年度指定管理者による管理に対するモニタリング・評価","agenda":"令和２年度指定管理者による管理に対するモニタリング・評価","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"そうした情報の中で、区議会が適正なのかどうかということを見ていくということになりますので、十分な情報を出していただきたいというふうに思います。２４時間常駐して、いろいろ居住者の方の問合せ等に答えていると思うのですが、この間、具体的な対応等、紹介できるものがありましたら、伺いたいと思います。","respondent":"竹田住宅課長","answer":"東急分のほうの緊急時の対応ということですが、こちらはお住まいの戸数が非常に多いので、２４時間体制でサービスセンターを設置しておりまして、皆様のご連絡を受けられる体制をとっているところですが、この間、特段大きな事故等はなかったというふうに聞いております。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問・要望","question":"これはどちらのところでも言えることなのですけれども、支出のところで、入居者管理経費ということで書いてありますが、言葉尻といえば言葉尻かもしれませんが、入居者を管理するという捉え方で仕事をしていると、やはり入居者の方との対応がよくないということもあり得るのかなというふうに思いますので、そこは、そういったことがないようにやっていただきたいというふうに思いますが、いかがでしょうか。","respondent":"竹田住宅課長","answer":"入居者からのお声ということでお伝えしますと、夜間に限らないのですが、例えば、共有部分に私物を置いて放置してあるので困るとか、あと、雑排水が逆流する、あるいは臭いがするとか、カラスが巣をつくってしまったとか、生活上。","id":"exchange-017"},{"speaker":"のだて委員","kind":"質問・要望","question":"それで、先ほど言い忘れましたけれども、指定管理者の情報を十分に出してほしいというところで、確かに今回、収入、支出の部分は新しいかなと思ったのですが、ほとんど出ている情報は変わりがありませんので、さらに多くの情報を出していただいて、事業者が適正かどうかということを区議会がしっかり判断できるようにしていただきたいというふうに思います。","respondent":"竹田住宅課長","answer":"その中でも詳しくお話しして、指定管理者はどういうところが適切なのかというところをご説明させていただきたいと考えております。","id":"exchange-018"},{"speaker":"のだて委員","kind":"質問・要望","question":"情報公開のところで、この報告書をつくったりしている中で、情報がいろいろ取捨選択されていると思うのです。ではなくて、そういった出されている情報を全て出せばいいと思いますので、そういった方向で前進していっていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"西本委員","kind":"確認","question":"これは区営住宅が多いのでしょうか、区民住宅が多いのでしょうかということと、それから、区営住宅等については、高齢者が多いものですから、その方々の福祉部との連携、民生委員の方々もいらっしゃると思うので、どういう現状があるのかとか、おひとり住まいの高齢者は特に様子を見ていかないと、いろいろ容体が変わってくるという状況がありますから。","respondent":"竹田住宅課長","answer":"その計画も１０年前に立てまして、来年度がちょうど現計画の終了時期になりますので、来年度、新しい向こう１０年の計画を立てまして、建物の適正な維持管理に努めていきたいと考えております。","id":"exchange-020"},{"speaker":"西本委員","kind":"質問","question":"高齢者が多い状況ですから、特にお一人で住まわれている方に対しての現状把握は、品川宅建管理センター、それからもう１つのところもぜひよろしくお願いしたいと思います。もしかしたら区営住宅の考え方も変えていく必要があるのか、私はなくしてほしくはないですけれども、その用途も含めて見直しを図る時期にも来ているのではないかと思うのですが、それは今後考えていく予定はあるのでしょうか。","respondent":"竹田住宅課長","answer":"先ほど申し上げた長寿命化計画ですが、１０年スパンで計画しているものですから、実際に時間が経過する中で、いや、この工事はもう少し前倒しにしたほうがいいとか、もうちょっと延期した、延期はなかなかないと思いますが、状況に応じて見直しも必要だろうと考えています。","id":"exchange-021"},{"speaker":"西本委員","kind":"質問・要望","question":"これは要望なのですけれども、これから人口増、品川区の人口の動向を考えたり、あと、高齢化を考えていくと、やはりニーズは高くなってくる可能性もあるなと。その面、高齢化も見なければいけないし、人口推移も当然見ていかなければいけないので、それに対して長期に計画をしていくという形をとらざるを得ないだろうなというふうに思うのです。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"芹澤委員","kind":"質問","question":"両方ともかなり大手の会社がやっていらっしゃると思うのですけれども、マンション管理だったりとか、かなり実績のあるところで、改めて滞納の課題が出てくるというのは、どういったことなのかなと思って、特にノウハウを持っている会社だと思うのですけれども、そこについての評価はいかがお考えなのでしょうか。","respondent":"竹田住宅課長","answer":"ただ、今日冒頭でご説明させていただいたとおり、近年は非常に高い収納率を達成できておりますので、ここに甘んじることなく、今後もしっかりと収納に努めていきたいと考えております。","id":"exchange-023"},{"speaker":"芹澤委員","kind":"質問","question":"最後に１つだけ、そうすると、滞納があって、指定管理者が把握されていて、そこからこの家庭はもしかしたらお金が今厳しいのかもしれないというようなことが住宅課に入って、そこからいろいろな課に、皆さんの判断で情報の伝達がなされているということでよろしいのでしょうか。","respondent":"竹田住宅課長","answer":"こちらからお伝えするというよりは、むしろほかの課から、お住まいの方の状況をお聞きするケースのほうが多いような気がしております。","id":"exchange-024"},{"speaker":"塚本委員","kind":"確認","question":"すみません、ちょっとこれまでの質疑であったかもしれない、聞き漏らしていたらすみません。主に区民住宅なのですけれども、指定管理業務の概要の中の1)で、入居及び返還に関することというふうになっています。いわゆる入居率というのか、空室を埋めるための様々な努力みたいなことは、この指定管理者の業務として委託されているのですか。そこを確認させていただいていいですか。","respondent":"竹田住宅課長","answer":"ご指摘のとおり、入居率は非常に大事な項目だと考えています。入居に関する事務全般も、指定管理者にお願いしています。","id":"exchange-025"},{"speaker":"塚本委員","kind":"意見","question":"やっぱりもうちょっと努力すべき、入居率を上げなければというところがあって、またそれについては、あるのであれば、指定管理者に対しても何かしらの形で改善してもらうように考えてもらうというのか、一緒に検討するというようなイメージなのかちょっと微妙ですけれども、そういう入居率を上げていくということに関しての指定管理者への評価と、今後についてどういうふうに取り組む考え等があるのか。","respondent":"竹田住宅課長","answer":"何が入居促進につながるのかというものを、まさに指定管理者は不動産業のプロですから、そういった方の知恵もお借りしながら、有効な入居率の向上に向けて努めていきたいと考えております。","id":"exchange-026"}]},{"id":"topic-05","title":"建設委員会を再開いたします。 これ以降は、防災まちづくり部が所管する議題となりますので、よろしくお願いいたします。 それでは、引き続き","agenda":"建設委員会を再開いたします。 これ以降は、防災まちづくり部が所管する議題となりますので、よろしくお願いいたします。 それでは、引き続き","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今回、紙のアンケートに加えてウェブアンケートを実施したということですが、この声が、どういった声が出ているのか伺いたいと思います。そして、これは平成３０年度ですけれども、収支が差引きマイナス１２０万円ということで、マイナスになった場合、どういった処理をしているのか、仕組み上の問題を伺いたいと思います。","respondent":"川口交通安全担当課長","answer":"１点目のウェブのアンケートの結果等につきましては、大きいものですと、やはり利便性の向上という面で、例えば先ほどもご説明いたしましたけれども、いわゆるＩＣカードによる支払いを、自分が今、実際に利用しているところにも導入をしてもらいたいという要望ですとか、また。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問","question":"そういったときの処理といいますか、事業者の負担になるということなのか、そこの仕組みのところを伺いたいと思います。それと、今回、返還もあったりとかということですが、人件費のところではアップをしたということで、人件費がアップした理由はどういう理由なのか伺います。","respondent":"川口交通安全担当課長","answer":"１点目の仕組みのところですが、こちらにつきましては、先ほどもご説明させていただきましたとおり、当初の見込みよりも多く、通常の計上はされているのですけれども、それ以外に急遽、例えば施設の故障等とか、修繕が必要になったという部分におきまして。","id":"exchange-028"},{"speaker":"のだて委員","kind":"質問・要望","question":"人件費のところは、最低賃金が上がったからということですね。それはよかったと思います。このコロナ禍で減っていないというところですけれども、さらによくしていくようにしていっていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問・要望","question":"何点か確認をいたします。ＩＣカード対応になったということで、これは要望していましたので、本当うれしいと思います。幾らか手数料という、これはどのぐらいの割合で、ＩＣカードを使うと必要になってくるのかということを教えてください。それと、コロナ禍によって利用率が下がっているというのは、それも仕方ないわけでありますが、１つは、利用者の増加が求められると、求めなくていいと思っています。","respondent":"川口交通安全担当課長","answer":"当然、一時的に、例えば、たまたまそのシェアサイクルがある場所が会社の近くであれば、短時間で使うのでシェアのほうが便利だとか、また、定期的な確実な自転車利用があるということで、自転車は自分の所有において駅前まで毎日のように自転車を使うという。","id":"exchange-030"},{"speaker":"西本委員","kind":"意見","question":"ＩＣカードの手数料は結構あります。それが一応、品川区の収入という部分でいうと、その分少なくなったということの理解なのかと思うのですけれども、それは、ある程度仕方ないかなというふうに思っております。住民の便利さをぜひお願いしたいというところでありますので。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり今、この最低賃金では暮らしていけないということも言われています。働いている方は若い方はそんなにいないと思いますが、それでもやはり最低賃金で暮らしていくというのはなかなか大変だというふうに思いますので、そこのところ、ぜひさらにアップしていっていただきたいというふうに思うのですけれども、いかがでしょうか。","respondent":"川口交通安全担当課長","answer":"そちらの賃金の関係につきましては、当課の事業のみならず、区全体として、そのような考え方をしっかりと把握していくことが必要なのではないかなというふうに考えております。","id":"exchange-032"},{"speaker":"のだて委員","kind":"質問","question":"そのような考え方というのは、どのような考え方でしょうか。","respondent":"川口交通安全担当課長","answer":"失礼いたしました。一応、契約面を担当している部署と調整を図りながら対応させていただければというふうに考えております。","id":"exchange-033"}]},{"id":"topic-06","title":"品川区舗装修繕計画の策定","agenda":"品川区舗装修繕計画の策定","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、舗装修繕計画を策定するということでご説明がありました。平均でいくと、年間主要な区道は３.４億円、その他区道は５.４億円の維持管理経費がかかっているということなのですが、まず、資料のところで、冊子のほうの１８ページ、一番最後のところです。この見方を伺いたいと思います。行わないとすると、そうした理由を伺いたいと思います。","respondent":"溝口道路課長","answer":"具体的な路線については、様々日々いただいている皆さんからの要望または道路の点検状況、そういったものも含めて予算要求しながら進めていきたいというふうに考えておりますので、本計画については、改めてパブリックコメント等の意見を聞きながら進めていく形ではなくて。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問","question":"今回、国の補助金の制度も整ってきたということで、これを整備するに当たって、補助金がどのくらい出るという考えなのかも伺いたいと思います。そして、今回、この間、国のほうでは、平成２５年にインフラ長寿命化基本計画を策定してきたというところで、品川区として、舗装修繕計画がこの時期になった理由を伺います。","respondent":"溝口道路課長","answer":"平準化に伴ってコストのところですが、橋梁とか、ほかのところを見ますと、平準化することによって幾らかということが出るのですが、やはり道路につきましては、皆さんの生活に密着するところですので、一番の関心事と、私どもとしては、今。","id":"exchange-035"},{"speaker":"のだて委員","kind":"意見","question":"どれだけ経費削減できたかではないということで、それもしっかり管理していくということは重要だと思いますので、今後、どういうふうになっていくのか、実績を見ながら私も見ていきたいというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"あともう１つは、いろいろな工事があります。でも、そこから外れると割といいとかという、道路は１本なのですけれども、でも、部分部分によって影響が出てくる。大型車両が入ってくると、そこも荒れやすくなってきたりするので、全体的に舗装するという時期なども、結構、判断するのは難しいのではないかと思うのですけれども、その辺はどういうふうな運用をされるのでしょうか。","respondent":"溝口道路課長","answer":"これまでの関係をまず説明させていただきたいと思います。これまで品川区の管理する道路の補修につきましては、道路の新設、都市計画道路は別ですけれども、それ以外のものは基本的に品川区の費用というか、品川区で予算をとって整備をしてきたという経緯があります。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"それについて、民間の方々との調整をどうするのかというところ。それから、今後の予定の中で、ホームページに公表するということなのですが、何を公表するのですか。この資料を公表するのですか。計画のほうをするのか。だから、安心してほしいというメッセージなのか、その分、下手をすると、「何、工事ばっかりになるの」と。そこの表現の仕方はどう考えていますか。","respondent":"溝口道路課長、稲田土木管理課長","answer":"ホームページの公表ですけれども、本文だけだとやっぱり分かりづらいので、今回、私が説明で使わせていただいたＡ３判の資料も一緒に添付するような形で公表していきたいと考えていますし、文書の中には、やはり今後、先ほど来。計画を出してもらって、どのようにやるのかとか、細かいところまでチェックしながらやってきているものなのですけれども、それと、また、道路工事調整協議会を年に４回ほどやっておりまして、また。","id":"exchange-038"},{"speaker":"西本委員","kind":"質問・要望","question":"最後に意見だけ。やはり道路工事などというと、「また不便なの」とか、電線の地中化にしても、すごい長くかかって、非常に皆さんに不便がかかるわけです。だから、道路工事というと、あまりいいイメージがないので、最終的には快適な生活になるのですけれども、そういうような目的を持ってやっているのですよということは、しっかりお伝えしていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"塚本委員","kind":"質問・要望","question":"少し確認だけさせていただきたいと思うのですけれども、２ページ目の３、維持管理方法のところで、これまでの質疑にもちょっと関わるのですけれども、主要な区道とその他の区道というところで、それぞれ維持管理方法が示されています。ＩＣＴ機器からは応急補修ということになっているのかというところの確認です。","respondent":"溝口道路課長","answer":"そういったところで、やはり先ほど来、話しています点検で出た悪いところをしっかり直すというのも１つですし、区民の方からの要望とか、そういったものをしっかり受けながら路線を決めていかなければいけないと考えていますので、一概に私どもが一方的に。","id":"exchange-040"},{"speaker":"塚本委員","kind":"質問・要望","question":"ありがとうございました。品川区、東京２３区と言ってもいいかもしれないですけれども、地方へ行ったりすると、道路の状況は、地方と比べるとやっぱり非常によく管理されているというのは感じます。そういった目的を達するものになり得るように、しっかりやっていただきたいというふうに要望いたしまして、以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"}]},{"id":"topic-07","title":"しながわ区民公園北側ゾーン改修工事","agenda":"しながわ区民公園北側ゾーン改修工事","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"この区民公園の北側の改修は、この間も地域の方からいろいろお話があったりしてきましたので、これまでもアンケート等をやられて、様々な意見を取り入れて進めておりますので、引き続き、住民の理解、利用者などのご理解をいただけるように、意見交換といいますか、説明などをしていっていただきたいというふうに思います。いかがでしょうか。","respondent":"高梨公園課長","answer":"しながわ区民公園は、周辺の方のみならず、区内全域から訪れる大きな公園ですので、工事に際しましては、工事説明会等を通じて、しっかりと利用者の皆様、また、周辺の皆様方に理解をしていただいて、工事が円滑に進められるように努めてまいりたいと考えております。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問","question":"第１期工事範囲ということで、スポーツ施設の周りということになっているのですけれども、この周りは、わりかし木とかが鬱蒼としているのですが、緑の多いところです。なので、どういう雰囲気になるのでしょうか。なるべく自然は維持してほしいという思いがあるのですが、木のほうも樹勢の衰えた樹木ということで整理されるということなのですが、どういう感じになるのでしょうか。","respondent":"高梨公園課長","answer":"基本的なしつらえにつきましては、今、樹林となっているようなところは引き続き樹林として整備をしていきたいというふうに考えてありますが、今、委員からもご説明ありましたとおり、開園からもう４０年近く経っているということで。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"なぜかというと、そこを広げてしまうと、やっぱり樹木のところが狭くなってしまったりということで、ちょっと全体像が見えないものですから、緑も大切だし、あそこで散策する人も必要だし、マラソンなどをしている人、ランニングしている人もたくさんいるし、その辺の兼ね合いはどうなっているのでしょうか。","respondent":"高梨公園課長","answer":"周辺の園路は、今も歩行者用と自転車用とありますけれども、今回、自転車のほうの通行路は、引き続き自転車の通行路として確保するのですけれども、歩行者の部分については、６ｍに拡幅し、災害時、発災時の緊急車両等の動線にも配慮できるような形で。","id":"exchange-044"},{"speaker":"西本委員","kind":"質問","question":"これ、北口のほうを開放的にと言っているのですけれども、ここは、今、午後５時に閉めるのですよね。その開放も、ここを考えるのか。考えないのか。中央のほうは、それなりの水族館的な、何かそういう雰囲気があるのですけれども、この北口は、もうちょっと、今ちょっと暗いので、ちょっと明るめで、入りやすそうな、そのような雰囲気が欲しいと思うのですが、どのようなイメージでしょうか。","respondent":"高梨公園課長","answer":"今回、段階的に再整備を進めてまいりましたので、また運用しながら、再整備した区民公園の状況に合わせて、閉鎖の時間帯であったりとか、そういうところはしっかりと現状を見ながら検討を進めていきたいと思います。","id":"exchange-045"},{"speaker":"西本委員","kind":"意見","question":"北口のところが午後５時ということで、例えば、テニスコートとかを使われている方が帰ろうとすると遠くなるのです。もちろんセキュリティの問題がありますので、そこは必要になってくると思うのですけれども、今後、検討していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"}]},{"id":"topic-08","title":"「品川区水とみどりの基本計画・行動計画」（改定素案）について（パブリックコメントの実施）","agenda":"「品川区水とみどりの基本計画・行動計画」（改定素案）について（パブリックコメントの実施）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回改定をするということで、この計画の改定検討委員会、メンバーはどういった方が入っているのか、学識経験者の方もいるということですので、この人数と、あと、専門分野を伺いたいと思います。ちなみに、この会議体は公開されているのかどうかも伺いたいと思います。","respondent":"高梨公園課長","answer":"検討委員会、いろいろと検討の内容につきましては、区民に誤解というか、まだ検討途中の段階で、そういった内容も含まれる可能性があるということで、会自体は非公開で行っているところです。","id":"exchange-047"},{"speaker":"のだて委員","kind":"質問・要望","question":"会議は非公開ということですけれども、やはり公開をしていくべきかというふうに思います。そうすると、この会議体のメンバーは、１０人以上にはなるということですか。その代わりに登録もされておりますけれども、そうした中で、やはり保存樹木も守っていくということが、民間の樹木を守っていくことにもつながるのかなというふうに思いますけれども、どのようなお考えか伺いたいと思います。","respondent":"高梨公園課長","answer":"一足飛びにすぐに改定といったところにいけるかどうかということについては検討が必要ですけれども、今後、今の基準どおりの緑化のお願いで本当にいいのかどうか、それをもう少し多くお願いしていかなければいけないのかといったところについては。","id":"exchange-048"},{"speaker":"のだて委員","kind":"質問・要望","question":"保存樹木のほうは、増やしていきたいということだったので、ぜひそこは増やしていっていただきたいと思いますし、やはり緑被率を上げていくということが重要だというふうに思います。それで、目標のところで、みどり率の目標が今回の計画では２１.７％を目指していくということですけれども、前回の目標ですと２２.６％ということで、この目標を下げた理由を伺いたいと思います。","respondent":"高梨公園課長","answer":"区民満足度の目標設定についてですけれども、ご説明の中でも申し上げましたが、目標設定のあり方について、純然たるみどりといいますと、量だけではなく、しっかりとした質、その質とは何かといったところですけれども、区民の方々が身近で見て、みどりの癒し。","id":"exchange-049"},{"speaker":"のだて委員","kind":"質問・要望","question":"目標のところで、今回、みどり率は実現可能なところを見てということでしたので、それにプラスアルファしているということですので、さらに伸ばしていっていただきたいというふうに思います。東京都の平均の公園の面積よりも少ないという状況ですので、この緑被率を増やしていくという目標も持つべきではないかと思うのですが、いかがでしょうか。","respondent":"高梨公園課長","answer":"緑被の目標設定を新たに設けるといった考え方もあろうかとは思いますけれども、区といたしましては、東京都をはじめ都内の各自治体が、みどり率で、いろいろみどりの施策の指標として設けているといったところも踏まえまして。","id":"exchange-050"},{"speaker":"のだて委員","kind":"質問・要望","question":"それで、今回、まちづくりはにぎわいということも含まれて書かれておりますけれども、再開発をやられたところで、航空写真でみどりが増えていますというような感じで載ってもおりましたが、やはり、そこでみどりは増えるということですが、高層ビルなどが建てばＣＯ２の排出量も増えるということで本末転倒なことになってしまいますので。","respondent":"高梨公園課長","answer":"山や森林が多くある自治体と違って、ほぼ全てが都市化が進んでいるこの品川区においては、そういったまちの更新の機会を捉えた水辺であったり、みどりの創出を、やはり主眼に置いて進めていかなければいけない、このように考えているところです。","id":"exchange-051"},{"speaker":"のだて委員","kind":"質問・要望","question":"機会を捉えてということですが、こうした整備が再開発につながっていかないように、改めて求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"本多委員","kind":"質問","question":"すみません、この計画は、公園課と河川下水道課が中心となりつくられたのだと思いますが、すばらしい計画だと思います。それぞれが施策展開をされると、もうすごくいろいろな部署にまたぐと思うのですが、行動計画を実現しますという品川区内の各部署がそれぞれの取組をするときの、公園課と河川下水道課の関わりというのはどういう位置なのか、総括的になるのか、その辺を教えてください。","respondent":"高梨公園課長","answer":"今ご質問の、そういった中での公園課、河川下水道課の立ち位置といったところですけれども、本計画を策定するに当たり、事務局として担った両課は、説明の中でもお話ししましたとおり、毎年、事業の進捗状況をチェックするための会議を行うこととしておりますので。","id":"exchange-053"},{"speaker":"本多委員","kind":"質問","question":"この素案の先ほど説明いただいた７４ページに、区有船着場の利用回数とか、この辺の満足度とかが出ているのですけれども、以前より水辺の舟運とか計画があったのが、コロナ禍によって大分遅れたりしていて、例えば、水上タクシーの展開とかが大幅に遅れてしまったりする、そういう個々のことが、こういった１つ１つの目標回数とかが伸びているのですけれども、具体的にそういうものが着手していけるのか。","respondent":"栗原河川下水道課長","answer":"水辺を活かしたまちづくりの中で、地域と連携した船着場・護岸の修景等を行うなど、また、舟運事業者の皆様のご意見を伺いながら、引き続き、水辺イベントの開催時の支援、桟橋の整備などを続けまして、取組を進めていきたいというふうに考えているところです。","id":"exchange-054"},{"speaker":"芹澤委員","kind":"質問","question":"すみません、１点お伺いしたいのですが、何ページだったか、目黒川の将来的なビジョンというところで、アユが来たりとか、あと、そもそも人の遊泳というようなところが書いてあると思うのです。","respondent":"栗原河川下水道課長","answer":"当然、舟運事業と遊泳というところで、なかなか実際の両立が難しいということはありますけれども、そういった水質改善の取組に向けた分かりやすい目標、将来像の設定ということでご理解いただければというふうに思っております。","id":"exchange-055"},{"speaker":"西本委員","kind":"質問","question":"なので、増えていくのか、減っていくのか、そういうものがどういう関連性でまちづくりというふうな捉え方で考えればいいのかというところが１つ気になりました。それから、屋上緑化という形で、これは建物を利用して屋上、それから壁面緑化とか、そういうものも当然必要になってくる、すみません、見つけられなかったので、そこら辺がどこかに示されているのかなというのが２点。","respondent":"高梨公園課長","answer":"そのために必要な行政の支援、またはまちの方々の認識がどういったものかということも見定めながら、今後検討してまいりたいというふうに考えております。","id":"exchange-056"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、そこは、これを機会に、ある程度の考え方をつくっていただきたいというのと、相談の場所です。地域の区道であれ、都道とか国道もそうですけれども、そういう樹木をひとつとっても弊害があるということにおいて、そこはどういう決まりの中で区民の皆さんに理解をして協力していただけるのかというところが、ある程度整理されるとうれしいというふうに思いますので、そのお考えを聞きたいと思います。","respondent":"高梨公園課長","answer":"隣に枝が行かないようにということで、結構きつめの剪定を数年に１回やっているというような保存樹木もあるような状況ですので、周りの方々の状況も、場所によってまちまちですし、その保存樹のおかれている立地も場所によって違うという状況のもとで、なかなか一定の考え方。","id":"exchange-057"},{"speaker":"塚本委員","kind":"質問・要望","question":"ちょっと確認をしたいことがありますというか、細かく少し教えていただきたいのですけれども、みどり率について、２１.１％から２１.７％にということで、このパーセントだけ見ると、０.６％ということなのですけれども、ヘクタールみたいなことでいうと、品川区では１５ヘクタールということで、林試の森よりももっと大きな面積ということで、なかなか驚くような面積かなというふうに私自身は捉えました。","respondent":"高梨公園課長","answer":"単純に、では、これは何十年後に２５％にすることありきで比例配分で、では、１０年後だから２０何％だねというふうなことで設定するのではなくて、しっかりとこの２５％を目指しつつも、この１０年では何をやっていくのか。","id":"exchange-058"},{"speaker":"塚本委員","kind":"意見","question":"なぜ２５％なのかというのは、いろいろな議論があるのかと思いますけれども、それについて、すみません、ちょっと不勉強で、もしご説明があれば一言お願いしたいのと、あと、一方で、満足度というのは、この中での８０％を目指すということで、主観というような話もこれはありましたけれども、これはまたいろいろなやり方によって、そういう人々のみどりに対する親しみが増えるみたいな感覚というのは。","respondent":"高梨公園課長、藤田防災まちづくり部長","answer":"この２５％につきましては、各自治体でそれぞれみどりの計画を持っているところは、最終的な将来目標に設定しております、都心部、都心の区と、やはり郊外の区と状況も違いますので、品川区においては。そういう中で、都心化した品川区の中で、どの割合を目指すのかといったときに、一律の３０％でそのままいくのは品川区内では難しいだろうということで、昭和５０年代に立てた目標が、それがいいということで。","id":"exchange-059"},{"speaker":"西本委員","kind":"質問","question":"すみません、参考－１２ページを開けてもらっていいですか。ちょっと気がついてしまったので。参考－１２ページの(9)、四角に囲ってあるところ、これ、「渋沢栄一」と書いて、英語表記「shibusawa」、これ、「、」になっているのですけれども、これは何か続くのですか。これは間違いですよね。すみません、ちょっと気になってしまったので。","respondent":"高梨公園課長","answer":"申し訳ございません、ご指摘のとおりでございまして、「後藤新平」の「Goto」のスペルが抜けているものと思われますので、確認をします。","id":"exchange-060"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/297355?Template=document&Id=4332#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":65085,"voices":170}},{"id":"r03-20210922-9","meetingId":"r03-cm09","date":"2021年9月22日","dateIso":"2021-09-22","committee":"文教委員会","time":"午前１０時００分～午後 ２時４６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を74件抜き出しています。","topics":[{"id":"topic-01","title":"はじめに、(1)令和２年度保護者アンケートおよび児童・生徒アンケートの結果","agenda":"はじめに、(1)令和２年度保護者アンケートおよび児童・生徒アンケートの結果","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"このアンケートの中で少し気になったことがありまして、この市民科なのですけれども、私も市民科の教科書をよく読ませてもらうのですけれども、純粋に感じた表現をすると、これは学校でやることなのかな、家庭教育で済む、要は時間を守りなさいとか、それが悪いというわけではないのですけれども。","respondent":"工藤指導課長","answer":"ですから、児童・生徒を育んでいくときには、もちろん私ども教育委員会としては学校教育を中心としながら、家庭とも連携しながら育んでいくという意味では、ご指摘でいただいたようにもちろん家庭での教育が担うところもあると思うのですが、それも含めながら。","id":"exchange-001"},{"speaker":"松澤委員","kind":"質問","question":"私なども時間を守れないと正直思っているので、昔は携帯電話、今のまもるっちみたいなものもなかったですから、もう５時に家に帰りなさい、そこにいなかったらやはり親と会えなかったり、そこで約束事がちゃんとできていないと子どもはその場所に行けない、親もその場所に行けない。だから時間は大事なのだというのがあるから、今はすごく便利になったので、携帯電話１個で「遅れるよ」と簡単に言う。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"吉田委員","kind":"質問・要望","question":"今のご報告は主に肯定的な回答のほうを中心にご報告がありまして、今行われている教育に対して肯定的なご意見があるというのはよいことだと思うのですけれども、今後活かす、よいところを伸ばしていくというのは当然だと思うのですけれども、やはり気になるのは、なかなかそうは思えないという方たちが少数であるけれどもいるということで言うと、そこの趣旨をくみ取るということも。","respondent":"工藤指導課長","answer":"特に学校は自校の結果を分析する中では、その学校の取組がやはりダイレクトに表れてくるところがありますので、そういった意味ではこの児童・生徒のアンケートなどで言うと、学校教育活動の取組そのものを見直すきっかけにもなりますから、そういったところでは。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問","question":"今のご報告だと、今特に具体的に何かこういう回答が少数であっても目立つのだけれども、それについてはこういうことを考えているみたいな議論はまだされていない、とりあえずは集計されたという感じの段階だと捉えてよろしいでしょうか。","respondent":"工藤指導課長","answer":"今回、令和２年度として分析している中では、大きく課題として取り上げて見直しを図るべき、つまり否定的な回答が多く、肯定的な回答を上回るというものが散見できないので、個々に見直す必要があるものはあるかもしれませんけれども。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問・要望","question":"あまり具体的なお答えは伺えなかったのですけれども、やはりせっかくこれだけアンケートをきちんととって、回収率もよいというところでは、よいところを伸ばすということもすごく大事ですけれども、否定的なご意見の中に何か改善できるところがあるのではないかという分析も大変重要だと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"松本委員","kind":"質問","question":"この分析をどのように考えていくのか。やはり一定数参加していただけない方たちがいるというところが、ここでも出てきていると思うのですけれども、では、これをどう考えていくのかというのは、多分これは数字だけ見ても答えは出てこなくて、一つ思うのは、これは自由記載欄というのは特に設けられていないのでしょうか。そこのところをお願いいたします。","respondent":"工藤指導課長","answer":"そういった意味では、品川コミュニティ・スクールで進めている上では、地域連携しているというご認識をいただいている中で言うと、例えば学校行事の一貫として地域行事への参加というのを学校で考えた場合に、そういった保護者の方の積極的な促しがないにしても。","id":"exchange-006"},{"speaker":"松本委員","kind":"質問","question":"決して設問３を品川区の教育においてマイナスに評価しているとかいうわけではなくて、やはり何かあるのであれば原因を探っていただければと思っているので、やはり自由記述欄というか自由記載欄、これは各設問をチェックするようになっているのかと思いますけれども、この下に本当に任意の欄を１行分でも設けていただくことで、それが最終的にどこまで活用できるかというのはその後になるんですけれども。","respondent":"工藤指導課長","answer":"これまでも設問に応じては設けたということはありますので、それは引き続きその設問と、我々が回答として分析したいということも含めながら、研究したいと考えています。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"前回も聞いたのですけれども、現在通っている学校に満足しているという保護者に対する設問なのですけれども、これはむしろ児童・生徒自身にも聞くべきことなのではないかと思うのですけれども、なぜ聞かないのかというのが１点です。３点目は、これはちょっと具体的なのですが、前年度との項目の違いというのは今回どこなのか、削ったところとか新たに追加したところがあればご説明いただきたいと思います。","respondent":"工藤指導課長","answer":"委員のご指摘がございましたが、やはりこれは児童・生徒が素直にそのときの回答を頂きたいという部分でお願いをしていますので、私どもとしては、例えば学習に意欲があるのかどうかも含めながら。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"というのは昨年も質問したのですけれども、さらに今年１年たってみて、やはり子どもの権利条約等もありますので、やはり子ども自身の声を聞くというのは、アンケートで聞けばいいというものではないとは思いますけれども、ただ、それは基本にすべきなのではないかと思うので、なぜ保護者には聞いて子どもには聞かないのかというのがちょっと分からないので、あえてもう一度お伺いしたいと思います。","respondent":"工藤指導課長","answer":"２点頂きました。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはりちょっと違和感があるということなのです。アンケートが、各学校や学年、学級、もっと言えば担任の先生のこういう主体的な自主的な独自の教育活動というのを縛ってしまうというおそれはないのでしょうか。それは当然あるべきだという考えなのでしょうか。あってもいい、あって当然という考えなのか、そこら辺をちょっと伺いたいと思います。","respondent":"工藤指導課長","answer":"例えば子どもに家事を分担しているという今回の結果につきましても、平成３０年度の比較では、肯定的な回答はやや上昇している傾向がポイントではございました。といったところが各校分析をする中でいうと、おうち時間が増えたというこのコロナ禍の中で、家事分担をさせる。","id":"exchange-010"},{"speaker":"安藤委員","kind":"提案","question":"考えはないということですけれども、繰り返すようですがアンケート自体は全く意味がないとは思いませんけれども、やはり考えはないけれども、結果として現場にもたらす作用というのをぜひしっかりと把握し自覚した上でやる必要があると思っていまして、私自身ももう少しこの現場の方々のお話を聞いて、このアンケートのさらなるよりよい環境を作るためのものにするために。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"つる委員","kind":"確認","question":"それはちょっと感想的な話ですが、その意味では先ほどもしかしたら質疑で若干確認があったかもしれないのですが、このアンケート項目というのは当然年度によっていろいろ聞く項目とか聞かない項目とか入れ替えで、その課題だったり、逆に言うと高評価を得たいということで取組みをしていることがいいものかどうかという確認をするとか、いろいろな目的があると思うのですけれども。","respondent":"工藤指導課長","answer":"一定程度、今回設問を絞った理由というのはそういった経緯で令和元年度から、今２年目ですので、今年度、令和３年度に実施するものを含めて３年たつというところです。","id":"exchange-012"},{"speaker":"つる委員","kind":"質問・要望","question":"これは教科そのものの具体的な内容ということになってくるのかと思うのですが、まさに先ほどの部分で指摘させていただいたとおり、そのアンケートが全体としてそういう傾向にあるのであれば、そこがやはり当てはまるというのが教育委員会というか学校側としても広くなってほしいという、市民科というのは品川区独自で、非常にいいものだと私も思ってはいるのですけれども。","respondent":"工藤指導課長","answer":"これはほかの調査結果でも明らかですので、こういったところで、義務教育の出口である９年生の結果の中では、そういった指導の効果が一定程度表れているのではないかと見ておりますので、こういった全体の結果を基にしながら、各校の取組を見直していただき。","id":"exchange-013"},{"speaker":"つる委員","kind":"質問・要望","question":"そういう意味ではその授業だけではない、またその授業を通じての年代とかの部分でそういう傾向というのはあるということに対してのフォロー、学校での一人一人に対する教育をしていただいているというご答弁が今あって、大きい部分での安心はするというところなのですが、ただ、保護者からすると、「良い学習だ思う」という肯定的な意見を欲しいというアンケートに対して。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"湯澤副委員長","kind":"質問","question":"あとこの回答率についてなのですけれども、回答率も９０％を超えて非常に高いと思っているのですけれども、ただ結局これを見る限りだと、例えば児童・生徒ですと１,０００人ぐらいが無回答なのか、それとも用紙を出しているけれども、白紙で出しているのかちょっと分からないのですけれども、そういったところがあるというので、そういったところのこの１,０００人ぐらいが出していないというのは。","respondent":"工藤指導課長","answer":"回答率のところ、特に児童・生徒につきましては、この期間に各学級単位、学年単位で行っていただいておりますので、そのときに出席していない場合、様々な要因も考えられますので、そのときに例えば今年度の調査で言うと。","id":"exchange-015"}]},{"id":"topic-02","title":"令和２年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"令和２年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"これは別に悪いことではないと思っているのですけれども、人件費が軒並み増加傾向というのはどういう理由なのかということが一つです。それと、そもそも品川区としては図書館を指定管理しているわけですけれども、その指定管理するときの成果というのは何で測っているのか、それはどういう考えを持っているのか伺いたいのが２点目です。","respondent":"吉田品川図書館長","answer":"３点頂きました。人件費の増加につきましてどういうことかですけれども、一般的な雇用にあたっての社員の人件費の増という部分も当然あると思いますし、大きいところはそういうところになると思います。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、協定書という形で実際指定管理の仕事をどのようにやるかというのを定めているという話でしたけれども、その協定書自体は品川区の部署で考えて作っているのか、それとももうその協定書の中身自体もどこかに考えてもらっているのか、そこら辺を伺いたいと思います。","respondent":"吉田品川図書館長","answer":"２点ご質問頂きました。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。この指定管理業務の中に、資料の選定ですとか廃棄、除籍というのが入っているわけですけれども、自治体の図書館を考える上で、結構コレクションをどうするかというのはすごく大事な中核的な仕事だと思うのです。ちょっと自治体図書館として住民の要求に応えられないのではないかと私は思うのですけれども、そこら辺はいかがでしょうか。","respondent":"吉田品川図書館長","answer":"中央館は当然私どもがおりますので、そこで二次審査ということで、これは残しておくべきであればそれは残しますし、例えば地区館のほうに置いておく必要がなくても本館のほうで管理するだとか、そういう個別の対応、それから管理はしております。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。本館のほうで一定の区としての考え方というか、関わっているのだというご説明でした。なるほど、分かりました。私は指定管理でやるべき仕事なのかという問題意識があるわけです。やはり自治体、区民の資料の様々な要求に応えるための図書館を作るという点では、指定管理という方法は私は望ましくないと思うのですけれども、先ほどのローカル資料の収集という点でいかがでしょうか。","respondent":"吉田品川図書館長","answer":"普段から地域との連携を取りながら、またこういうものが出た場合は普段から収集しておりますよという地域との連携、この辺はまた地区図書館の得意なところだと思いますし、それをまた全体で管理している本館もありますので、その辺が力を合わせながら。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問・要望","question":"もう一つのＣグループの中で、積極的な評価のところで、ティーンズ資料の充実、アニメ上映会等のサービス拡充に努めているということが積極的に評価されていて、このコロナ禍の中で、生活者ネットワークとしては、ティーンズの居場所とかそういうことが品川区の中で薄いと感じていたので、これはぜひ積極的に進めていただきたいと思ったのですけれども、もう少し何かどういうところなのか。","respondent":"吉田品川図書館長","answer":"それと、例えばＣグループでやったそういういいところが、次のところの協定の中で活かせるのかですが、これはＡ、Ｂ、Ｃグループで毎月一度指定管理者会議みたいな形で会議を開いておりまして、私どもは今。","id":"exchange-020"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。私も本当であれば情報開示請求して全部協定書を読み込んでからというところが本当なのでしょうけれども、なかなかそこまで力が及びませんで、読まずに質問しております。失礼いたしました。ほかにたくさん聞きたいことがあるのですが、別の機会にしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"松澤委員","kind":"質問","question":"不勉強で申し訳ないのですけれども、３グループに分かれている中で、改善が必要とされる点の中に認知症カフェの安定した運営というのがあるのですけれども、これはもう指定管理者のほうで、この認知症カフェ運営というのがもともと入っているものなのか、そこだけ教えてください。","respondent":"吉田品川図書館長","answer":"やれる状況とその環境が整っている、例えばそこそこ大きいホールがないとできないようなものもありますので、そういうところは自分の図書館にそういうホールがなかったりするとやはりできないとかいうのもありますので、環境に依存するところは若干あります。","id":"exchange-022"},{"speaker":"松澤委員","kind":"意見","question":"すみません、失礼しました。図書館の中で認知症カフェということですね。失礼ついでに、ぱっと見て児童おはなし会の会員の数なのですけれども、Ａ、Ｂ、Ｃを比べると、Ａ、Ｂが約２,０００人、Ｃが約３,０００人。これは素人考えで、そのおはなし会がすごく楽しいから人が多いのか、それともこの建てている場所、五反田、大崎はただ単に児童・生徒が多いのか、何かそのようなことがありましたら。","respondent":"吉田品川図書館長","answer":"そのため、ほかのＡグループ、Ｂグループは図書館は３館ずつですけれども、Ｃグループは４館ありますので、その辺の若干の多さは出てくるかなというところは考えられるところです。","id":"exchange-023"},{"speaker":"松本委員","kind":"質問","question":"というのも、例えばＡグループで言うと、これは６００万円ぐらいがっと増えているのです。なので、人件費、例えばこのＡグループの人件費が６００万円ぐらい増えているというところの理由を改めてお伺いしたいです。それとあと、逆にＡグループでちょっと不思議なのは、備品購入費が約４０万円減っているのです。お願いします。","respondent":"吉田品川図書館長","answer":"備品のほうから説明いたします。備品で金額の大きいもの、今１０万円以上するものでありまして、この３年間で書籍除菌機というのを購入しております。","id":"exchange-024"},{"speaker":"松本委員","kind":"質問・要望","question":"ただ人件費のほうは、今の専門職の話とかも出たので、やはり区民の方たちの税金も使われているわけですから、理由をしっかりと把握していただければと思います。これもちょっと不思議で、この１年間やはり休館とかいうこともあった中でこれが増えているという、この辺りは経営会議等では何か問題にならなかったのでしょうか。","respondent":"吉田品川図書館長","answer":"そういうことから、ほかのところに比べて、なぜ大きくなったかというのはなかなか難しいところなのですけれども、相対的には増えていっているところです。大きくなった原因までは、ちょっとそこは踏み込めませんでした。","id":"exchange-025"},{"speaker":"松本委員","kind":"質問・要望","question":"その辺りは本来は専門職の方たちに応募していただきたいところではあるのですけれども、やはりこういったモニタリングというのはやはり公開されて区民もご覧になるものだと思いますので、通常の株主総会とかでも突っ込みが入るようなところというのは、できるだけ掘り下げていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"つる委員","kind":"質問・要望","question":"最初にすごくざっくりな言い方なのですが、品川区の図書館の充実を求めたいと。そういうお子さんが図書館に訪れたときに、今のこの３つのグループで指定管理になっている。そういうお子さんがいらっしゃったときのスタッフの対応というのはどういう感じなのかというのと、この９月に限らず、実際そういうお子さんがいたのかどうかということも含めて実態があれば教えていただければと思います。","respondent":"吉田品川図書館長","answer":"そういう中で、あとは例えばスタッフのほうからお声かけする場合もありますし、スタッフのほうも専門職ですので、何かあれば図書館としての対応はできるかとは思っております。","id":"exchange-027"},{"speaker":"つる委員","kind":"確認","question":"当然親御さんもいなくて。今回のモニタリングだとか評価の項目の中にはそういうものはなかったと思うのですけれども、まさにそういうお子さんがいたときの図書館と、また教育総合支援センターとか教育委員会とか学校とか、そういう連携というのは、把握だとか支援だとかの体制はどうなっているのかというのがちょっと気になったところでしたので、また改めて伺いたいと思います。そこを教えてください。","respondent":"吉田品川図書館長","answer":"これは年２回発行しておりまして、発行にあたっては、各地区の図書館のやはり若手、それから私どもの職員の中でも若手のほうが集まりまして、こういう図書館を若い人たちにうまく紹介していくのにどうしたらいいかというところは。大変失礼いたしました。「ＬｉＬｉＬｉ」につきましてはこのように、変わらず図書館の職員と業者のほうと一緒に作っているところです。","id":"exchange-028"},{"speaker":"つる委員","kind":"質問・要望","question":"分かりました。そういう意味では、どこかの優れている業者があって、そこでやっているのかと思ったら、今伺ったようなことで続けていだたいているというところでは、これは区全体の広報紙にもある意味ではいい影響を与える広報紙であっていただきたいなという部分です。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"松本委員","kind":"意見","question":"先ほどのＣグループの光熱水費で、自己解決したというか、先ほど少しお話をもらいましたけれども、大崎図書館の分館のところで、平成３０年から令和元年で跳ね上がっているので、私はてっきりこれで反映できていると思っていたのですけれども、オープンが令和元年度なので、令和２年１月なので、もうそこからその後、１月ということは数か月分しか令和元年度には反映されていなくて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"}]},{"id":"topic-03","title":"その他の(4)その他","agenda":"その他の(4)その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"特に見たいという場合は、これは事前に申込制ということか、具体的にどのように申し込めがいいのかというのを教えてください。","respondent":"有馬庶務課長","answer":"とりあえず今はこの３日間にもしご都合がよろしければ、この時間は職員が必ずいるということで対応したいと考えています。それ以外についてはちょっと個別にご相談をしていただくしかないかと。","id":"exchange-031"}]},{"id":"topic-04","title":"を改めて聴取いたします。 初めに、(2)令和２年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"を改めて聴取いたします。 初めに、(2)令和２年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"それとあと、改善が必要な事項の情報セキュリティ対策の一層の向上が求められているとありまして、あと具体的かつ継続的な取組が必要とありますけれども、なぜこういうことが事項に入ったのか、どのような経緯があったのか伺いたいと思います。３点目は、ぷりすくーる西五反田のほうにはありますこの支出のところの人件費という項目が、こちらにはないのはなぜなのか伺いたいと思います。","respondent":"伊東子育て応援課長","answer":"情報セキュリティ対策に関しましては、特に何か昨年あったとかいうことではないのですけれども、今までの中でそこが重要だということはもう認識しているところでございましたので、昨今の状況を見ますと。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問・要望","question":"これはちょっと改善をお願いしたいと思います。それと、情報セキュリティですが、では確認なのですけれども、特別にこの年度に何か漏洩とか、そういった不祥事みたいなよくない事例が起こったというわけではないということでよろしいのかちょっと確認させてください。保護者、利用者への不都合などは発生しなかったのか、大丈夫だったのか、伺いたいと思います。","respondent":"伊東子育て応援課長、初貝保育教育運営担当課長","answer":"情報漏洩に関しましてはありません。内部でのペーパーベースのヒヤリハット的なものはあったのかもしれませんが、情報漏洩という形でのことはなかったと聞いています。今、ご指摘ございましたとおりで、本年度４月から福栄会のほうにお願いしていますが、人材の引継ぎに関しましては、保育士は基本的に全員新しい福栄会のほうで引き続き仕事をしているというところで。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問","question":"ぷりすくーる西五反田のほうですけれども、予算執行の視点で、積立金を運営費に回したことにより利用料金等の収入が増加したというところなのですけれども、この特定非営利活動法人子育て品川が積み立ててきた金額というのは幾らだったのか伺います。そういう処理になった経緯を伺いたいと思います。","respondent":"初貝保育教育運営担当課長","answer":"その金額に関しましては、最終的にはおよそ３,０００万円程度の積立金がございましたけれども、それは基本的に今回の福栄会に引き継ぐということで、きちんと委託料のところと相殺しまして精算したです。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問","question":"そのようになった経緯を伺いたいということで質問したので、教えてもらいたいのと、これまでぷりすくーる西五反田を運営するために作られたＮＰＯだったと思うので、それがやる仕事がなくなったというところで、ＮＰＯが積み立てていた金額をぷりすくーるのほうの運営費に回したというのは、それはあり得ることかなとは思うのですけれども。","respondent":"初貝保育教育運営担当課長","answer":"こちらの積立金なのですけれども、今までも基本的には区のほうからの委託料の中で積み立てているもので、ぷりすくーる西五反田のために使うということで、ただ今回指定管理者が福栄会になりますので、そこは一旦ＮＰＯが発展的解散ということになりますけれども。","id":"exchange-035"},{"speaker":"安藤委員","kind":"意見","question":"やはりぷりすくーる西五反田を運営してくる中で積み立ててきた、人材確保をスムーズに行うために積み立ててきたものなので、それがお金に色はついていないということになりますと、ただ単に福栄会の全般的な収入になってしまっては意味がないのではないかと思うので、ここは引き続きぷりすくーるの運営、人材確保等のために使うようにしていくべきだと思うのですけれども。","respondent":"初貝保育教育運営担当課長","answer":"今ご指摘のありました、これはＮＰＯの収入にということは決してございませんで、我々はきちんと何にお金が使われているかということを確認した上で、必要なその積立金の部分は、逆に必要なかった委託料を減らしてきちんと精算をしているというところなので。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"利用者からの意見要望については、意見箱や苦情解決制度など様々な方法で情報収集し、いろいろ改善に取り組んでいるというところなのですが、区民満足の視点というのが利用者という意味だと思うのですが、その利用者から具体的にどのくらい満足度があってということをもう少しストレートに分かりやすく表現することはできないのでしょうか。とりあえず、それで。","respondent":"伊東子育て応援課長","answer":"表現の仕方とか、そう言われるとそうかもしれませんが、ちょっとなかなか書きようがないといいますか、一応そういうことをやっているです。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"事業者にしてみたらそれほど大きな苦情はなかったということで処理されてしまったのかなと思いますが、それが本当に大きいことか大きくないかは、区としてぜひ指定管理者に対する評価としては把握しておいていただきたいのですが、その辺はいかがでしょうか。","respondent":"伊東子育て応援課長、山下子ども家庭支援センター長","answer":"ということでいろいろと、苦情はないのですけれども、いろいろな形で情報収集して、改善して前に進むような形での情報共有をしています。場合によっては一緒に対応を考えていきましたり、どういったところを改善できるかというのはともに考えてまいりますので、今後ともそういった形で区民満足度の向上に努めてまいりたいと考えております。","id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。報告の仕方は本当に個人情報に触れないようなところでの報告でいいと思うのですけれども、区としてはその辺を把握していただきたいと思います。問い合わせをしたときに、空いていて使えるという回答が返ってくるといいと思って伺うのですが、その辺はいかがでしょうか。","respondent":"伊東子育て応援課長、山下子ども家庭支援センター長","answer":"ただ、それは我々のほうも有効活用、有効利用していただきたいとは思っているところですけれども、なかなかＰＲすれば誰でも入れますというような施設ではないものですから、それは個々に本当に相談を受けた上で、その利用を促す。トワイライトステイ等につきましては、一定このコロナ禍において保護者の方が在宅であるがゆえに、トワイライトステイの利用の必要性が生じなくなったといったような事情もありますけれども、そういった事業の拡大であったり。","id":"exchange-039"},{"speaker":"吉田委員","kind":"提案","question":"分かりました。これからも機会があったらまた質問していきたいと思います。その中に、「効率的な施設運営を図るため、委託業務内容の見直しと業務がより効果的に進むよう」というのが、この指定管理者から提案と書いてあるのをどう読んだらいいのか分からなくて、それは読み方が違うというご指摘があれば、それも含めて伺いたいと思います。","respondent":"初貝保育教育運営担当課長","answer":"ＮＰＯの中で一回精算をしています。それとあと、今、ご質問を頂きました指定管理者からの提案などというところに関しましては、１年を振り返りまして、指定管理者から次にどういう形でやっていくかというような項目です。","id":"exchange-040"},{"speaker":"吉田委員","kind":"提案","question":"後半の質問なのですけれども、この指定管理者からの提案等というのは、これはここの旧指定管理者、子育て品川から提案があって、その提案の中に委託業務内容の見直しということが言われていると私には読めてしまうのですけれども、そういう読み方は違うのでしょうかということと、もしそうであれば、その「委託業務内容の見直し」と。","respondent":"初貝保育教育運営担当課長","answer":"その部分に関して連携を図って、より効率的に運営をしていこうというようなところですので、ちょっと表現がこちらはつたなかったところがあるかと思います。","id":"exchange-041"},{"speaker":"吉田委員","kind":"質問","question":"私にはうまく理解できないので、また改めて、別の機会に伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"つる委員","kind":"質問・要望","question":"家庭あんしんセンターについてですが、ちょっと不勉強なところもあり改めて教えていただきたいと思うのですけれども、まず設置目的には母子家庭となっていて、法律の立てつけは両方もう既になっていたかと思うのですけれども、父子家庭が今現在利用できるのか。根拠的なことも含めて、改めて教えてください。","respondent":"伊東子育て応援課長","answer":"母子家庭の自立支援です。現状では問題として、根拠法令もありますし、今現状では母子ということになっているのと、施設的にも混在するのがいいのかどうかというところもあります。何が問題で使えないのかというと言いにくい所もありますが、現状は母子の利用のみです。","id":"exchange-043"},{"speaker":"つる委員","kind":"質問","question":"品川区の条例をざっと見る中では母子となっているので、当然施設設置の条例の意味のところも含めて母子のみなのだと思うのですが、ただ、品川区がこの家庭安心センターを設置するに際しての条例をさらに都の条例ないし国の法律というところでは、今名称はいろいろ変わっているのでしょうけれども、「母子及び父子並びに寡婦福祉法」の中の第３８条とかに「母子・父子福祉施設」とあって。","respondent":"伊東子育て応援課長","answer":"根拠的には児童福祉法に基づきまして、そこの中に「配偶者のない女子及びその者の監護すべき児童を入所させて」ということになってありますので、そこの部分で、表現的には「母子」という形で書かせていただいています。","id":"exchange-044"},{"speaker":"つる委員","kind":"質問","question":"そうすると、いろいろな捉え方や表現、実態とかもあるのでしょうけれども、父子家庭が同様の施設を利用できるようにするためには、今の立てつけ、法律とか都の条例も含めて、区の条例を変えれば、今の同一施設を使うということではなくて別棟を造るとかということも含めてですけれども、借り上げだとかいうのも含めて、区の条例を改正することで、父子家庭に対しても。","respondent":"伊東子育て応援課長","answer":"そういうことも踏まえているという中では、現状では母子の生活支援施設ということで、父子に関しては現状では利用は考えられないです。","id":"exchange-045"},{"speaker":"つる委員","kind":"質問","question":"ニーズですね。件数としては、今の中では多分少ないのかなと推測するのですけれども、相談実績で、なおかつそういうご相談があった際にはどういうサービスの紹介等になるのでしょうか。","respondent":"伊東子育て応援課長","answer":"父親のほうからの相談ということでは、こういう施設への相談ということよりは、離婚してその後どうしようかなというような相談はあるところですけれども、ただ、圧倒的に生活基盤というか仕事的なものというのは。","id":"exchange-046"},{"speaker":"つる委員","kind":"確認","question":"分かりました。ただ、過去にあっては父子寮というものがあったことはあったわけですよね。そういう意味では、今いろいろな家庭のありようになっている中で、そこについての課題というのはちょっと今気になったところなので、確認をさせていただきましたが、そういう相談がもしあった場合、丁寧なご対応を頂きたいなと。この家庭あんしんセンターの課題についてだったので、確認させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"}]},{"id":"topic-05","title":"ひがしやつやま保育園（公設民営保育園）の運営期間延長","agenda":"ひがしやつやま保育園（公設民営保育園）の運営期間延長","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"こちらの保育園は品川駅南開発地域の中に入っているわけですが、延長自体はもちろんいいことだと思うのですけれども、なぜ毎年少しずつ延長していくのか、理由を伺いたいと思います。この表によると令和９年度に閉園ということなのですが、この閉園予定の令和９年度には開発が動くということなのか、どのような説明を保育課として開発部門から受けているのか、伺いたいと思います。","respondent":"初貝保育教育運営担当課長","answer":"は１つ目のご質問に関しましては、例年、毎年この開発のところの部門に対して、次の１年当面利用ができるかどうかという確認を取っておりまして、なかなか一度に多くの期間の確認をというところが取れておりませんので、１年ずつという形で今のところやっております。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問","question":"私が伺ったのはどのような説明を受けているのかということなのです。説明も受けていないで、ただとりあえず１年延びますよということだけ、延ばしても大丈夫ですよということだけ言われているのか。もしそうだとしたら随分と秘密主義だなと思うのですけれども、もう一度、どのような説明を受けているのか伺いたいと思います。","respondent":"初貝保育教育運営担当課長","answer":"確認に関しましては、我々のほうからも１年間の延長、特に入園に関わる話なので、そこの部分、来年度さらに延長ができるかというところを確認しておりますので、それ以上、向こうからも具体的にどういう形になっているのかといった説明は把握してございません。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"随分縦割りだと思うのですけれども、今年の第２回定例会の一般質問でも、私はこの開発そのものの中止を求めたのですけれども、やはり都営住宅を退かせて超高層ビルを建てて、北品川の景観を損なってそこに莫大な税金を投入するという、問題がある事業だと考えています。そういう意見を述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"吉田委員","kind":"確認","question":"これは期間限定ということで、とにかくひろまち保育園の反省なのかなと思ったのですけれども、あのときもちゃんと毎年仕様書を確認しなければいけなかったのだなと思ったのですが、入園させた子どもは全部卒園というような形になっていなくて、５年限定にもかかわらず、毎年同じだけの１歳児、２歳児、３歳児。","respondent":"初貝保育教育運営担当課長","answer":"こちらの運営に関してですけれども、こちらは公設民営園という形になっておりますので、あくまでも区のほうが設置をして、民間の事業者に運営をしていただいているというところなので、そこはきちんと入園の状況も見極めながら管理をしていきたいと考えております。","id":"exchange-051"},{"speaker":"吉田委員","kind":"質問","question":"ということは、こういう運営の仕方による負担は全部区のほうで受け止めて、その事業者については、人件費等を含めてちゃんと成り立つようになっていると理解してよろしいでしょうか。","respondent":"初貝保育教育運営担当課長、立木保育課長","answer":"委員ご指摘のとおりでございまして、区のほうから委託をしていまして、管理をしています。子どもの数の増減によりまして負担が発生するような形の計算はしておりませんので、こうして１年延びることによって、不都合が出るということはございません。","id":"exchange-052"},{"speaker":"吉田委員","kind":"質問","question":"最後に満員だったとして５歳児だけの１５人というような保育園の保育の質をどうやって確保するのか。保護者の方は最終的にはここに入れるということで承知の上ということだと思うのですけれども、その辺について、運営の面もですけれども、保育事業としての在り方みたいなものはどのように検討されているのか、伺いたいと思います。","respondent":"初貝保育教育運営担当課長","answer":"保育のやり方ですけれども、来年度受け付けして、多分先々というお話かと思いますけれども、そこの部分に関しましては、例えば今後の検討の中で、空いたところをどのような形で活用できるかとか。","id":"exchange-053"},{"speaker":"吉田委員","kind":"質問・要望","question":"最終的にはそういうことで、ぜひそのとおり実現していただきたいと思うのですけれども、先ほどのやり取りだとまた延びる可能性もなきにしもあらずということなのかなと思うのですが、何かこういうやり方というのは、受託した事業者としてはどうなのでしょうか。毎年、受託事業者としての事業計画を立てていると思うのですけれども、その辺について何か事業者のほうから意見とかはないのでしょうか。","respondent":"初貝保育教育運営担当課長","answer":"事業者ともその辺りは話しておりまして、令和８年度と少し先のことになってしまうのですけれども、十分事業者のほうの状況も把握をしながら、密接にやり取りしながら進めてまいりたいと考えています。","id":"exchange-054"},{"speaker":"吉田委員","kind":"質問・要望","question":"これ以上言っても押し問答みたいになってしまうと思います。最終的には運営事業者としての事業がきちんと成り立って、かつ保育の質が確保できるような、最終的にはどんどん人数が少なくなってしまう中での委託料で保育の質が確保できるような事業で進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"}]},{"id":"topic-06","title":"大井保育園改築工事に伴う休日保育対応","agenda":"大井保育園改築工事に伴う休日保育対応","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"こちらは定員の変化というのはあるのかというのを伺いたいのと、あと、これまでやっていなかった品川保育園のほうで緊急対応するということだと思うのですけれども、その際の人的な体制の支援みたいなことはちゃんとされるのか、その辺についても伺いたいと思います。","respondent":"初貝保育教育運営担当課長","answer":"それとあと、品川保育園での対応に関しましては、今までもそうなのですけれども、各園から応援というような形で担当を組みまして、大井保育園もそうだったのですけれども、品川保育園だけに負担がかからないような形で体制を整えて。","id":"exchange-056"}]},{"id":"topic-07","title":"認可保育園の新規開設等","agenda":"認可保育園の新規開設等","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"確認ですが、どんぐり保育園の統合に伴っての定数というのは変わらないのかということが一つです。それと、すみません、保育所型認定こども園とはざっくり言うとどういう園なのか、伺いたいと思います。","respondent":"若生保育支援課長","answer":"２点ご質問いただきました。","id":"exchange-057"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。あわせてポピンズナーサリースクール上大崎のほうなのですけれども、２年後の４月に開設を目指しているということですね。施設の建設にあたって、従来から懸念があった近隣住民の皆さんへの説明とか意見を伺う機会はどの程度持たれたのでしょうか。その結果、この施設に反映された点は何か具体的にあったのか、伺いたいと思います。","respondent":"若生保育支援課長","answer":"昨年度令和２年度につきましては、事業者が決定した後に、事業計画と解体工事の説明会を昨年１１月に行いました。その後、今年の４月になりまして、新築の計画説明会というのを事業者が主体で行っております。","id":"exchange-058"},{"speaker":"安藤委員","kind":"質問","question":"保育園はまだまだ必要だと思いますので、特にこの上大崎のほうはなかなかないというのもあると思いますので、ぜひ今後とも様々地元の住民の方のご意見も伺いながら、地域とともに共存できるような保育園の整備をお願いしたいと思います。今年度４月は５人という発表でしたけれども、それを目指しているのか、伺いたいと思います。そこら辺も伺いたいと思います。","respondent":"若生保育支援課長","answer":"そういう観点から計画を立てておりますので、今後もニーズ、これは人口の見込み等も変わってくる部分もありますので、そういったものに合わせて柔軟に対応していこうと思っているところです。","id":"exchange-059"},{"speaker":"安藤委員","kind":"質問","question":"まだまだ区としては増設する必要があると考えているのか、そこら辺ですね。１点目はまだまだ認可保育園を増設しようという考えがあるのかということと、もう一つは、そういう隠れ待機児童というニーズもきちんと踏まえて、認可保育園の増設というのが私は必要なのではないかと思うのですけれども、いかがでしょうか、その２点、最後にお伺いしたいと思います。","respondent":"若生保育支援課長","answer":"そういった観点できちんと必要な数の供給を行うということで、今後も進めてまいりたいと考えています。","id":"exchange-060"},{"speaker":"安藤委員","kind":"意見","question":"受け皿があるかのようなことをおっしゃるのですけれども、先ほど紹介したのは、実際に不承諾を受けたのですけれども、そういう認証にも認可にも無認可にも入れない、小規模にも入っていないという方なのです。６６人の方は入れなかったから、求職を休んでいる人が６６人もいましたし、あと３６８人の方は、徒歩３０分以内に入れる保育園があるのに選ばなかったというだけで、しかも１年だけではないですよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-061"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういう方なので、決して私はその方々がどこかに入れているということではないと思いますので、やはりそういう隠れ待機児童のところもきちんと見据えて、増設計画を立てていく必要があると思います。そうしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"吉田委員","kind":"提案","question":"いろいろ提案をもらいながらそれを点検しているということだったのですが、このglobal child careはほかのところで実績とかはあるのでしょうか。すみません、私は品川区の状況しか把握していないので。それをどのように評価されたのか、伺いたいと思います。","respondent":"若生保育支援課長","answer":"新規開設の１件目のあい・あい保育園の事業者であるglobal child careですが、こちらはご指摘のとおり、品川区内では初の事業者となっています。初めてですので、いろいろと区のほうでも確認等はしています。","id":"exchange-063"},{"speaker":"吉田委員","kind":"質問","question":"もうご存じだと思いますけれども、生活者ネットワークは毎年保育従事者人件費比率が載った資料を東京都が公表している「こぽる」には載っていない情報が載った資料を要求しております。これから私たちも調べればよいのですけれども、この事業者がほかで運営している園について、保育従事者の人件費比率とかも確かめられたかどうか、伺いたいと思います。","respondent":"若生保育支援課長","answer":"指摘いただきました他園での第三者評価は、区でも確認を行っております。すべてですと七十何園ありますので、すべて見たわけではございませんけれども、都内でも幾つかの園を見てあります。その中で、おおむね良好な結果だったと認識しております。","id":"exchange-064"},{"speaker":"吉田委員","kind":"確認","question":"再度確認ですが、この６０％というのは、保育に従事している方の人件費比率と考えてよろしいでしょうか。それで６０％だと、今運営されている中ではかなり高いなと考えていますが、全体の人件費比率と、それから保育従事者の人件費比率とあるのですが、どちらの人件費比率か教えてください。","respondent":"若生保育支援課長","answer":"こちらは全職員の人件費比率でございまして、保育士のみではございません。保育士のみとしては把握してございませんので、確認したいと思います。","id":"exchange-065"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ、私たちも事業が行われれば確認をしますけれども、これは「こぽる」には出ていないのです。それから、こっこるですけれども、私の手元にあるのが古い資料というか手に入るものでは最新の資料なのですけれども、前は幼児活動研究会株式会社となっているのですけれども、そうではなく、社会福祉法人のということなのでしょうか。ちょっと伺いたいと思います。とりあえずそれでお願いします。","respondent":"若生保育支援課長","answer":"特に実態が変わるものではございません。","id":"exchange-066"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。保育園でその数もとても大切で、まだ入れない方もいらっしゃるということで言えば数を増やすことは大切だと思いますけれども、やはり保育の質の確保ということで言うと、保育従事者の処遇というのがすごく大切だと、それがすべてではないですけれども、やはり処遇が悪い中ではなかなか保育の質も確保できないということで、生活者ネットワークとしては保育士の処遇の改善を求めております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"}]},{"id":"topic-08","title":"その他を再度議題に供します。 はじめに、(1)所管質問","agenda":"その他を再度議題に供します。 はじめに、(1)所管質問","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"私からは、初日の石田秀男議員からの一般質問の中で、総合実施計画についてのご質問の中に、児童相談所の人材確保についてのご質問がありました。そのご答弁の中で、今人材確保がどこも大変で採用競争が激しいと。任期付職員をどのようなところで、どういう視点で活用するのか、もう少し具体的なご答弁を頂きたいと思います。","respondent":"加島児童相談所移管担当課長","answer":"このたびの任期付職員採用の趣旨といたしましては、令和６年度中の区立児童相談所開設を目指す中、児童相談行政に精通した管理職の下、児童相談所の運営体制の具体的な検討などを確実に行っていく必要があること、また児童相談所に係る専門的知識や豊富な経験を有する人材の下。","id":"exchange-068"},{"speaker":"吉田委員","kind":"質問","question":"すみません、今ご答弁いただいたのはもうそれぞれ本当に必要な、受験してくださるといいなというような人材だと思うのですけれども、５年を越えないようにとする趣旨が私にはよく分からないのですが、その理由を教えてください。","respondent":"加島児童相談所移管担当課長","answer":"こちらの条文の中で、一般職任期付職員の採用につきまして、任期は５年を越えない範囲内とすると定められておりますので、そちらを根拠としております。","id":"exchange-069"},{"speaker":"吉田委員","kind":"質問","question":"ということは、既に経験がある人を採用するにはこの制度を使うという趣旨なのでしょうか。基本的に一般的な採用だと、いきなりこういう経験者を管理職にするような形での採用はできないからという趣旨で理解してよろしいのでしょうか。ごめんなさい、基本的なことが分からないので。","respondent":"加島児童相談所移管担当課長","answer":"今回、任期付職員の採用につきましては年齢の定めがございませんので、例えば他自治体を退職した職員など、知識・経験の豊富な方に品川区で活躍いただくことを想定して、人事課のほうに協議を行ったものです。","id":"exchange-070"},{"speaker":"吉田委員","kind":"質問","question":"そうしますと、５年を越えないということで言うと、この方たちの先ほどの業務内容に入っていたでしょうか。区の職員をそういう人たちに育てていくというようなことも、業務内容に含まれているという理解でよろしいでしょうか。５年で育つのかなとか思いながら、ぜひそういうことも業務に入っているべきだと思うのですが、それについてご答弁をお願いします。","respondent":"加島児童相談所移管担当課長","answer":"ただいま委員からございましたとおり、任期付職員につきましては、持てる知識・経験を最大限に活かしていただいて、区専門職の指導・育成にあたってもらうことを考えております。","id":"exchange-071"},{"speaker":"吉田委員","kind":"質問・要望","question":"具体的な制度のことは全然よく前提としないで、できることなら長く勤められるような方でじっくり育成していただきたいと思って質問させていただいたのですけれども、まず今その人材の獲得競争が激しい中で、この制度を使って即戦力になるような人を採用していきたいということで理解をいたしましたが、見込みとして、最初の一般質問のご答弁にもありましたけれども。","respondent":"加島児童相談所移管担当課長","answer":"人事課にて、区内施設のほうに実施要綱を配布・設置しておりますほか、有識者ですとか、視察等で得たつながりを活かしまして、各方面から経験豊富な人材を集められるよう、所管のほうでも努めているところです。","id":"exchange-072"},{"speaker":"吉田委員","kind":"質問・要望","question":"私の質問の意図も、先ほど言いましたけれども、できることならずっと勤めていただける方でそういう人材が確保できたらと思って質問させていただきましたけれども、そういう状況であれば、即戦力になる人材はこの制度を使ってということですので、どこも目指していると思うのですけれども、ぜひ品川区としてもよりよい人材の確保を目指していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"安藤委員","kind":"質問・要望","question":"児童相談所の職員の方は、本当に高度な専門的な経験とスキルが求められてくると思います。ただそれがなかなかすぐにはかなわないのでということだと思うのですけれども、これは臨時的な措置だと考えていらっしゃるのか、将来的にはその辺についての見通しだけ、ちょっとお聞かせいただければと思います。","respondent":"加島児童相談所移管担当課長","answer":"これからの区立児童相談所を担っていく人材といたしましては、特別区人事委員会のほうで実施しております新規採用や経験者採用を中心に、長く勤められる職員の確保にも区として努めているところです。","id":"exchange-074"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/186280?Template=document&Id=5044#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":62490,"voices":207}},{"id":"r03-20210922-5","meetingId":"r03-cm09","date":"2021年9月22日","dateIso":"2021-09-22","committee":"総務委員会","time":"午前１０時００分～午前１１時１９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","topics":[{"id":"topic-01","title":"その他のうち、(1)所管質問","agenda":"その他のうち、(1)所管質問","exchanges":[{"speaker":"田中委員","kind":"意見","question":"９月１６日の大沢真一議員の「デジタル化への対応について」の質疑の中で、区の対応として、「情報戦略担当新設に併せて任期付職員の採用を検討中」とご答弁がありました。どういった人材を何人採用して、任期はどの程度を検討しているのか。その状況について、お知らせください。","respondent":"宮澤情報推進課長","answer":"公募により、採用するべく準備を進めているところです。任期は令和４年４月１日から令和６年３月３１日までの２年間を予定しています。","id":"exchange-001"},{"speaker":"田中委員","kind":"意見","question":"今課長級の方を２年間採用ということだったのですが、課長級の方を２年間採用ということがいまいちよく分からないというか、なぜ課長級なのかということと２年間という期間の根拠をお知らせいただけますか。","respondent":"宮澤情報推進課長","answer":"２年間にしているのは、区のデジタル化を進めていくに当たりまして、自治体デジタルトランスフォーメーション推進手順書というものが国からも示されておりまして、例えば情報システムの標準化の対応であったり、行政手続のオンライン化、そういったものを令和６年。","id":"exchange-002"},{"speaker":"田中委員","kind":"確認","question":"期間ですけれども、今は２年間としているけれども、延びる可能性も考えられるということですかという確認と、あと、その２年間で課長級という今のお話でしたけれども、２年間の間に高度な専門性を持つ課長の知識を任期が終わった後に課長になられる方が習得しなければならないではないですか。そのための引継ぎというか、そういったことなども含まれての最大５年間の期間ということなのでしょうか。","respondent":"宮澤情報推進課長","answer":"それもありまして、知識等の豊富な民間人材を採用するところです。その２年間の中で、デジタル人材の育成ということにも取組んでいただきたいと考えておりまして、一般職員を含めてデジタル化に対応できるような職員育成も考えているです。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"レベル４相当の方が来られるということですが、その方は現在それなりの高収入を得ている方が多いのかなというふうに想像できるのですが、相当の額を支払わないと、高報酬でないと実際には来てくれないのではないかという懸念があるのですが、その辺は大丈夫なのですか。それと、今田中委員からもありましたが、このデジタル化というのは、日進月歩、どんどん進化しているではないですか。","respondent":"宮澤情報推進課長","answer":"デジタル人材、民間企業でもデジタルトランスフォーメーションに取組む企業は大変多く、不足していると言われているところですが、自治体のこういったデジタル人材の報酬に対する支援策というものが国のほうでございまして、自治体の募集状況というのを、国、総務省になりますが。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問","question":"体制を聞きたいのですけれども、今後、新しい課長とかがいらっしゃって、情報戦略担当と情報推進担当のところの体制が、今情報推進課が１６名ということですよね。体制がどうなるのかということなどを伺いたいのですけれども。","respondent":"宮澤情報推進課長","answer":"情報推進課の中に情報戦略担当という新しい部署があります。新たに採用する方につきましては、情報推進課の中で情報推進課長と協力しながら、区のデジタルトランスフォーメーションの推進に取組んでいくというところになってあります。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問","question":"私の質問の仕方が悪くてごめんなさい。情報戦略担当の任期付のレベル４相当の方がいらっしゃる部署の構成というか、何人ぐらいの方たちがこの情報戦略担当の中に今後育成の人材として、ここに関わるのかといったところを知りたかったのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問","question":"９月１６日の石田秀男議員の「総合実施計画について」の一般質問の中で、企画部長がお答えだったので、ここが所管すると思うので伺うのですけれども、新庁舎に関連したにぎわいゾーンの質問に対して、多くのにぎわい集約ができる施設が必要とご答弁されていたと思うのですが、その多くのにぎわい集約ができる施設というのはもう建設の想定がされていて、計画などがあるのかといったところを伺いたいです。","respondent":"佐藤（聡）計画担当課長","answer":"その中で区の中心核としてふさわしいにぎわい創出を図る地域として、こちらは位置づけられております。現在新庁舎の計画につきまして、新庁舎の規模を含めて検討が進んでおりますので、今後、にぎわい施設の整備につきましても、そちらを踏まえて検討してまいります。","id":"exchange-007"},{"speaker":"田中委員","kind":"質問","question":"部長の一般質問での答弁に「集約ができる施設が必要」という言葉があったと思うのです。なので、区として今のところ計画自体ないといったご答弁だったのですけれども、今後の新庁舎の状況を見て検討していくということで、検討の中には今後造っていくということが含まれているのか。そこのところについて伺いたいと思います。","respondent":"佐藤（聡）計画担当課長","answer":"基本的には新庁舎のほうを先行して検討しておりますので、そちらの規模ですとか、位置も含めて、そちらのほうの検討が終わりまして固まってから、今後にぎわい施設の具体的な検討をしていくという順番で考えておりますので、新庁舎の検討が終わりましたら。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"分かりました。新庁舎の検討次第で今後見ていくといったご主旨だったと思います。どういったものが、今本当に一番重要なのかといったことが議論できるような場というのも、ぜひ今後もし造るのであれば、そういう計画とかが検討されるときには、ぜひその方たち、当事者の方たちを交えた話合いの場を持っていただきたいと強く要望したいのですけれども、いかがでしょうか。","respondent":"佐藤（聡）計画担当課長","answer":"こちらにつきましては、にぎわい施設ということで、区の中心核である大井町エリアのさらなるにぎわいの向上ということを目的としている地域ですので、区民の方からの意見を伺いながら、検討を進めたいと考えております。","id":"exchange-009"}]},{"id":"topic-02","title":"在住外国人向け情報のＬＩＮＥ配信事業の開始","agenda":"在住外国人向け情報のＬＩＮＥ配信事業の開始","exchanges":[{"speaker":"田中委員","kind":"質問","question":"今現在ある品川区ＬＩＮＥ公式アカウントの今のフォロワー数というのは、区民の大体どの程度が活用されていて、また今回の在住外国人向けのＬＩＮＥについては、現在１２,８３６名いらっしゃるということですけれども、どの程度の方が登録してくださると見込んでいるのかといったところを伺いたいのですけれども。","respondent":"古巻総務課長、大澤広報広聴課長","answer":"区のＬＩＮＥのフォロワー数、登録数は今手元にないのですけれども、外国人向けのこういったアカウントにつきましては、ほかの区で新宿区でしたか、やっているのですが、数百人程度の登録ということなので。区の公式アカウントの登録数は現在約７千となっています。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"今回２つのアカウントを開設して、いい情報を配信するということなのですが、外国人の方、住んでいる方の居住先等は区のほうで把握されているのでしょうか。もし、居住先等を把握できているようならば、郵送などでできるだけ本人宛てに、直接ダイレクトに連絡する。それでも届かない場合があると思うのですが、そういう工夫というのはされているのでしょうか。教えてください。","respondent":"古巻総務課長","answer":"委員のご提案もありますので、いかにしたら広く周知できるかということはさらに検討を進めていきたいと思いますが、あまり日もないことですので、まずはチラシ等で周知しながら継続的に周知をしていくでありますとか、外国人関連団体にお知らせすることで。","id":"exchange-011"},{"speaker":"須貝委員","kind":"意見","question":"ほかの自治体の情報発信を見たら、「友達が友達に伝えてくださいよ」というようなことがコメントとして書いてあるのですけれども、せっかくいいこと、また、品川区では防災もそうですけれども、コロナ対策もそうですが、清掃等、様々な事業があるわけで、せっかくいいことをやっているので、それを何とか見てもらえるような工夫を私はしたほうが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"たけうち副委員長","kind":"確認","question":"確認ですけれども、ＬＩＮＥということなので、文字で配信される。それとも音で。","respondent":"古巻総務課長","answer":"基本的には文字での配信になります。一部絵みたいな、図表というか、そのようなものも使われることになろうと思いますけれども、基本的には文字情報の配信です。","id":"exchange-013"},{"speaker":"たけうち副委員長","kind":"意見","question":"今は英語と日本語ですけれども、今例えばホームページなどは中国語や韓国語もやっていますが、今後はそういうふうにもう少し言語を増やしていくような方法もあるのかどうか。","respondent":"古巻総務課長","answer":"先ほどもご答弁させていただきましたが、８割程度はやさしい日本語と英語である程度把握ができるというような認識を持っておりますが、今後のサービス拡大につきましては、配信内容も含め、随時広げていくとか。","id":"exchange-014"},{"speaker":"田中委員","kind":"質問","question":"すみません。予算は幾らですか。伺いたいと思います。","respondent":"古巻総務課長","answer":"今細かい数字の資料が手元にないので、申し訳ございません。だいたい３００万ぐらいの金額です。","id":"exchange-015"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"契約方法のところ、最初のほうのご説明のところですけれども、一般競争入札をはじめとして４つの方法が規定されていると説明されていて、(1)では一般競争入札ではなく制限付き一般競争入札が実際には行われているということなのですが、実際には一般競争入札は行われていなくて、制限付き一般競争入札が行われているという理解でよいのかどうなのかということが１つ。","respondent":"東野経理課長","answer":"一般競争入札につきましては、委員がおっしゃるように、地方自治法施行令第１６７条で規定があるものです。","id":"exchange-016"},{"speaker":"田中委員","kind":"質問・要望","question":"契約方法の(3)随意契約のところですけれども、これも今後の要望になるのですが、随意契約が実際に上がって審査をする際に、随意契約の説明というのが資料の中ではなかなかなくて、随意契約に関しては前もって資料請求をして、どういった経緯で随意契約になったのかということを調べてから私たちはいつも態度を決めているのですが。","respondent":"東野経理課長","answer":"それらを全部示すのはなかなか難しいのかなと思いますので、開示請求などがある場合につきまして、１件１件示しているというような状況ですので、ご理解いただければと思います。","id":"exchange-017"},{"speaker":"田中委員","kind":"質問","question":"全てをというわけではなくて、どういった理由で随意契約になったのかということだけでいいので、ぜひ知らせていただけると。その前の情報開示なども、情報開示すれば得られる情報ですけれども、ほかの委員の方たちにも共有できたほうがいいのではないかなということを思うので、ぜひ検討していただければと思いますが、いかがでしょうか。","respondent":"東野経理課長","answer":"随意契約の理由につきましては、規定にあります第何号という部分で示させていただいているものが根拠になるのですけれども、細かいものにつきましては、先ほどお話しさせていただきました業者推薦理由書などによって。","id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"先ほど、一般競争入札の場合において、品川区では業者の信用の面で、一定の制限を設けているというお話をお聞きしましたが、会社の経営面、財政面、それからかつての仕事の成果といいますか、実績といいますか、そういうものに関して、しっかり調査した上で、一般競争入札から外しているのか、その辺は実際どうなのですか。","respondent":"東野経理課長","answer":"業者の実績、あとは信頼性という部分ですが、先ほどご説明させていただきました東京電子自治体共同運営サービスへの登録というものを義務づけておりますので、そこの審査の中でそういった実績を基に格付を行っているというものです。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"そこでお聞きしたいのですが、品川区は支払いもいいし、コンスタントに仕事がある中で、なぜこれだけ入札する業者の件数が少ないのかというのは、どのような理由をお考えなのでしょうか。入札記録を見ますと、毎回３社、４社、５社。競争というのですけれども、２社、３社で、それは競争と言えるのでしょうか。そして、入札価格。この手法での入札価格を適正な価格というふうに考えているのでしょうか。","respondent":"東野経理課長","answer":"予定価格の公表によりまして、事業者間同士で調整ができてしまうのではないかという部分ですが、先ほどもご説明させていただきましたいわゆる談合につながるというようなところにつきましては、区として看過できないところですので、そういう情報がありましたらば。","id":"exchange-020"},{"speaker":"須貝委員","kind":"質問・要望","question":"やはり先ほどお話がありましたけれども、談合はこれで防げているのか、本当に大丈夫なのだろうかということは、私は今後も考えていってほしいなと。何かいい方法があったら、そういうものも考えて、私はできるだけ多くの区民が見ても、これならかなり透明性、または公平性が大きいなと十分に思えるような仕組みづくりをしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"田中委員","kind":"意見","question":"すみません。関連してですけれども、さっき聞き忘れてしまって、入札談合等関与行為の排除および防止に関する法律の説明があったのですけれども、区の中でこういう談合に関する規則・条例などがあるのかということをお知らせいただけますか。","respondent":"東野経理課長","answer":"区としての規則はございませんが、例えば指名停止基準というものがございまして、その中に談合に関するような、いわゆる社会信用失墜行為を行ったものに対しての処分規定というものがあります。","id":"exchange-022"},{"speaker":"たけうち副委員長","kind":"質問","question":"どのようにしてやっていらっしゃるのか教えていただければ。","respondent":"東野経理課長","answer":"大手のところから安くというような考え方もあると思いますが、区内業者育成という観点を品川区としては強調して契約をしているものです。","id":"exchange-023"},{"speaker":"たけうち副委員長","kind":"質問・要望","question":"考え方は、我々も品川区民なので、ぜひそういう方向でとは思うのですが、あとはそんなに極端に変わらないと思うので、金額のバランスを考えながら、中にはそうではないものもあるかもしれないわけで、そこら辺は分からないですけれども、あとこれもなかなかお答えづらいかもしれないですが、そういう中で何社かずっと同じ、実際に具体的に何か分かって言っているわけではないのですが。","respondent":"東野経理課長","answer":"すみません。先ほどの文具等のお話の中で１点答弁漏れがございました。職員が頻繁に使うようなものとかもありますので、そういったものは用品基金、会計管理室のほうで、指定しております用品基金の中での対応というものも一部あります。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/307500?Template=document&Id=2210#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":23590,"voices":88}},{"id":"r03-20210924-14","meetingId":"r03-cm09","date":"2021年9月24日","dateIso":"2021-09-24","committee":"行財政改革特別委員会","time":"午前１０時００分～午前１１時２７分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"私のほうから少しお聞きしたいのですが、資料３の素案要約版の一番後ろのページ、８ページですか、事業計画に対して事業手法がありますが、従来方式と設計・施工一括発注方式、ＰＦＩ方式と書いてありますが、従来方式というのは、一般的な民間企業が建設するときに、こういう手法を取っているというのが大半だと思います。","respondent":"東野経理課長","answer":"こちらを採用した他区の事例などを聞いておりますと、このＤＢ方式を使うこととは別にＣＭ方式、コンストラクションマネジメント方式ということで、別の業者が管理するような方式を取っているということも聞いておりますので、ＤＢ方式採用の場合は。","id":"exchange-001"},{"speaker":"須貝委員","kind":"質問","question":"まだこれからもんでいって、どういう建物にしていくのかとお考えだと思うのですが、その皆さんのご意見の中で、庁舎内が非常に使いやすい、それから、区民が使いやすい、それから、働く人も、職員の方も動きやすい、新庁舎ならば働く場所ということですから、それがやはり基本的な第一のコンセプトになると思います。","respondent":"東野経理課長","answer":"ただ、委員がおっしゃるとおり、区民が、窓口等に来られた方が一番使いやすい低階層への配置というものは、今後考えていくべきものだと考えています。","id":"exchange-002"},{"speaker":"須貝委員","kind":"質問・要望","question":"最後に１つだけ、災害対策で、区民にとって、やはり新庁舎に対しては区のシンボルになると思いますが、大災害が起きたときに、やはり近くの地域センター、近くの避難所も利用するということはありますが、大半の方が考え方として、新庁舎のほうに救助、救援を求めてくるのかな、またここも、避難してくる方も多数出てこられるかと私は思うのですが、その辺に対して。","respondent":"東野経理課長","answer":"職員が庁舎で寝起きができるようにというようなお話でしたが、災害時につきましては、関係機関も含めまして、ワークスペースの確保というものを目指していきたいと考えていますので、その中に、もしそういうものが必要であれば、今後。","id":"exchange-003"},{"speaker":"芹澤委員","kind":"意見","question":"要約版の４ページの、「人すこやか共生」というところの一番下に、「職員にとっても働きやすい機能性にあふれた庁舎とすることで、業務効率化と質の高い区民サービスが提供できる」というのを目指すと書いてあります。ほかの民間だと、結構ワンフロア、オープンスペースみたいになっているところがあると思うのです。","respondent":"東野経理課長","answer":"そういった職員の福利厚生に資するようなところにつきましても、今後設けていく必要があると考えておりますので、詳細につきましては、基本計画の策定の段階で考えていきたいと思っているところです。","id":"exchange-004"},{"speaker":"西村委員","kind":"質問・要望","question":"１点だけお伺いさせてください。アンケートのほうですけれども、ＷＥＢ回答を用意していただいたおかげで、ＷＥＢ回答が約４割ぐらいありますので、回答者の方の年齢層がバランスよく、積極的に回答していただけた結果でもあるのではないかと考えています。","respondent":"東野経理課長","answer":"少し先ほどからの繰り返しになりますが、基本計画策定の段階でどういったものが必要かという部分については、十分考えていきたいと思います。そういった階段、廊下が狭いなどといった部分、バリアフリーに対応するような部分につきましても、十分考えていきたいと思います。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問・要望","question":"策定委員会にも出席させていただいていますので、大体の内容は確認をさせていただいていて、素案の中にこれを入れていただきたいということも反映を確認させていただきました。これはどの程度までのいわゆる達成というか、目標値みたいなものも立てていく方向性なのかというところ、これも、基本構想ではなくて基本計画の策定委員会の中で議論していくということなのか、その２点について教えてください。","respondent":"東野経理課長","answer":"ＳＤＧｓのところですけれども、こちらにつきましては、１７の目標に向けまして、庁舎の計画の中で取り組んでいくべきものと捉えておりますので、そちらにつきましてももう少し細かい内容につきましては、例えば目標とするもの等につきましては。","id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問","question":"この「一定地域内の建物群に対して蒸気・温水・冷水などの熱媒を熱源プラントから導管を通じて供給する」ということについて、これは、こういうことが環境性能を上昇させるのに資するという考え方もあると、こういう理解をせよと、こういうことでよろしいですか。","respondent":"東野経理課長","answer":"一定程度の環境に配慮という部分と、それから、庁舎の光熱水費削減に向けてという部分になってきますので、すみません、語句がどこに該当するかという部分につきまして、記載がここですと言えないのがもどかしいのですけれども。","id":"exchange-007"},{"speaker":"塚本委員","kind":"質問・要望","question":"庁舎の素案の本編のほうですが、いろいろな機能が整理されていて、共通機能ということで、ユニバーサルデザイン、ＤＸ、デジタルトランスフォーメーションの推進、セキュリティ対策と、こういったことで、特にこのデジタルトランスフォーメーションの推進のところが３５ページですかね。とても大切な視点だと考えています。こういったことにもぜひ力を入れていただきたいと考えていますが、いかがでしょうか。","respondent":"東野経理課長","answer":"ＤＸの推進、特に自治体ＤＸの推進という部分ですが、３５ページにも記載のとおり、委員がおっしゃったとおり、デジタルデバイド、いわゆる情報弱者の方々にも配慮した形で、役所の窓口等のあり方を今後考えていくべきものと考えています。","id":"exchange-008"},{"speaker":"塚本委員","kind":"意見","question":"ぜひよろしくお願いします。新庁舎が、デジタルトランスフォーメーションもしっかり機能として持っている、最新鋭だというだけではなくて、デジタルデバイドというものも解消していく、区内においてそういった１つの象徴的な場にもなるということを期待いたしますので、よろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"大倉委員","kind":"質問・要望","question":"環境について非常にいろいろな、積極的に再生可能エネルギーを使っていくとか、高効率化の庁舎にしていくとかというところがあるのですが、例えば今も庁舎内で食堂があったりして、食品ロスとか、そういったところへの取組というのも、今後、庁舎ができたときに、きっと食堂というか、カフェなのか分からないですが、そういったところが入ってくるというのは考えられるのですが、そういったところでも。","respondent":"東野経理課長","answer":"区民対応のスペース、それから職員の執務スペースについて、まずお答えさせていただきたいのですけれども、現在の考えでは両方必要だというものです。","id":"exchange-010"},{"speaker":"大倉委員","kind":"質問","question":"食品ロス、ありがとうあります。基本構想というところで、こういった環境対策をしっかりしていくというところで少し伺ったので、ありがとうございました。職員の働き方、敷地面積はある程度限られてくる中で、スペースのあり方というのもしっかり検討していただいて、区民の方がより利用しやすい環境をつくるためには、職員のスペースをしっかり確保していく。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"渡部委員","kind":"質問","question":"その辺の話し合いは進んでいるのとかというところと、どういうふうな見込みというか、分かれば教えてほしいのと、あと、結局、事業費合計４００億円にそこで影響もしてくるし、設計も変わってくるしというところの中で、ここで起債をかけていくというところと基金というところで、基金は今、施設整備はたしか４００億円はもうあるのだけれども、では、全部まるっきり使うわけにもいかないし。","respondent":"東野経理課長、黒田財政課長","answer":"４００億円というのもあくまでも概算金額、それもざっくりとした金額ですので、これにつきましては、やはり基本計画の段階で、もう少し詳細なものが進んできたところで決めていくものとしておりますので。起債の制度ですが、今、経理課長が申し上げたとおり、どこまでが起債の範囲になるかというところが決まりませんと、概算事業費が出てこないのですが、今の制度ですと、庁舎建設ですと一般事業に該当するということで。","id":"exchange-012"},{"speaker":"せお委員","kind":"質問・要望","question":"アンケートのところから１点だけお聞きしたいのですが、アンケートの１１ページの庁舎を利用した際の印象で、「5)区民が活用したり交流したりできるスペースが不足している」というのが、ほかと比べて「そう思わない」が多いというところと、あと１８ページでも、新庁舎に求められる機能についてというところで、「重要でない」が多いのは議会機能で、議会に関して興味がないのは少しショックなのですが。","respondent":"東野経理課長","answer":"１１ページ、「区民が活用したり交流したりできるスペースが不足している」という部分ですが、これはもう半数以上の方が不足していると捉えております。","id":"exchange-013"},{"speaker":"せお委員","kind":"質問・要望","question":"ほかの項目から比べて、比較的少ないというか、関心が少し少ないところではあるようなのですが、私としてはとても重要かと思っていますので、バランスを考えていただいて、そこら辺もしっかりと検討していただきたいと思って、要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"提案","question":"何点かお伺いをしたいと思います。初めにお伺いしたいのは、これは基本構想で、一部基本計画に踏み込んでいる部分も書いてあるかと考えていますけれども、それから、この基本計画が多分一番重要になるかと私は思っています。それが１つ。それから、もう一つ言うと、分かりやすく教えてほしいのは、例えば「ぐるっぽ」は、事業者が決まって、事業者が連れてきた設計会社がいて、それで施工会社もやったと。","respondent":"東野経理課長","answer":"ＪＲとの関連におきましては、区画道路をどうするかとか、それから、ＪＲの駅から続くデッキをどうするか、そういった部分につきましても、広町地区の開発計画の中で共同で検討させていただいているところですので、そういったところを踏まえながら。","id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"確認","question":"最初の基本計画が非常に大切な部分だと思っています。容積率の問題も含めて分かっておいたほうが、では、これは容積率にとらわれないでどういうふうにしていこうとか、そういうことが必要なのかなとある程度思っている。そういうお願いをするときは必ずあるので、そのときにそういうものがあればありがたいと思っているので、最後のその資料的なものが大丈夫かどうかというところだけ、確認させてください。","respondent":"東野経理課長","answer":"基本計画を進めていく段階で、様々な他自治体などからも建設時の資料なども入手いたしまして、どういったものが必要かという部分の検討材料としていきたいと考えています。","id":"exchange-016"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"先ほどから出ていますけれども、職員の休憩スペースというのは必要かと思います。庁舎ですから、やはり区民の財産でもあり、区民の方が利用に訪れるということですので、そういった広く知らせていくことがぜひ必要だと思いますけれども、いかがでしょうか。その数でいいのかと。ぜひもっと、この電子意見フォームの点でも知らせていただきたいと思いますけれども、いかがでしょうか。","respondent":"東野経理課長","answer":"こちらをご覧いただいている方がまずどれだけいるか、それに対してどう考えているかという部分ですが、確かに日程的なところもありますが、これまでの策定委員会の検討状況なども踏まえまして。","id":"exchange-017"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"全体を一遍に理解するのもなかなか難しいので、区民の皆さんにも分かるように、ぜひやっていただきたいと思いますけれども、改めてありましたら、伺いたいと思います。所有していた土地から減るということになりますが、今回この区有地の減歩率というのはどのくらいになるのか、つまり拠出をしてどれくらい減るのかということなのですが、いかがでしょうか。","respondent":"東野経理課長","answer":"改めて説明会をですが、繰り返しになりますが、こういったコロナ禍の状況を見ながら、区として進めるべきところで進めてまいりたいと思います。候補地に関して減歩率といいますか、それにつきましては、土地区画整理事業の中で行われているものです。","id":"exchange-018"},{"speaker":"のだて副委員長","kind":"質問","question":"今、把握していないということです。そして、今回、一般質問でも質問をさせていただきましたけれども、以前現庁舎が３６億円かけて耐震工事を行って、あと１６年もつということで、拙速に進めるべきではないということで、中止すべきだということで質問をいたしました。その耐震化した庁舎で万全でない事態というのはどういった事態なのか、伺いたいと思います。","respondent":"東野経理課長","answer":"１６年もつ耐震化をしているという状況ですが、万全でないといいますのは、特に設備面は５０年以上経過してかなり老朽化している状況です。","id":"exchange-019"},{"speaker":"のだて副委員長","kind":"質問","question":"設備面が万全ではないということなのですが、これ、災害が起きたときに万全ではないということの意味かと思ったのですが、そうではない、日常的に万全ではないということですか。","respondent":"榎本総務部長","answer":"答弁したのは私ですから私が答えますけれども、あの当時の耐震基準でいけば、耐震基準を十分満たしているという基準でやっていますけれども、例えば東日本大震災が直下型で来た場合に、それが万全であると言えるかどうかというのは、災害の想定規模が。","id":"exchange-020"},{"speaker":"のだて副委員長","kind":"質問","question":"確かにこの間、災害規模が激甚化している、地震も強くなってきているのかという印象がありますけれども、そうすると、庁舎だけでなくて、ほかの区有施設も耐えられるのかというところがあると思うのです。実際、区有施設で、そういった東日本大震災のような地震が来た場合、耐えられる施設というのはどれだけあるのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"やはりこうした区民の生活を支援していくということが今必要であって、拙速にこの新庁舎建替えを進めていくべきではないと思います。今回４００億円の事業費がかかるということで、こうした税金は、区民生活を支援していくことに充てるべきだと思いますけれども、いかがでしょうか。一旦立ち止まって、やはり広く区民に内容を知らせて、改めて検討することを求めます。いかがでしょうか。","respondent":"東野経理課長","answer":"区の庁舎は、大分老朽化が進んでいる状況なども踏まえまして、計画のほうは着実に進めていきたいと考えています。","id":"exchange-022"}]},{"id":"topic-02","title":"旧第一日野小学校跡地の状況","agenda":"旧第一日野小学校跡地の状況","exchanges":[{"speaker":"のだて副委員長","kind":"質問","question":"今回、ＴＯＣと協定を交わしたということで、この協定の内容というのは記載のある３点だけなのかということと、あと今回、金額１７億円の寄附ということですが、これはどういった根拠で決めたのかということと、今、区の中でこれをどう使っていくというお考えがあれば、伺いたいと思います。","respondent":"佐藤企画調整課長","answer":"４つ目の本格活用につきましては、仮移転で今後しばらく使いますので、その間、行政需要や地域のお声を聞いて、今後検討してまいります。","id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/121451?Template=document&Id=6116#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":25424,"voices":69}},{"id":"r03-20210927-19","meetingId":"r03-cm09","date":"2021年9月27日","dateIso":"2021-09-27","committee":"災害・環境対策特別委員会","time":"午前１０時００分～午後 ０時０３分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"おくの委員","kind":"確認","question":"そのサーマルリサイクルが、この減少率が年々鈍化したことの１つの要因になったのかなと、私なんかは思ったりもしたのですけれども、そこら辺はいかがでしょうか。","respondent":"品川品川区清掃事務所長","answer":"サーマルリサイクルの実施ですけれども、これについては、大体平成２０年度頃から始めているというところであります。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"それもあるのだろうなと思います。そういう意味で、サーマルリサイクルというのは、ごみを増やす方向で働いているということと、それから、二酸化炭素をやはり増やす方向で働いているという意味で、ごみについてサーマルリサイクルをやるというのは、少し考え直したほうがいいのではないかなと私は思うのですけれども、その点、どうお考えになられますか。伺いたい。","respondent":"品川品川区清掃事務所長","answer":"ただ、委員がおっしゃるとおり、燃やしますので、こういったあたりで、昨今非常に注目されているＣＯ２が出るというところについては、やはり今後、改善していかなければいけないところではあるかと考えております。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"ごみの元になるものがなければ一番いいので、これについて、前回頂いた資料では、特に区民事業者に発生抑制について積極的に働きかけを行っていきますと書いてあるのですが、これをどうやるかが非常に大事だと思うのですが、この働きかけという点についてはどのようなことをやられているのか、この点もお伺いしておきたいと思います。いかがでしょうか。","respondent":"品川品川区清掃事務所長","answer":"ごみの発生抑制ですが、こちらについては、細かいところを言えば、今たくさん、リサイクルの事業を行っております。やはりこういったリサイクルの事業については、基本的に全て発生抑制効果につながっているものと考えています。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"心から納得して持ってもらうような努力、なるほどな、こうやったらという、心から納得して持ってもらうような努力というのを、やっていかなければいけないと思うのですけれども、そこら辺の努力が、私たちというか、行政の側、政治の側に、ここのところ少し足りなかったのではないかと思うのですけれども、そこら辺いかがでしょうか。","respondent":"品川品川区清掃事務所長","answer":"そういう段階のところで、分別できないということで漏れてしまえば、その分はやはりリサイクルできないということになってしまうので、分別がしっかりと適正にできていれば、リサイクルする量も増えていくという効果があるので、やはり分別を進めているというところはあります。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問・要望","question":"本当にそのとおりだと思います。本当に今、いい情勢だと思うのです。むしろ、これは本当に私たちが生きていくために大事なことですから、ごみを減量していく、環境を守っていくということは、それはもう誰もが納得するような話なのですから、心から納得するような手段で、分別、リサイクル、あるいはリデュースということをやっていただきたいと思いますけれども、いかがでしょうか。","respondent":"品川品川区清掃事務所長","answer":"ごみの出し方についても、一部やはり無料にするために何か違ったことをやってくるとか、そういうことが考えられるのかなというところで、非常に有料化については、いい面もありますし、悪い面もあるというところで、こういったところをどのように考えるかをやはり検討しながら。","id":"exchange-005"},{"speaker":"おくの委員","kind":"質問・要望","question":"とにかくごみを減量する、そして環境を守る、自分たちが生きていく社会の環境を守るという目的自体は、本当に誰もが納得できるものなのですから、それに向かっていく、目的を納得していただくということで、その手段もみんなが納得できるというところで、進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"最初に１の表の言葉の確認なのですが、このごみの量というのは、資源とごみ、生ごみとか燃えないごみを含めたごみ全体の中の、資源化が可能なものを除いた量というふうに読んでよろしいのでしょうか。そう聞いたのですが、確認です。現在、まだ私から見るに、資源にしていいものがあると思うのですが、その辺の割合も、今もし分かるようでしたら教えてください。","respondent":"品川品川区清掃事務所長","answer":"それで、その中で、要するに資源化、リサイクルできないかということで、いろいろと研究されているものもあります。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問","question":"ありがとうございました。そうすると、令和４年度の資源化率が３１％となっています。ですが、国のプラスチック資源循環促進法は、もう来年から施行になるではないですか。それを、３１％でも大変かなと思うのですけれども、この法律ができて、この法律を守りながらとなると、いろいろ区として工夫が必要だと思うのですけれども、その辺のことはどのようにお考えでしょうか、伺いたいと思います。","respondent":"品川品川区清掃事務所長","answer":"ほかのものでも、何か今、可燃ごみ、不燃ごみになっているものでリサイクルできるものはないかというところは、随時そういった情報等は、他の自治体なども参考にしながら探していって、資源化率を高めていきたいと考えております。","id":"exchange-008"},{"speaker":"吉田委員","kind":"質問・要望","question":"啓発はとても大事だと思いますので、ぜひいろいろ工夫していただきたいと思います。これはなかなか厳しいです。ただ今後は、全部、製品プラスチックについても一括して回収して、リサイクルすることが求められている法です。その辺はやはり今からきちんと計画を立てておかないと、厳しいのではないでしょうか。その辺について、今、現段階でどのようにお考えか、伺いたいと思います。","respondent":"品川品川区清掃事務所長","answer":"大きく考えますと、プラスチック製品がリサイクルに回るというところを考えれば、現在、数値で示しております例えば令和２年度で見ますと、ごみ量としては７万７,０００トン、資源としては大体２万５,０００トンぐらいになっておりまして。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問・要望","question":"これはこれから施行される法律の話ですので、まだまだここだけで全部解決できることではないと思いますが、やはり先ほどの区民への啓発は、もちろん続けていただきたいと思います。それから、事業者への啓発、特に区内の事業者への啓発を進めていただきたいです。事業者も相当な義務を負います。ほかから入ってきてしまう可能性はありますけれども、区内では出さない。はまた機会を改めて伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"たけうち委員","kind":"質問・要望","question":"一方で、お店等は、なかなか飲食店が、居酒屋さんを中心に、営業をやらないところが増えたので、事業系のほうは減っているのかなという気がするのですが、何かその辺の、この７万７,０００トンのうち、もし分かれば、事業系がこれくらいで、これぐらい減っていますと、一方で、家庭のほうはこれだけ増えて、トータルでこうなりましたというのが分かれば、教えていただきたいのと、あと。","respondent":"品川品川区清掃事務所長","answer":"ただ、段ボール等のリサイクルについては、国内でも非常に需要がありますので、そういった部分については、いろいろと引取り等もスムーズに行ったりということは、動いているという状況です。","id":"exchange-011"},{"speaker":"たけうち委員","kind":"質問","question":"分かりました。事業系は、数は出ないけれども減っているだろうと。分かりました。区でどうこうできる話ではないと思うのですが、そういう影響なのか分からないですが、資源の新聞とか、それから古紙類の持ち去りが相変わらずあるとは思うのですが、私の周りだけなのかもしれないですが、何か一時より減ったような気がするのですが、その辺の状況が分かれば教えてください。","respondent":"品川品川区清掃事務所長","answer":"傾向としては、やはり同じ方が引き続き続けているかなという傾向がありますので、引き続きパトロールを重視して、持ち去り等を防ぐようにしていきたいと考えています。","id":"exchange-012"},{"speaker":"たけうち委員","kind":"質問","question":"もし分かればですが、戸越公園に環境学習交流施設ができますよね。そこに、この資源とか清掃・リサイクル関係の何か、さっき意識啓発とかいろいろありましたが、そういったブースを作るとか、何かそういう展示など、まだ決まっていないかもしれないけれども、何か予定されているのか、入るかどうかというのを教えてください。","respondent":"河内環境課長","answer":"子ども向けの展示内容の中に、清掃・分別をゲーム感覚で学習できるようなコンテンツが含まれておりまして、資源が流れてくれば資源のほうに、ごみであればごみのほうにというところで、そういったものの啓発に努めながら、子どもの時代から２０３０年、２０５０年に向けまして。","id":"exchange-013"},{"speaker":"こんの委員","kind":"確認","question":"細かいところを１点だけ、確認させてください。先ほどのご説明の中で、いわゆる生ごみの水切りの問題で、簡単に水切りができるグッズを配布したようなお話をされていましたが、これはいつ頃どんなふうに配布されて、現状それを配布されているのか、その点を１点教えてください。","respondent":"品川品川区清掃事務所長","answer":"仕組みとしましては、洗濯ばさみのような構造で、生ごみをそこに挟んでぎゅっと押して水分を取るという仕組みの、ごく単純なものですので、もしかしたらですが、例えばいわゆる１００円ショップだとか、そういったところに売っているようなものではないかなとは思っております。","id":"exchange-014"},{"speaker":"こんの委員","kind":"質問","question":"その意識を持ってもらえる方を１人でも多く増やす。そうしたことを考えたときに、こうしたいいことをしているのを、今はされていないということなので、何かそうした啓発で、具体的に行動を起こさせるものをと考えるのですが、いかがでしょうか。","respondent":"品川品川区清掃事務所長","answer":"委員からお話があったように、１つのグッズという形で、目に見えるもので……、書面上でも目には見えるのですが、いろいろとそういう道具によってリサイクル意識を変えるというところも、一つ大切なところではないかと思いますので。","id":"exchange-015"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひお願いしたいと思います。マイバッグの例も、当初、いろいろなところで頂いたりしながら、あのときも意識を高めていったなと。今、大分マイバッグを持ってお買い物をする人が、本当に増えたなと。袋の有料化というところもあったのでしょうけれども。やはりそうした啓発を、ぜひ工夫していただきたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"これは本当に一部分なのですが、それから、プラスチックなんかも、プラスチックそのものをなくしていく、何かに代用できるというところの、そういうふうな、何というのですか、大本から変えていくというのがすごく大事なのではないかと思うのですが、区として事業所系ごみの発生抑制に対しても推進しているというのが、基本方針の中に書かれているのですが、これは具体的に。","respondent":"品川品川区清掃事務所長","answer":"こういったところで、国の法律はこういう動きもありますので、そういうところと連携しながら、法律がこういうふうにできましたという啓発も、やはり自治体として行っていかなければいけないところではないかなと考えていますので、そういった部分で。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここでもかなり、目標そのものを、２０３０年に向けた主要目標で、一般廃棄物のリサイクル率を３７％とか、プラスチック対策で、ワンウェイプラスチックを累積２５％削減とか、食品ロス発生量を２０００年度比で５０％削減とか、具体的な数値目標を東京都でも立てていると思うのですが、この東京都の目標と品川区のそういう施策とがどういうふうに関連してくるのかというところも。","respondent":"品川品川区清掃事務所長","answer":"ただ、それが実際にリサイクル率に影響しているかどうかというところは、はっきりと私も調べていないところでありますので、こういう高い自治体等があれば、またいろいろと参考にしながら勉強していきたいと、このように考えております。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"有料化は、やめていただきたいと考えています。ごみの発生抑制というところでは、事業者の責任というのも、しっかりと製造者責任を問うということが、大本にはすごく大事だと思っています。本当に意識するのとしないのとで、ごみの量というのは全然変わってくる部分がありますので、そういう点での啓発も含めて、ごみ減量にこれからも取組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問・要望","question":"もうその辺は、調査結果が出たらお届けしますが、明らかです。ですから、先ほどは途中で止めましたが、やはりその辺の意識というのも今後、プラスチックの問題もありますけれども、ぜひ自分たちの焼却・最終処分場まで含めたことを全体で品川区としても捉えないと、少しこの目標とかは厳しいのかなと考えていますので、ぜひその辺、きちんとやっていただきたいです。意見だけ述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]},{"id":"topic-02","title":"リサイクルショップ「リボン」の閉店","agenda":"リサイクルショップ「リボン」の閉店","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"このリサイクルショップ「リボン」の大井町店は、第三庁舎の下なので区の建物ですけれども、旗の台店のほうは、民間のところを区が借り上げているという形になっているのでしょうか。具体的にこの「リボン」に対して、区として、財政的支援も含めてどのようにされてきたのかを伺いたいと思います。それから、どれぐらいの実績があったのか、そこら辺のところも教えていただけたらと思います。","respondent":"品川品川区清掃事務所長","answer":"それで、基本的に家賃は、大井町、それから旗の台、両方とも免除という形で行っております。それから、ざっとですけれども、補助金等を年間大体４００万円ぐらい、それから、建物等の小破修繕などもトータルで含めて、ほかに４００万円という形で支援をしています。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そうすると、補助金としては年間、区から約８００万円ぐらいの補助金が出ていて、そして、リサイクルショップ「リボン」としての売上げは、年間７万円ぐらいしかないという……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"７万件。分かりました。では、職員の経費というのは７万件のところで賄われ……。そこら辺の、何というのですか、財政支援と収支のバランスというか、そこら辺だけ分かる形で教えてください。","respondent":"品川品川区清掃事務所長","answer":"すみません。少し訂正をさせてください。販売件数としましては、平成２９年から３０年ぐらいまでは大体７万件ぐらいあったのですが、今、コロナの関係等で少し件数が減っておりまして、現在のところ、大体５万件ぐらいの販売件数となっています。","id":"exchange-023"}]},{"id":"topic-03","title":"品川区強靱化地域計画（素案）","agenda":"品川区強靱化地域計画（素案）","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"具体的にどういう実績があるところにどの辺まで委託しているのかということと、そのときに、内閣府でその計画を立てる前に、何かチェックリスト、自治体としてチェックをして、それから計画を立てるというシナリオで、リストが出ていたと思うのですが、それが、この辺の脆弱性の評価というところに生きているのか、その辺についても伺いたいと思います。","respondent":"山本防災課長","answer":"１点目の委託事業者についてですが、こちらは、入札で事業者を選定しておりますが、その要件として、地方公共団体を発注元とした国土強靱化地域計画策定支援業務を、これまでに実績があるものというところで指定をしています。","id":"exchange-024"},{"speaker":"吉田委員","kind":"質問・要望","question":"委託内容については、また後でお問い合わせします。具体的なところを委託するというのは了解ですけれども、その辺のことについて、これからパブリックコメントということですけれども、そもそも自分たちの弱みというか、そういうところの意見の参加とかは全然考えなかったのか、その辺について伺いたいと思います。ぜひそのように進めていただきたいと思います。改めて何かお考えがあれば伺います。","respondent":"山本防災課長","answer":"他の自治体との連携の部分ですが、確かに河川の氾濫等、広域的な避難というところも、もしかしたらあるかもしれないというところで、今後、区といたしましても、日頃の災害対策等につきまして、関係自治体というか、近隣の自治体との連携というのは強めていきたいと考えています。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"この品川区強靱化地域計画ですが、予算には組まれていたと思うのですが、それで、また予算特別委員会の中でも何人かからは発言があったと思うのですが、でも、こういう形でつくっていきますとか、策定委員会はこういうメンバーでやりますとかの報告が全くなかったので、私は今回、突然素案が出てきたという、そんな思いをしているのですけれども、策定委員会はどういう形でされたのか、策定委員のメンバーと。","respondent":"山本防災課長","answer":"策定委員会のメンバーですが、部長級の職員１２名で構成しています。会議ですが、４月のキックオフから始めまして、これまで３回、検討委員会を開催しまして、プラス１回、書面での開催というのを行っているところです。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この計画そのものは国の国土強靱化基本法に基づいてということで、この計画を品川区でもつくるということになったと思うのですが、これができているのは、平成２５年の１２月に基本法ができて、平成２６年の６月に国のほうでは基本計画ができているわけですけど、この品川区で今回こういう形で計画がつくられたというのは、なぜ今なのか、それから、もう既に２３区の中でも。","respondent":"山本防災課長","answer":"検討会の具体的な中身になりますが、まず４月にキックオフ会議を行いまして、この計画策定の目的等を委員の皆さんに共有を図ったところです。その後５月に、まず原案を事務局で策定しまして、その原案の確認の会議というのを行ってあります。","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ただ、国の国土強靱化基本法という法律そのものが、そういうことも言いながら、巨大開発の復活・拡大を進める根拠ということにもなっていますので、共産党としては、大本のところは反対をした法律なのですが、そういうところでは、災害に対しての対策というのはすごく大事なことなので、それはぜひ具体化を進めていただきたいと考えています。","respondent":"山本防災課長","answer":"強靱化地域計画の位置づけというお話かと思いますけれども、こちらについては、他の個別の計画と上位、下位という関係ではなくて、あくまでもそれぞれ個別で進めている計画を体系的にまとめた計画というところで、それぞれの計画と整合・調和を取りながら。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私が聞いたのは、そういう開発を進める事業者が、区としてこういう計画があって、それに基づいて行っているということで説明に使われる、そういう計画になっていくのではないか、マスタープランと同列に、そういうことになっていくのではないかということで伺ったのです。だから、開発を進めることにもつながっていく、そういう計画になるのではないかということで伺ったのですが、いかがでしょう。","respondent":"藤田防災まちづくり部長","answer":"そういう意味で、まちにある今の課題、例えば木密地域であればその木密地域を改善する、そのためのまちづくりを進めるべきだということを、強靱化地域計画の中で、事前防災として行っていくべき考え方を示しているものです。","id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これからパブリックコメントで区民の意見を聞いていきますということで言われますが、そうであれば、私は、こういう脆弱性の評価にしても、それから、どういう対策を取ってもらいたいかという、具体的に本当に災害に備えていくのであれば、説明会を開いて地域の意見を聞く、そういう場をぜひつくっていただきたいと思うのですが、いかがでしょうか。","respondent":"山本防災課長","answer":"脆弱性の評価等、区民のご意見をいただくですが、当然、区としても区民のご意見をいただきながら、施策に反映するというのは非常に重要だと考えていますので、これから行っていくパブリックコメントをしっかり周知して行いながら、様々な意見を集約して。","id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今までであれば、もっと議会にも報告があって、こういう形で策定委員会をつくって、こうやっていきますという報告があって、それで、策定委員会も公開で行うということでされてきたと思うのですが、そこのところが、今回は全くそういう説明もなく、なぜ素案という形でぼんと出てきたのか、なぜ外部委員も入れた公開された策定委員会にしなかったのか、その点についてもお聞かせいただきたいと思います。","respondent":"山本防災課長","answer":"議会への報告ですが、計画の策定自体は、６月の建設委員会で事務事業概要のご説明を差し上げたときに、今年度、こういった計画をつくっていくというところのご説明を、差し上げたところです。","id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、この計画は「大規模自然災害等に備えるため、事前防災・減災と迅速な復旧復興に資する施策」ということであるわけですから、これは住民参加で、住民の実態を踏まえた形で、開かれた形で計画を組んでいただきたかったし、また、計画というのはそういう形で、ぜひとも今後に向けて組んでいただきたいということで、要望をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"たけうち委員","kind":"質問","question":"１枚目の、１の（２）の計画期間、令和４年度から令和１１年度の８か年とありますが、これは、この計画ができて、ここに出ている３７項目ですか、これについて、既に取組んでいるものとか、既にできつつあるものもあると思うのですけれども、それが完了すると、いわゆる脆弱性がこの３７項目については達成できるよ、なくなるよというのが、令和１１年度がお尻と、こういう考え方でいいのですか。","respondent":"山本防災課長","answer":"計画につきましては、令和１１年度までということを予定していますが、おっしゃるとおりで、それまでにこちらの対応方策を一定進めながら、課題解決に向けて取組むというところが、計画の期間の設定となっています。","id":"exchange-033"},{"speaker":"たけうち委員","kind":"確認","question":"素案の一番後ろのページに、この計画の進捗管理というのがＰＤＣＡサイクルで載っていますけれども、このチェックのところに重要業績指標（ＫＰＩ）というのがあるのですが、なかなか聞き慣れない言葉、私だけかもしれないですが、もう少しこの重要業績指標（ＫＰＩ）ということについて、これによって確認するとなっているので、もう少し分かれば詳しく教えてもらいたいのと、これによって評価して。","respondent":"山本防災課長","answer":"基本的には１年度ごとの数値をつくっていきたいと思っているところです。それから、評価をどう皆様にお見せできるかというところですが、このあたりについては今検討しているところでございまして、また別途ご報告できればと考えています。","id":"exchange-034"},{"speaker":"たけうち委員","kind":"質問・要望","question":"分かりました。そうすると、１年ごとにできればというお話だったのですが、これは要望になってしまいますが、このまとめる重要なもの、全部重要なのかなとこちらとしては思ってしまうので、できるだけ多くやっていただくとともに、こういう決算特別委員会等の時期には出していただけると、非常にまた質疑が深まっていくのかなと思うので、これは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/298227?Template=document&Id=6602#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":34924,"voices":98}}]);
